/**
 * 9amLeads Production API Server
 * Handles: Auth, Customers, Leads, Delivery, Subscriptions
 * Database: SQLite (upgrade to PostgreSQL via .env)
 * 
 * Run: node production_api_server.js
 * Port: 8012
 */

const express = require('express');
const cors = require('cors');
const rateLimit = require('express-rate-limit');
const bcrypt = require('bcryptjs');
const jwt = require('jsonwebtoken');
const path = require('path');
const fs = require('fs');
const { v4: uuidv4 } = require('uuid');
const cron = require('node-cron');

require('dotenv').config();

// ===== CONFIG =====
const PORT = process.env.PORT || process.env.API_PORT || 8012;
const JWT_SECRET = process.env.JWT_SECRET || '9amLeads-Production-JWT-Secret-2026!';
if (!process.env.JWT_SECRET) console.log('[CONFIG] JWT_SECRET not set. Using hardcoded fallback.');
const DATA_DIR = (function() {
  var d = path.join(__dirname, 'data');
  if (!fs.existsSync(d)) {
    var alt = path.join(__dirname, '..', 'mission control', 'data');
    if (fs.existsSync(alt)) d = alt;
  }
  return d;
})();
const DB_FILE = path.join(DATA_DIR, 'database.json');
const PUBLIC_URL = process.env.PUBLIC_URL || 'https://www.9amleads.com';

// Postcode district data
const POSTCODE_DISTRICTS_FILE = path.join(DATA_DIR, 'uk-postcode-districts.json');
const POSTCODE_AREAS_FILE = path.join(DATA_DIR, 'uk-postcode-areas.json');
const POSTCODE_ASSIGNMENTS_FILE = path.join(DATA_DIR, 'postcode-assignments.json');

// Postcode district limits per plan — unlimited for all (any customer can add any postcode)
const POSTCODE_LIMITS = {
  free_trial: 5,
  essential: 5,
  starter: 5,
  pro: 999,
  enterprise: 999
};

function loadPostcodeDistricts() {
  try { return JSON.parse(fs.readFileSync(POSTCODE_DISTRICTS_FILE, 'utf-8')); }
  catch { return {}; }
}

function loadPostcodeAreas() {
  try { return JSON.parse(fs.readFileSync(POSTCODE_AREAS_FILE, 'utf-8')); }
  catch {
    // Fallback: built-in area list
    var areaCodes = 'AB,AL,B,BA,BB,BD,BH,BL,BN,BR,BS,BT,CA,CB,CF,CH,CM,CO,CR,CT,CV,CW,DA,DD,DE,DG,DH,DL,DN,DT,DY,E,EC,EH,EN,EX,FK,FY,G,GL,GU,GY,HA,HD,HG,HP,HR,HS,HU,HX,IG,IM,IP,IV,JE,KA,KT,KW,KY,L,LA,LD,LE,LL,LN,LS,LU,M,ME,MK,ML,MN,MS,N,NE,NG,NL,NN,NP,NR,NW,OL,OX,PA,PE,PH,PL,PO,PR,RG,RH,RM,S,SA,SE,SG,SK,SL,SM,SN,SO,SP,SR,SS,ST,SW,SY,TA,TD,TF,TN,TQ,TR,TS,TW,UB,W,WA,WC,WD,WF,WN,WR,WS,WV,YO,ZE';
    var areas = {};
    areaCodes.split(',').forEach(function(code) {
      areas[code] = { code: code, name: code, region: '' };
    });
    return areas;
  }
}

function loadAssignments() {
  try { return JSON.parse(fs.readFileSync(POSTCODE_ASSIGNMENTS_FILE, 'utf-8')); }
  catch { return { assignments: {} }; }
}

// On startup: ensure required data files exist on persistent disk
try {
  if (!fs.existsSync(DATA_DIR)) fs.mkdirSync(DATA_DIR, { recursive: true });
  // Copy default data files from source if not present on persistent disk
  var sourceDataDir = path.join(__dirname, 'data');
  if (!fs.existsSync(sourceDataDir)) sourceDataDir = path.join(__dirname, '..', 'mission control', 'data');
  ['uk-postcode-areas.json', 'uk-postcode-districts.json', 'postcode-assignments.json', 'stripe-config.json'].forEach(function(fn) {
    var targetPath = path.join(DATA_DIR, fn);
    var sourcePath = path.join(sourceDataDir, fn);
    if (fs.existsSync(sourcePath) && (!fs.existsSync(targetPath) || fn === 'stripe-config.json')) {
      fs.copyFileSync(sourcePath, targetPath);
      if (fn === 'stripe-config.json') console.log('[BOOT] Updated stripe-config.json');
      else console.log('[BOOT] Copied ' + fn + ' to persistent disk');
    }
  });
} catch(e) { console.log('[BOOT] Data file setup:', e.message); }

try {
  var startupDb = JSON.parse(fs.readFileSync(path.join(DATA_DIR, 'database.json'), 'utf-8'));
  var beforeCust = (startupDb.customers || []).length;
  var beforeLeads = (startupDb.leads || []).length;
  startupDb.customers = (startupDb.customers || []).filter(function(c) { return c.source !== 'demo-migration'; });
  startupDb.leads = (startupDb.leads || []).filter(function(l) { return l.customer_id && startupDb.customers.some(function(oc) { return oc.id === l.customer_id; }); });
  if (beforeCust !== startupDb.customers.length) {
    fs.writeFileSync(path.join(DATA_DIR, 'database.json'), JSON.stringify(startupDb, null, 2));
    console.log('[BOOT] Purged ' + (beforeCust - startupDb.customers.length) + ' demo customers + ' + (beforeLeads - startupDb.leads.length) + ' leads');
  }
} catch(e) { console.log('[BOOT] Startup purge check:', e.message); }

function saveAssignments(data) {
  fs.mkdirSync(DATA_DIR, { recursive: true });
  fs.writeFileSync(POSTCODE_ASSIGNMENTS_FILE, JSON.stringify(data, null, 2));
}

function getPostcodeLimit(plan, extraPostcodes, product) {
  // Specialist types (planning, probate, tenders) use wider areas by default
  var specialistTypes = { planning: true, probate: true, tenders: true };
  if (product && specialistTypes[product]) {
    var rule = getLeadTypeRule(product);
    if (rule && rule.area_limit) {
      var limit = rule.area_limit[plan] || rule.area_limit.starter || 3;
      var extra = parseInt(extraPostcodes) || 0;
      return Math.min(limit + extra2, 999);
    }
  }
  const base = POSTCODE_LIMITS[plan] || POSTCODE_LIMITS.free_trial;
  var extra2 = parseInt(extraPostcodes) || 0;
  return base + extra2;
}

const EXTRAS_PRICE = 5000; // £50 one-time per extra postcode area

function normalisePostcodeForMatch(pc) {
  return pc.toLowerCase().replace(/[^a-z0-9]/g, '');
}

function isFullDistrict(code, districts) {
  return !!districts[code.toUpperCase()];
}



function extractPostcodeArea(postcode) {
  if (!postcode) return '';
  var s = String(postcode).toUpperCase().trim();
  // If the string contains a full postcode (possibly inside an address, e.g.
  // "16 Brick House 1a Faringdon Avenue, Romford, RM3 8SH"), extract it first.
  var m = s.match(/[A-Z]{1,2}[0-9][A-Z0-9]?\s?[0-9][A-Z]{2}/);
  if (m) s = m[0];
  var out = s.replace(/[^A-Z].*$/, '');
  return out.length >= 1 && out.length <= 4 ? out : '';
}

// Shared premise-identifier logic (delivery gate + dashboard filter): guarantees
// a delivered moving/probate lead always carries a door number, flat number,
// street number or house name — never a bare street/place name. See address_premise.js.
var ADDR_PREMISE = require('./address_premise');
var CURATED_BLOG = require('./curated_blog_posts');
var AFFILIATE_TOOLKIT = require('./affiliate_resources');
function hasUsablePremiseAddress(addr, pc) { return ADDR_PREMISE.hasUsablePremiseAddress(addr, pc); }

// Strip a leading DEFAULT/UNCONFIRMED "Flat 1" prefix from an address. UK portals
// (Rightmove etc.) hide exact flat numbers and default a flat listing's
// displayAddress to "Flat 1, <Building>, <Street>" when the real flat is unknown.
// For Print & Post we must NEVER mail to a guessed flat, so we strip that default
// and keep the accurate building-level address (e.g. "Flat 1, Collcutt Lodge, 4
// Ferndale Road" -> "Collcutt Lodge, 4 Ferndale Road"), which still passes the
// premise gate via the building number/name. Genuine higher flat numbers (Flat 3,
// Flat 4a, ...) are kept - only the default first-unit "Flat 1" is removed.
function stripGuessedFlatPrefix(addr) {
  return String(addr || '').replace(/^(?:Flat|Apartment|Unit|Maisonette|Penthouse)\s*1\b\s*[,.-]?\s*/i, '').replace(/^,\s*/, '').trim();
}
// True when the address is a flat/apartment (has a flat/unit/apt style identifier).
function isFlatAddress(addr) {
  return /(?:^|[\s,])(flat|apartment|unit|maisonette|penthouse|room)\s*\d/i.test(String(addr || ''));
}

// Strip WRONG REGION/COUNTRY tags that leak into addresses (e.g. "London, Wales",
// "Battersea, Scotland", "London, Greater London, SW11 3TY, Scotland"). A mail
// address = premises, street, town, postcode - region/country names don't belong
// and are frequently wrong (London is not in Wales). Removes standalone
// England/Scotland/Wales/N.Ireland + the English region names + Greater London
// + trailing "UK".
function stripRegionTags(addr) {
  return String(addr || '')
    .replace(/(?:^|,\s*)(?:England|Scotland|Wales|Northern\s*Ireland|South\s*East\s*England|South\s*West\s*England|East\s*of\s*England|East\s*Midlands|West\s*Midlands|North\s*West\s*England|North\s*East\s*England|Yorkshire\s*and\s*the\s*Humber|Greater\s*London|UK)(?=\s*,|\s*$)/gi, '')
    .replace(/,\s*,/g, ',').replace(/^\s*,/, '').replace(/\s*,\s*/g, ', ').replace(/\s{2,}/g, ' ').trim();
}

// Reject new-build DEVELOPMENT UNIT CODES in addresses (e.g. "L-001226, 8 Circus
// Road West", "N-0123, ...", "Plot 12, ...", "Unit 12a, ..."). These are plot/unit
// references from new-build marketing, NOT real mail addresses - never deliver them.
function hasBadUnitCode(addr) {
  var a = String(addr || '').trim();
  if (!a) return false;
  if (/^\s*(?:plot\s+\d+[a-z]?|unit\s+\d+[a-z]?|[a-z]{1,4}-\d{3,})\b/i.test(a)) return true;
  if (/,\s*(?:plot\s+\d+[a-z]?|unit\s+\d+[a-z]?|[a-z]{1,4}-\d{3,})\b/i.test(a)) return true;
  return false;
}

// EXACT-DATA GUARANTEE: reject placeholder/mock pool entries so a customer can
// never receive a fake lead (e.g. a leftover seed file with "Tender 0"/"Buyer"/
// "Works" rows, or an address-less stub). Applied at pool-load time, so EVERY
// delivery pass (round 1/2, pool-file fallback, final-guarantee, top-ups) only
// ever sees real data. Conservative on purpose — a real lead with a URL and a
// title/name/address/reference always passes.
function isPlaceholderLead(l) {
  if (!l || typeof l !== 'object') return true;
  var s = JSON.stringify(l).toLowerCase();
  if (/placeholder|lorem ipsum|mock data|\btest\s+street\b|\b123\s+test\b|\bexample\.com\b|fake\s+lead|sample\s+data/.test(s)) return true;
  var id = String(l.id || l.url || '').toLowerCase();
  if (/^(tenders|probate|planning|newbusiness|moving)_\d+$/.test(id)) return true;
  // Generic seeded titles ("Tender 0", "Buyer", bare "Works") with no URL =
  // generated stub, not a real opportunity.
  var url = String(l.url || '').trim();
  var title = String(l.title || l.name || l.buyer || '').toLowerCase().trim();
  if (/^tender\s?\d+$/.test(title)) return true;
  if (title === 'buyer' || title === 'works' || title === 'tender') return !url;
  // A lead with NO url, NO title, NO address, NO reference and NO company is not
  // real data — it has nothing to show or verify.
  if (!url) {
    var reference = String(l.reference || l.proposal || l.applicationRef || l.tenderNoticeId || l.deceasedName || l.companyNumber || '').trim();
    if (!title && !reference && !l.address && !l.fullAddress && !l.deceasedAddress && !l.company && !l.name) return true;
  }
  return false;
}

// Remove a trailing PARTIAL postcode (outcode only, e.g. "London, WC2A" /
// "London, SW17") from an address string. The full postcode is stored separately
// in the postcode field - a bare outcode at the end of the address is redundant
// and makes the lead look incomplete.
function stripPartialPostcode(addr) {
  return String(addr || '').replace(/,\s*[A-Z]{1,2}[0-9][A-Z0-9]?\s*$/i, '').replace(/\s{2,}/g, ' ').trim();
}

// MOVING-LEAD ADDRESS NORMALISER: a moving lead's printable address must start
// with the DOOR/FLAT NUMBER + STREET (the mail address), not a building/company
// name. Scrapers often prepend "Aitchison Raffety, King House,", "Western Court,"
// or "Court ..." building names. Rules:
//   1) If a numbered street exists in the address ("55 Victoria Street"),
//      return the address STARTING at that street+number (drop the leading
//      building/company name). A "Court/Close" name with no number is dropped;
//      the numbered street is used instead.
//   2) Keep flat/apartment numbers ("Flat 1, ...", "Flat A, ...").
//   3) If there's no numbered street (bare building name), keep the address as-is.
function normaliseMovingAddress(addr) {
  var a = String(addr || '').trim();
  if (!a) return '';
  // 1) Numbered street: number + optional letter + street word (Road/Street/
  //    Avenue/Lane/Drive/Close/Court/Terrace/Way/Hill/Place/Mews/Grove/Gardens/
  //    Crescent/Row/Park/Square/Green/View/Gate/End/Field/Path/...).
  var numStreet = a.match(/(?:^|,\s*)((?:\bFlat\s*[0-9A-Za-z]+\b\s*,?\s*)?\d{1,5}[A-Za-z]?(?:[-\u2013]\d{1,5}[A-Za-z]?)?\s+[A-Z][A-Za-z'-]*(?:\s+[A-Z][A-Za-z'-]*){0,2}\s+(?:Road|Street|Avenue|Lane|Drive|Close|Court|Crescent|Gardens|Grove|Terrace|Way|Walk|Hill|Place|Mews|Rise|Row|Park|Square|Green|Broadway|Path|View|Gate|End|Field|Fields|High\s?Street|St|Rd|Ave|Ln|Dr|Ct|Tce|Gdns|Gv|Cl|Cres|Mws|Rse|Pk|Sq|Bdwy))\b/i);
  // Prefer a numbered street that is NOT just "Court"/"Close" without a number.
  if (numStreet) return numStreet[1].replace(/\s*,\s*/g, ', ').trim();
  // 2) Flat/apartment numbered prefix (no street found): keep flat part + rest.
  if (/^(?:Flat|Apartment|Unit|Maisonette|Penthouse|Room)\s*[0-9A-Za-z]+/i.test(a)) return a;
  // 3) No numbered street — return the address unchanged.
  return a;
}

// FINAL AUTO-REVIEW for a moving lead. Returns '' if the lead is complete and
// mail-ready, otherwise the reason it failed. EVERY moving lead must pass ALL of
// these before it can be emailed to a customer:
//   - has a full UK postcode (outcode + inward)
//   - has a door/flat number or single-premise building (premise gate)
//   - has a real street name
//   - has no wrong region tags (London, Wales / Battersea, Scotland / UK)
//   - has no trailing partial postcode (London, SW2)
//   - has no new-build unit/plot code (L-001226, Plot 12, Unit 12a)
//   - has a listing URL
//   - has no guessed "Flat 1" prefix
function validateMovingLead(ld) {
  var a = String(ld.fullAddress || ld.address || '').trim();
  var pc = String(ld.postcode || '').trim().toUpperCase();
  if (!a) return 'no-address';
  if (!pc) return 'no-postcode';
  if (!/^[A-Z]{1,2}[0-9][A-Z0-9]?\s?[0-9][A-Z]{2}$/.test(pc)) return 'incomplete-postcode';
  var pafRelaxed = process.env.PAF_RELAXED_PICK === 'true' || process.env.PAF_RELAXED_PICK === '1';
  var hasPremise = hasUsablePremiseAddress(a, pc);
  var streetOk = hasStreetName(a);
  if (!streetOk) return 'no-street-name';
  // PAF-RELAXED (PAF_RELAXED_PICK=true): a street-only lead with a full postcode is
  // a PAF candidate — the delivery PAF pass adds a door number to the EXACT leads
  // being sent. So accept it here (the final PAF pass still drops it if PAF can't
  // confirm a complete address).
  if (!hasPremise && !(pafRelaxed && streetOk)) return 'no-premise-number';
  if (hasPremise && !hasFullAddress(a, pc)) return 'incomplete-address';
  if (/,\s*(England|Scotland|Wales|Northern\s*Ireland|South\s*East\s*England|South\s*West\s*England|East\s*of\s*England|East\s*Midlands|West\s*Midlands|North\s*West\s*England|North\s*East\s*England|Greater\s*London|UK)(?=\s*,|\s*$)/i.test(a)) return 'wrong-region-tag';
  if (/,\s*[A-Z]{1,2}[0-9][A-Z0-9]?\s*$/i.test(a)) return 'partial-postcode';
  if (hasBadUnitCode(a)) return 'unit-code';
  if (!ld.url) return 'no-listing-url';
  return '';
}

// True when an address contains a real street name (a door number followed by a
// street word, OR a street suffix like Road/Street/Avenue/Lane/Close/...). Moving
// leads must carry street + number + area + postcode - a bare building name with
// no street (e.g. "Hazelwood House, Deptford") is NOT deliverable.
function hasStreetName(addr) {
  var a = String(addr || '').trim();
  if (!a) return false;
  if (/^\s*\d{1,5}[A-Za-z]?(?:[-\u2013]\d{1,5}[A-Za-z]?)?\s+[A-Z][A-Za-z'-]+/.test(a)) return true;
  // Word-boundary anchored so 'Court' never matches inside 'Courtenay'.
  return /(?:\bRoad\b|\bStreet\b|\bAvenue\b|\bLane\b|\bDrive\b|\bClose\b|\bCrescent\b|\bGardens\b|\bGrove\b|\bCourt\b|\bTerrace\b|\bWay\b|\bWalk\b|\bHill\b|\bPlace\b|\bMews\b|\bRise\b|\bRow\b|\bPark\b|\bSquare\b|\bGreen\b|\bBroadway\b|\bPath\b|\bView\b|\bGate\b|\bEnd\b|\bField\b|\bFields\b|\bHigh\s?Street\b|\bSt\b|\bRd\b|\bAve\b|\bLn\b|\bDr\b|\bCl\b|\bCres\b|\bGdns\b|\bGv\b|\bCt\b|\bTce\b|\bWl\b|\bPl\b|\bMws\b|\bRse\b|\bPk\b|\bSq\b|\bBdwy\b)/i.test(a);
}

// True when an address is COMPLETE for mailing: door/flat/house/apartment number
// + street name + a full postcode. A town/area is nice-to-have but NOT essential
// ("1 Caldwell Street, SW9 0HD" is acceptable). A bare street or building name
// with no number is NOT deliverable.
function hasFullAddress(addr, pc) {
  var a = String(addr || '').replace(new RegExp(String(pc || '').replace(/[.*+?^${}()|[\]\\]/g, '\\$&'), 'gi'), '').trim();
  if (!hasUsablePremiseAddress(a, pc)) return false;
  if (!hasStreetName(a)) return false;
  return /[A-Z]{1,2}[0-9][A-Z0-9]?\s?[0-9][A-Z]{2}$/i.test(String(pc || '').trim());
}

// ---- Capacity / usage telemetry (exposed on /api/health) ----
// Brevo daily send counter (1 email per customer per day). In-memory, reset on
// the UTC date rollover; good enough to watch the free-tier 300/day ceiling.
var _brevoSent = { date: '', count: 0 };
function bumpBrevoSentToday() {
  var d = new Date().toISOString().split('T')[0];
  if (_brevoSent.date !== d) { _brevoSent.date = d; _brevoSent.count = 0; }
  _brevoSent.count++;
}
function brevoSentToday() {
  var d = new Date().toISOString().split('T')[0];
  return _brevoSent.date === d ? _brevoSent.count : 0;
}
// Cached per-product fresh-pool supply (leads under 48h old), refreshed at most
// every 5 minutes so Render health checks don't re-parse the large pool files.
var _poolSupplyCache = { at: 0, data: null };
function getPoolSupply() {
  var now = Date.now();
  if (_poolSupplyCache.data && (now - _poolSupplyCache.at) < 300000) return _poolSupplyCache.data;
  var cutoff = getFreshCutoffIso();
  var out = {};
  var prods = ['moving', 'probate', 'newbusiness', 'planning', 'tenders'];
  for (var pi = 0; pi < prods.length; pi++) {
    var prod = prods[pi];
    var fn = path.join(DATA_DIR, PRODUCT_LEAD_FILES[prod] ? PRODUCT_LEAD_FILES[prod].file : (prod + '-leads.json'));
    var arr = [];
    try { var raw = JSON.parse(fs.readFileSync(fn, 'utf-8')); if (Array.isArray(raw)) arr = raw; else if (raw && typeof raw === 'object') Object.keys(raw).forEach(function(k){ if (k.indexOf('_') !== 0 && Array.isArray(raw[k])) arr = arr.concat(raw[k]); }); } catch(e) {}
    var fresh = 0;
    for (var i = 0; i < arr.length; i++) {
      var l = arr[i];
      var d = pickFreshDate(l); // freshness dateteSubmitted || l.incorporationDate || l.updateDate || l.createdAt || l.created_at || l.scrapedAt || '';
      if (d && d >= cutoff) fresh++;
    }
    out[prod] = { total: arr.length, fresh_48h: fresh };
  }
  _poolSupplyCache = { at: now, data: out };
  return out;
}

