// Given the customer's exact postcode areas, return the exact areas plus nearby
// areas in the same UK region(s), for use ONLY as a fallback when supply is short.
function expandedAreaFallback(areas) {
  var result = [];
  var map = {};
  // COUNTY-BASED CUSTOMERS (probate/planning/tenders use county names like "Kent",
  // "Greater London"): national supply for these products is thin (~27 probate
  // grants/day UK-wide), so when the exact county has no fresh lead the customer
  // would get NOTHING. Expand to cover ALL UK postcode areas (via the county map)
  // so they still receive their full promised count from the best available lead.
  var usesCounties = (areas || []).some(function(a) { return !/^[A-Z]{1,3}$/i.test(String(a).trim()); });
  if (usesCounties) {
    (areas || []).forEach(function(a) {
      var c = String(a).toLowerCase().replace(/[\s-]+/g, '-');
      // BROAD-REGION choice (e.g. "South England", "Scotland"): expand to every
      // postcode area in that region. Gives whole-region coverage for tenders etc.
      var regAreas = REGION_TO_POSTCODE_AREAS[c];
      if (regAreas) { regAreas.forEach(function(pc) { if (!map[pc]) { map[pc] = 1; result.push(pc); } }); }
      (COUNTY_POSTCODE_MAP[c] || []).forEach(function(pc) { if (!map[pc]) { map[pc] = 1; result.push(pc); } });
    });
    // ALSO include every other county's postcode areas as a broad fallback, so an
    // empty chosen county (e.g. "Devon" with no fresh grant today) still yields a
    // deliverable probate lead from the national pool. Kept LAST in the order so
    // exact-county leads are always preferred.
    Object.keys(COUNTY_POSTCODE_MAP).forEach(function(k) {
      (COUNTY_POSTCODE_MAP[k] || []).forEach(function(pc) { if (!map[pc]) { map[pc] = 1; result.push(pc); } });
    });
    return result;
  }
  (areas || []).forEach(function(a) {
    var c = extractPostcodeArea(a);
    if (!c || map[c]) return;
    map[c] = 1; result.push(c);
  });
  (areas || []).forEach(function(a) {
    var c = extractPostcodeArea(a);
    (REGION_NEIGHBOUR_AREAS[c] || []).forEach(function(n) {
      if (!map[n]) { map[n] = 1; result.push(n); }
    });
  });
  return result;
}

function validatePostcodes(postcodes, customerPlan, customerProduct, customerId, extraPostcodes) {
  const areas = loadPostcodeAreas();
  const assignments = loadAssignments();
  const maxLimit = getPostcodeLimit(customerPlan, extraPostcodes);
  const errors = [];

  if (!Array.isArray(postcodes)) {
    return { valid: false, errors: ['Postcodes must be an array'] };
  }

  if (postcodes.length > maxLimit) {
    const limitLabel = maxLimit >= 999 ? 'unlimited' : maxLimit;
    errors.push('Your ' + customerPlan + ' plan allows ' + limitLabel + ' postcode area' + (maxLimit !== 1 ? 's' : '') + '. You selected ' + postcodes.length + '.');
  }

  // MINIMUM 3 AREAS: every customer must choose at least 3 areas/postcodes so we can
  // deliver a steady daily supply. They can choose as many as they like — no upper
  // limit beyond their plan.
  if (postcodes.length < 3) {
    errors.push('Please choose at least 3 areas or postcodes so we can deliver a steady daily supply of leads. You can select as many as you like.');
  }

  for (const pc of postcodes) {
    const upper = pc.toUpperCase().trim();

    // Check if it's a valid postcode area (e.g., "EN", "SG", "CM")
    const matchedArea = getMatchingArea(upper, areas);
    if (!matchedArea) {
      errors.push('"' + pc + '" is not a valid UK postcode area. Use 1 or 2-letter codes like B (Birmingham), N (North London), EN (Enfield), SG (Stevenage), CM (Chelmsford).');
      continue;
    }

    if (upper.length < 1 || upper.length > 2) {
      errors.push('"' + pc + '" is not a valid UK postcode area code (use 1 or 2 letters like B, N, EN, SG, CM).');
      continue;
    }
  }

  return { valid: errors.length === 0, errors };
}

function claimPostcodes(postcodes, customerId, product) {
  const assignments = loadAssignments();
  for (const pc of postcodes) {
    const upper = pc.toUpperCase();
    if (!assignments.assignments[upper]) {
      assignments.assignments[upper] = {
        customer_id: customerId,
        product: product,
        assigned_at: new Date().toISOString(),
        status: 'active'
      };
    }
  }
  saveAssignments(assignments);
}

function releasePostcodes(customerId) {
  const assignments = loadAssignments();
  let changed = false;
  for (const [code, assignment] of Object.entries(assignments.assignments)) {
    if (assignment.customer_id === customerId) {
      delete assignments.assignments[code];
      changed = true;
    }
  }
  if (changed) saveAssignments(assignments);
}

