// ===== AUTOMATED DATABASE BACKUP (bulletproofing) =====
// The whole business (customers, leads, campaigns, payments) lives in database.json
// on Render's ephemeral disk. One bad deploy or disk reset = total data loss. This
// keeps a rolling local backup AND pushes it off-server to a private GitHub repo so
// data survives even if Render is destroyed. The GitHub token is the same one used
// to push code (read/write on the backup repo).
var BACKUP_DIR = path.join(DATA_DIR, 'backups');
var BACKUP_GITHUB_REPO = process.env.BACKUP_REPO || 'ketz1g/9amleads-backup';
var BACKUP_TOKEN = process.env.GITHUB_TOKEN || process.env.REPO_TOKEN || process.env.GH_PUSH_TOKEN || '';

function writeLocalBackup() {
  try {
    fs.mkdirSync(BACKUP_DIR, { recursive: true });
    var stamp = new Date().toISOString().replace(/[:T]/g, '-').substring(0, 19);
    var file = path.join(BACKUP_DIR, 'database-' + stamp + '.json');
    // Atomic-ish: write to temp then rename, so a crash mid-write never corrupts the backup
    var tmp = file + '.tmp';
    fs.writeFileSync(tmp, JSON.stringify(_dbData, null, 2));
    fs.renameSync(tmp, file);
    // Keep only the last 24 local backups (24h of hourly)
    var all = fs.readdirSync(BACKUP_DIR).filter(function(f) { return f.startsWith('database-') && f.endsWith('.json'); }).sort();
    while (all.length > 24) { fs.unlinkSync(path.join(BACKUP_DIR, all.shift())); }
    console.log('[BACKUP] Local backup written: ' + file);
    return file;
  } catch(e) { console.error('[BACKUP] Local backup error:', e.message); return null; }
}

function pushBackupToGitHub() {
  return new Promise(function(resolve) {
    try {
      if (!BACKUP_TOKEN) { resolve(false); return; }
      var content = JSON.stringify(_dbData, null, 2);
      var stamp = new Date().toISOString().replace(/[:T]/g, '-').substring(0, 19);
      var path = 'backups/database-' + stamp + '.json';
      // Use the GitHub contents API (create/update file)
      var d = JSON.stringify({ message: 'DB backup ' + stamp, content: Buffer.from(content).toString('base64'), branch: 'main' });
      var req = require('https').request({ hostname: 'api.github.com', path: '/repos/' + BACKUP_GITHUB_REPO + '/contents/' + path, method: 'PUT', headers: { 'Authorization': 'Bearer ' + BACKUP_TOKEN, 'User-Agent': '9amLeads', 'Content-Type': 'application/json', 'Content-Length': Buffer.byteLength(d) }, timeout: 30000 }, function(res) {
        var b = ''; res.on('data', function(c) { b += c; }); res.on('end', function() { if (res.statusCode < 300) { console.log('[BACKUP] Pushed to GitHub: ' + path); resolve(true); } else { console.log('[BACKUP] GitHub push HTTP ' + res.statusCode + ': ' + b.substring(0, 100)); resolve(false); } });
      });
      req.on('error', function(e) { console.log('[BACKUP] GitHub push error:', e.message); resolve(false); });
      req.setTimeout(30000, function() { req.destroy(); resolve(false); });
      req.write(d); req.end();
    } catch(e) { console.log('[BACKUP] GitHub push error:', e.message); resolve(false); }
  });
}

// Keep the newest N remote backups (delete older ones so the repo doesn't balloon)
async function pruneRemoteBackups() {
  try {
    if (!BACKUP_TOKEN) return;
    var req = require('https').request({ hostname: 'api.github.com', path: '/repos/' + BACKUP_GITHUB_REPO + '/contents/backups', method: 'GET', headers: { 'Authorization': 'Bearer ' + BACKUP_TOKEN, 'User-Agent': '9amLeads' }, timeout: 20000 }, function(res) {
      var b = ''; res.on('data', function(c) { b += c; }); res.on('end', function() {
        try {
          var items = JSON.parse(b);
          if (!Array.isArray(items)) return;
          items.sort(function(a, b2) { return (a.name || '').localeCompare(b2.name || ''); });
          // Keep newest 24
          while (items.length > 24) {
            var old = items.shift();
            var d2 = JSON.stringify({ message: 'Prune old backup', sha: old.sha, branch: 'main' });
            var del = require('https').request({ hostname: 'api.github.com', path: '/repos/' + BACKUP_GITHUB_REPO + '/contents/backups/' + old.name, method: 'DELETE', headers: { 'Authorization': 'Bearer ' + BACKUP_TOKEN, 'User-Agent': '9amLeads', 'Content-Type': 'application/json', 'Content-Length': Buffer.byteLength(d2) }, timeout: 20000 }, function(dres) { dres.resume(); });
            del.on('error', function() {}); del.write(d2); del.end();
          }
        } catch(e) { console.log('[BACKUP] Prune error:', e.message); }
      });
    });
    req.on('error', function() {}); req.end();
  } catch(e) {}
}

// Full backup: local + remote, then prune old remote.
async function runFullBackup() {
  try {
    var local = writeLocalBackup();
    await pushBackupToGitHub();
    setTimeout(pruneRemoteBackups, 2000);
    return local;
  } catch(e) { console.log('[BACKUP] Full backup error:', e.message); return null; }
}

// AUTO-RESTORE: if database.json is missing, corrupt, OR valid-but-stale (0 customers
// while backups have customers — a deploy reset the ephemeral disk), restore from the
// NEWEST backup that actually CONTAINS customers. Picking the newest file blindly is
// dangerous: a corrupt/small backup (0 customers) would be restored over good data.
function restoreDbFromBackup() {
  try {
    var curCust = -1;
    if (fs.existsSync(DB_FILE)) {
      try { var _cur = JSON.parse(fs.readFileSync(DB_FILE, 'utf-8')); curCust = (_cur && _cur.customers) ? _cur.customers.length : -1; } catch(e) { curCust = -1; }
    }
    var needsRestore = false;
    if (!fs.existsSync(DB_FILE)) needsRestore = true;
    else if (curCust < 0) needsRestore = true;
    else if (curCust === 0) {
      // Valid-but-empty: only restore if a backup has MORE customers (avoid restoring
      // a fresh legitimately-empty DB over a good backup, but DO restore a wiped DB).
      needsRestore = true;
    }
    if (!needsRestore) return false;
    console.log('[BACKUP] database.json missing/corrupt/empty (customers=' + curCust + ') — restoring from newest good backup...');
    var candidates = [];
    try { fs.mkdirSync(BACKUP_DIR, { recursive: true }); candidates = fs.readdirSync(BACKUP_DIR).filter(function(f) { return f.startsWith('database-') && f.endsWith('.json') && f.indexOf('CORRUPT') === -1; }).sort(); } catch(e) {}
    var _good = null;
    for (var _ci = candidates.length - 1; _ci >= 0; _ci--) {
      try {
        var _b = JSON.parse(fs.readFileSync(path.join(BACKUP_DIR, candidates[_ci]), 'utf-8'));
        if (_b && _b.customers && _b.customers.length > 0 && _b.customers.length > curCust) { _good = candidates[_ci]; break; }
      } catch(e) {}
    }
    if (!_good && curCust === 0) {
      // No backup beats an empty DB — take any non-empty backup.
      for (var _ci2 = candidates.length - 1; _ci2 >= 0; _ci2--) {
        try { var _b2 = JSON.parse(fs.readFileSync(path.join(BACKUP_DIR, candidates[_ci2]), 'utf-8')); if (_b2 && _b2.customers && _b2.customers.length > 0) { _good = candidates[_ci2]; break; } } catch(e) {}
      }
    }
    if (_good) {
      var gpath = path.join(BACKUP_DIR, _good);
      fs.copyFileSync(gpath, DB_FILE);
      _dbData = null; getDb();
      console.log('[BACKUP] Restored from good backup: ' + _good);
      return true;
    }
    if (curCust >= 0) return false; // DB is valid, just small — keep it
    console.log('[BACKUP] No local backup found — data may be lost.');
    return false;
  } catch(e) { console.log('[BACKUP] Restore error:', e.message); return false; }
}
function _q(sql, params) {
  // Parse SQL to determine operation
  const isSelect = sql.trim().toUpperCase().startsWith('SELECT');
  const isInsert = sql.trim().toUpperCase().startsWith('INSERT');
  const isUpdate = sql.trim().toUpperCase().startsWith('UPDATE');
  const isDelete = sql.trim().toUpperCase().startsWith('DELETE');
  
  // Extract table name
  const tableMatch = sql.match(/(?:FROM|INTO|UPDATE|DELETE FROM)\s+(\w+)/i);
  const table = tableMatch ? tableMatch[1] : null;
  
  return { table, isSelect, isInsert, isUpdate, isDelete, sql, params: params || [] };
}

function _exec(sql) {
  // Used for CREATE TABLE statements
  return { sql };
}

// Shims to match better-sqlite3 API
const db_shim = {
  prepare: (sql) => ({
    run: (...p) => _run(sql, p),
    get: (...p) => _get(sql, p),
    all: (...p) => _all(sql, p),
    raw: () => ({ all: (...p) => _all(sql, p).map(r => Object.values(r)) })
  }),
  exec: (sql) => _exec(sql),
  pragma: () => {}
};

function _run(sql, params) {
  const q = _q(sql, params);
  if (q.isInsert) {
    const row = {};
    const colsMatch = sql.match(/\(([^)]+)\)\s*VALUES/i);
    // Match the VALUES(...) block robustly: find '(' after VALUES and the matching ')'.
    const valsStart = sql.search(/VALUES\s*\(/i);
    let valsStr = '';
    if (valsStart !== -1) {
      let open = sql.indexOf('(', valsStart);
      let depth = 0;
      for (let i = open; i < sql.length; i++) {
        if (sql[i] === '(') depth++;
        else if (sql[i] === ')') { depth--; if (depth === 0) { valsStr = sql.substring(open + 1, i); break; } }
      }
    }
    if (colsMatch && valsStr) {
      const cols = colsMatch[1].split(',').map(c => c.trim());
      const vals = valsStr.split(',').map(v => v.trim());
      let paramIdx = 0;
      cols.forEach((c, i) => {
        const raw = vals[i];
        if (raw === undefined) return;
        if (raw === '?') {
          row[c] = params[paramIdx++];
        } else {
          row[c] = raw.replace(/^'(.*)'$/, '$1');
        }
      });
    }
    if (row.id) getDb()[q.table].push(row);
    saveDb(); return { changes: 1 };
  }
  if (q.isUpdate) {
    const setMatch = sql.match(/SET\s+(.+?)(?:\s+WHERE|$)/i);
    const whereMatch = sql.match(/WHERE\s+(.+?)$/i);
    if (setMatch) {
      const clauses = setMatch[1].split(',');
      let paramIdx = 0;
      const updates = {};
      for (const clause of clauses) {
        const eqIdx = clause.indexOf('=');
        const key = clause.substring(0, eqIdx).trim().replace(/['"]/g, '');
        let val = clause.substring(eqIdx + 1).trim();
        if (val === '?') {
          val = params[paramIdx++];
        } else {
          val = val.replace(/^'(.*)'$/, '$1');
        }
        updates[key] = val;
      }
      let idVal = null;
      let idField = 'id';
      if (whereMatch) {
        const whereStr = whereMatch[1].trim();
        // Handle AND conditions - find first = ? pair
        const conditions = whereStr.split(/\s+AND\s+/i);
        for (var _wci = 0; _wci < conditions.length; _wci++) {
          var cond = conditions[_wci].trim();
          var eqIdx2 = cond.indexOf('=');
          if (eqIdx2 === -1) continue;
          var field = cond.substring(0, eqIdx2).trim();
          var rawVal = cond.substring(eqIdx2 + 1).trim();
          if (_wci === 0) { idField = field; }
          if (rawVal === '?') {
            if (_wci === 0) idVal = params[paramIdx];
            paramIdx++;
          } else {
            if (_wci === 0) idVal = rawVal.replace(/^'(.*)'$/, '$1');
          }
        }
      }
      if (idVal === null || idVal === undefined) idVal = params[params.length - 1];
      const idx = getDb()[q.table].findIndex(r => r[idField] == idVal);
      if (idx !== -1) { getDb()[q.table][idx] = { ...getDb()[q.table][idx], ...updates }; saveDb(); return { changes: 1 }; }
    }
    return { changes: 0 };
  }
  if (q.isDelete) {
    const whereMatch = sql.match(/WHERE\s+(.+?)$/i);
    if (whereMatch) {
      const whereStr = whereMatch[1].trim();
      const eqIdx = whereStr.indexOf('=');
      const conditions = whereStr.split(/\s+AND\s+/i);
      let paramIdx = 0;
      let rows = getDb()[q.table];
      conditions.forEach(function(cond) {
        const eq = cond.indexOf('=');
        const field = cond.substring(0, eq).trim();
        let val = cond.substring(eq + 1).trim();
        if (val === '?') { val = params[paramIdx++]; }
        else { val = val.replace(/^'(.*)'$/, '$1'); }
        rows = rows.filter(function(r) { return r[field] != val; });
      });
      getDb()[q.table] = rows;
      saveDb();
      return { changes: 1 };
    }
    return { changes: 0 };
  }
  return { changes: 0 };
}

function _get(sql, params) {
  const q = _q(sql, params);
  if (q.table && getDb()[q.table]) {
    const orderMatch = sql.match(/ORDER\s+BY\s+(\w+)\s+(DESC|ASC)/i);
    const limitMatch = sql.match(/LIMIT\s+(\d+)/i);
    let results = _filterWhere(getDb()[q.table], sql, params);
    if (orderMatch) {
      const field = orderMatch[1];
      const dir = orderMatch[2];
      results.sort((a, b) => dir === 'DESC' ? (b[field]||'').localeCompare(a[field]||'') : (a[field]||'').localeCompare(b[field]||''));
    }
    if (sql.includes('COUNT(*)')) {
      return { count: results.length };
    }
    if (limitMatch) results = results.slice(0, parseInt(limitMatch[1]));
    return results[0] || null;
  }
  return null;
}

function _filterWhere(rows, sql, params) {
  const whereIdx = sql.toUpperCase().indexOf('WHERE');
  if (whereIdx === -1) return rows;
  const whereClause = sql.substring(whereIdx + 5).replace(/\bORDER\s+BY\s+.+/i, '').replace(/\bLIMIT\s+(?:\d+|\?)/i, '').replace(/\bOFFSET\s+(?:\d+|\?)/i, '').trim();
  const conditions = whereClause.split(/\bAND\b/i).map(c => c.trim()).filter(Boolean);
  const ops = ['!=', '<=', '>=', '<>', '=', '<', '>'];
  let paramIdx = 0;
  for (const cond of conditions) {
    let op = '=', opIdx = -1;
    const upper = cond.toUpperCase();
    if (upper.startsWith('DATE(')) {
      const dateStr = new Date().toISOString().split('T')[0];
      const match = cond.match(/DATE\(\s*(\w+)\s*\)\s*=\s*DATE\(\s*'now'\s*\)/i);
      if (match) {
        const field = match[1];
        rows = rows.filter(r => { const rv = r[field]; return rv && rv.startsWith(dateStr); });
      }
      continue;
    }
    for (const o of ops) {
      const idx = cond.indexOf(o);
      if (idx !== -1) { op = o; opIdx = idx; break; }
    }
    if (opIdx === -1) continue;
    const field = cond.substring(0, opIdx).trim();
    let val = cond.substring(opIdx + op.length).trim();
    if (val === '?') {
      val = params[paramIdx++];
    } else {
      val = val.replace(/^'(.*)'$/, '$1');
    }
    if (op === '!=' || op === '<>') {
      rows = rows.filter(r => r[field] != val);
    } else if (op === '<') {
      rows = rows.filter(r => Number(r[field]) < Number(val));
    } else if (op === '>') {
      rows = rows.filter(r => Number(r[field]) > Number(val));
    } else if (op === '<=') {
      rows = rows.filter(r => Number(r[field]) <= Number(val));
    } else if (op === '>=') {
      rows = rows.filter(r => Number(r[field]) >= Number(val));
    } else {
      rows = rows.filter(r => r[field] == val);
    }
  }
  return rows;
}

function _all(sql, params) {
  const q = _q(sql, params);
  if (q.table && getDb()[q.table]) {
    let results = _filterWhere(getDb()[q.table], sql, params);
    const orderMatch = sql.match(/ORDER\s+BY\s+(\w+)\s+(DESC|ASC)/i);
    if (orderMatch) {
      const field = orderMatch[1];
      const dir = orderMatch[2];
      results.sort((a, b) => dir === 'DESC' ? (b[field]||'').localeCompare(a[field]||'') : (a[field]||'').localeCompare(b[field]||''));
    }
    // Count how many params were consumed by _filterWhere
    const consumed = (sql.match(/\?/g) || []).length - (params || []).length;
    const remaining = Math.max(0, (params || []).length - Math.abs(consumed));
    const limitMatch = sql.match(/LIMIT\s+(?:(\d+)|(\?))/i);
    const offsetMatch = sql.match(/OFFSET\s+(?:(\d+)|(\?))/i);
    let offset = 0;
    if (offsetMatch) {
      offset = offsetMatch[1] ? parseInt(offsetMatch[1]) : (params[params.length - (limitMatch ? 2 : 1)] || 0);
    }
    if (limitMatch) {
      const limit = limitMatch[1] ? parseInt(limitMatch[1]) : (params[params.length - (offsetMatch ? 2 : 1)] || 50);
      if (offset > 0) results = results.slice(offset, offset + limit);
      else results = results.slice(0, limit);
    } else if (offset > 0) {
      results = results.slice(offset);
    }
    return results;
  }
  return [];
}

