var STANNP_API_KEY = process.env.STANNP_API_KEY || '';
var STANNP_BASE_URL = process.env.STANNP_BASE_URL || 'https://api-eu1.stannp.com/v1';
var STANNP_WEBHOOK_SECRET = process.env.STANNP_WEBHOOK_SECRET || '';

// ===== SHARED BRAND COLOURS PER LEAD TYPE =====
// Single source of truth so campaign emails, daily lead emails and the dashboard
// all use the SAME colour scheme per lead type. Dark, high-contrast shades so
// white text is always readable on the product colour. Each product also has a
// LIGHT accent for use on DARK backgrounds (e.g. footer/header) so the "Leads"
// wordmark stays visible — dark-on-dark is never used.
var PRODUCT_BRAND = {
  moving:      { color: '#bf360c', color2: '#8f2700', light: '#fb923c', bg: '#fff7f2', name: 'Moving Leads',     short: 'MOVING',  page: 'https://9amleads.com/movingleadsdaily/',   logo: '9' },
  probate:     { color: '#5b21b6', color2: '#3b1364', light: '#a78bfa', bg: '#f8f5ff', name: 'Probate Leads',     short: 'PROBATE', page: 'https://9amleads.com/probateleads/',      logo: '9' },
  newbusiness: { color: '#166534', color2: '#0f4524', light: '#4ade80', bg: '#f0fdf4', name: 'New Business Alerts', short: 'NEW BIZ', page: 'https://9amleads.com/newbusinessalert/',   logo: '9' },
  planning:    { color: '#115e59', color2: '#0b3d3a', light: '#2dd4bf', bg: '#f0fdfa', name: 'Planning Permission Leads', short: 'PLANNING', page: 'https://9amleads.com/planningleads/',   logo: '9' },
  tenders:     { color: '#3730a3', color2: '#232080', light: '#818cf8', bg: '#f5f7ff', name: 'Public Sector Tenders', short: 'TENDER', page: 'https://9amleads.com/tenders/',          logo: '9' }
};
function getProductBrand(product){
  return PRODUCT_BRAND[product] || PRODUCT_BRAND.moving;
}

class StannpProvider extends DirectMailProvider {
  constructor() { super(); this.name = 'stannp'; }

  // PREVIEW VERSION of the address zone: shows the customer where Stannp's native
  // `clearzone` will overlay the white address block at print time. Only used for
  // preview, never sent, and never modifies the real artwork. Built purely from
  // solid rects (sharp's SVG <text>/dashed strokes are unreliable).


  stannpRequest(endpoint, params, method) {
    return new Promise(function(resolve, reject) {
      if (!STANNP_API_KEY) return reject(new Error('STANNP_API_KEY not configured'));
      const https = require('https');
      var bodyData = Object.assign({}, params || {});
      var encoded = Object.keys(bodyData).map(function(k) { return encodeURIComponent(k) + '=' + encodeURIComponent(bodyData[k]); }).join('&');
      var url = STANNP_BASE_URL.replace(/\/+$/, '') + '/' + endpoint.replace(/^\/+/, '');
      var parsed = new URL(url);
      var httpMethod = method || 'POST';
      var headers = {
        'Authorization': 'Basic ' + Buffer.from(STANNP_API_KEY + ':').toString('base64'),
        'Content-Type': 'application/x-www-form-urlencoded'
      };
      if (httpMethod === 'GET') {
        // For GET requests with a query string, append to path
        if (encoded) parsed.search = (parsed.search ? parsed.search + '&' : '?') + encoded;
        headers['Content-Length'] = 0;
      } else {
        headers['Content-Length'] = Buffer.byteLength(encoded);
      }
      var req = https.request({
        hostname: parsed.hostname, path: parsed.pathname + (parsed.search || ''), method: httpMethod,
        headers: headers
      }, function(r) {
        var b = ''; r.on('data', function(c) { b += c; });
        r.on('end', function() {
          try {
            var parsed2 = JSON.parse(b);
            // Stannp returns { success: true, data: ... } or { success: false, error: ... }
            resolve(parsed2);
          } catch(e) { resolve({ success: false, error: 'Failed to parse Stannp response: ' + b.substring(0, 200) }); }
        });
      });
      req.on('error', function(e) { reject(new Error('Stannp request failed: ' + (e && e.message || ''))); });
      if (httpMethod !== 'GET') req.write(encoded);
      req.end();
    });
  }

  async validateAddresses(addresses) {
    if (!Array.isArray(addresses)) addresses = [addresses];
    var results = [];
    for (var vi = 0; vi < addresses.length; vi++) {
      var a = addresses[vi];
      var valid = a.postcode && a.postcode.trim().length > 2 && a.address_line1 && a.address_line1.trim().length > 2;
      results.push({
        original: a, valid: valid,
        reason: valid ? null : (a.postcode ? 'Missing street address' : 'Missing postcode'),
        corrected: valid ? { postcode: a.postcode.toUpperCase(), address_line1: a.address_line1, city: a.city || '', country: 'United Kingdom' } : null
      });
    }
    var validCount = results.filter(function(r) { return r.valid; }).length;
    return { success: true, validated: results.length, valid: validCount, invalid: results.length - validCount, details: results };
  }

  async createCampaign(campaignData) {
    // Stannp's new API sends single items directly via /letters/create or /postcards/create.
    // We treat each recipient as its own mailpiece (simplest, matches one-click per-lead sends).
    var params = { name: campaignData.name || 'Direct Mail Campaign' };
    var result = await this.stannpRequest('/groups/new', params);
    if (result.success && result.data) {
      return { success: true, provider_campaign_id: String(result.data), message: 'Stannp group created', status: 'accepted', raw: result };
    }
    return { success: false, error: result.error || 'Failed to create Stannp group', raw: result };
  }

  async uploadArtwork(campaignId, files) {
    if (!files || files.length === 0) return { success: true, files: 0, uploaded: [] };
    var results = [];
    for (var fi = 0; fi < files.length; fi++) {
      var f = files[fi];
      if (f.file_data) {
        var result = await this.stannpRequest('/files/upload', { file: f.file_data });
        results.push({ name: f.name, status: result.success ? 'uploaded' : 'failed', error: result.error || null, id: result.data ? result.data.id : '' });
      }
    }
    return { success: true, files: results.length, uploaded: results };
  }

  async sendCampaign(providerCampaignId) {
    // For the new API, mailpieces are created via /letters/create or /postcards/create.
    // We return success here; the actual send happens in sendMailpiece().
    return { success: true, provider_campaign_id: providerCampaignId, status: 'processing', message: 'Campaign queued for Stannp' };
  }

  // Build a proper A4 PDF letter. Stannp prints the RECIPIENT in the envelope
  // window (top-left), so the PDF keeps the top-left CLEAR and puts the SENDER's
  // return address at top-right + date, then the body. Auto-shrinks the font so
  // the letter is exactly ONE A4 page. DejaVu Sans TTF is embedded for unicode
  // symbols like ✓.
  async buildA4LetterPdf(pageHtml, recipient) {
    var PDFDocument = require('pdfkit');
    var fsL = require('fs');
    var pathL = require('path');
    var fontPath = pathL.join(__dirname, 'DejaVuSans.ttf');
    var unicodeFont = false;
    try { if (fsL.existsSync(fontPath)) unicodeFont = true; } catch(e) {}
    // Use the clean letter BODY when provided (avoids repeating sender/date that
    // the full HTML already carries).
    var rawBody = (recipient && recipient.letter_body) || pageHtml || '';
    var text = String(rawBody)
      .replace(/<br\s*\/?>/gi, '\n')
      .replace(/<\/p>/gi, '\n')
      .replace(/<\/div>/gi, '\n')
      .replace(/<[^>]+>/g, ' ')
      .replace(/&nbsp;/gi, ' ')
      .replace(/&amp;/gi, '&')
      .replace(/&lt;/gi, '<')
      .replace(/&gt;/gi, '>')
      .replace(/&quot;/gi, '"')
      .replace(/&#39;/gi, "'")
      .replace(/[ \t]+\n/g, '\n')
      .replace(/\n{3,}/g, '\n\n')
      .trim();
    // STRIP the recipient address block + marketing preamble: Stannp prints the
    // recipient address itself in the envelope window, so the letter must not
    // repeat it (was showing duplicated + missing the door number) and should
    // start at the real product/services content.
    text = cleanLetterBodyForPrint(text);
    var senderObj = (recipient && recipient.sender) || {};
    // STANNP A4 LETTER WINDOW: Stannp prints the recipient address in an envelope
    // WINDOW that sits in the TOP of the A4 page (~95-100mm from the top). The
    // letter body MUST start BELOW that window or it's hidden behind the address
    // label. A4 = 842pt tall; the window ends around 270pt, so the body starts at
    // 275pt and shrinks to fit the remaining ~500pt on one page.
    var WINDOW_BOTTOM = 275;
    var BODY_TOP = 285;
    var renderAt = function(fontSize, lineGap) {
      return new Promise(function(resolve, reject) {
        try {
          var buffers = [];
          var doc = new PDFDocument({ size: 'A4', layout: 'portrait', margin: 50 });
          if (unicodeFont) doc.registerFont('uni', fontPath);
          var pageCount = 1;
          doc.on('pageAdded', function() { pageCount++; });
          doc.on('data', buffers.push.bind(buffers));
          doc.on('end', function() { resolve({ buffer: Buffer.concat(buffers), pages: pageCount }); });
          var bodyFont = unicodeFont ? 'uni' : 'Helvetica';
          // NO sender/date header + divider: Stannp prints the recipient address
          // in its own envelope window, so the printed letter is just the body.
          // Body starts BELOW the window so it's fully visible on the printed page.
          doc.font(bodyFont).fontSize(fontSize).text(text, 50, BODY_TOP, { width: 595 - 100, lineBreak: true, align: 'left', lineGap: lineGap });
          doc.end();
        } catch(e) { reject(e); }
      });
    };
    var attempts = [
      { f: 10, g: 2 },
      { f: 9.5, g: 1.5 },
      { f: 9,   g: 1 },
      { f: 8.5, g: 0 },
      { f: 8,   g: 0 },
      { f: 7.5, g: 0 }
    ];
    var last = null;
    for (var ai = 0; ai < attempts.length; ai++) {
      last = await renderAt(attempts[ai].f, attempts[ai].g);
      if (last.pages <= 1) return last.buffer;
    }
    return last.buffer;
  }

  // Render a clean A4 letter PDF using Playwright (chromium, already installed).
  // Used as a fallback when pdfkit isn't available — guarantees Stannp always
  // receives a proper PDF FILE (its own recipient window is overlaid), never the
  // HTML `pages` path that injected "00000 / 0000" placeholders and duplicated the
  // recipient name.
  async buildA4LetterPdfViaBrowser(html, recipient) {
    var pw = require('playwright');
    var browser = await pw.chromium.launch({ headless: true });
    try {
      var page = await browser.newPage();
      await page.setContent('<html><head><style>@page{size:A4;margin:0}body{margin:0;font-family:Arial,Helvetica,sans-serif;color:#1e293b}</style></head><body>' + (html || '') + '</body></html>', { waitUntil: 'networkidle' });
      var pdfBuf = await page.pdf({ format: 'A4', printBackground: true, margin: { top: '130px', bottom: '40px', left: '50px', right: '50px' } });
      return Buffer.from(pdfBuf);
    } finally {
      try { await browser.close(); } catch(e) {}
    }
  }

  // Send a SINGLE mailpiece directly to Stannp (new API).
  // mailType: 'letter' | 'flyer' | 'flyer_plus_letter'
  // files: [{ name, file_data }] — artwork (flyer front/back / letter PDF)
  // recipient: { name, company, address_line1, city, postcode, country, pages }
  //   pages = HTML letter body OR plain text (used when no letter PDF uploaded)
  // format: optional format id (e.g. 'flyer_a5_portrait') or Stannp size string
  //   ('A5-PORT','A5','A6','DL','A5-ENV') — defaults to A5-PORT for flyers.
    // Stannp's legacy API expects RAW base64 (no data:...;base64, prefix).
  stripDataPrefix(data) {
    var s = String(data || '');
    var i = s.indexOf(',');
    if (i !== -1 && s.indexOf(';base64,') !== -1) return s.substring(i + 1);
    return s;
  }

async sendMailpiece(mailType, recipient, files, format) {
    var nameParts = (recipient.name || '').split(' ').filter(Boolean);
    var rcpt = {
      'recipient[firstname]': nameParts[0] || '',
      'recipient[lastname]': nameParts.slice(1).join(' ') || '',
      'recipient[company]': recipient.company || '',
      'recipient[address1]': recipient.address_line1 || '',
      'recipient[address2]': recipient.address_line2 || recipient.address2 || '',
      'recipient[city]': recipient.city || '',
      'recipient[town]': recipient.city || '',
      'recipient[county]': recipient.county || recipient.county_name || '',
      'recipient[postcode]': recipient.postcode || '',
      'recipient[country]': 'GB'
    };
    // Resolve the requested format/size for postcards.
    var wanted = format || '';
    if (typeof format === 'string' && DM_FORMATS.some(function(f) { return f.id === format; })) {
      var fmtMatch = DM_FORMATS.find(function(f) { return f.id === format; });
      wanted = fmtMatch.size;
    }
    var flyerSize = 'A5-PORT'; // default for a portrait leaflet
    var isLetter = mailType === 'letter' || mailType === 'letter_a4';
    var isFlyer = mailType === 'flyer' || mailType === 'flyer_a5';
    var isBoth = mailType === 'flyer_plus_letter';

    // Attach letter PDF if provided, otherwise use template content as HTML.
    var letterFile = (files || []).find(function(f) { return /letter|cover/i.test(f.name || ''); });
    var pageBody = recipient.pages || '<p>Dear ' + (recipient.name || 'Homeowner') + ',</p><p>Thank you for your time. We would love to help you.</p><p>[Your Company]</p>';

    // 'flyer_plus_letter' sends BOTH an A4 letter AND a leaflet. Send the letter
    // first, then the flyer — return success only if the letter was created.
    var letterResult = null;
    if (isLetter || isBoth) {
      var letterParams = Object.assign({}, rcpt, { tags: rcpt.tags || '9amleads' });
      if (letterFile && letterFile.file_data) {
        letterParams.file = this.stripDataPrefix(letterFile.file_data);
      } else {
        // Generate a proper A4 PDF letter from the body text so the bottom is
        // never cut off (raw HTML pages render on a flyer-sized page + clip), and
        // so Stannp receives a FILE (it renders its own recipient window) rather
        // than HTML `pages` (which made Stannp inject "00000 / 0000" placeholders
        // and repeat the recipient name).
        try {
          var letterPdfBuf = await this.buildA4LetterPdf(pageBody, recipient);
          letterParams.file = letterPdfBuf.toString('base64');
        } catch(pdfErr) {
          // pdfkit unavailable — use Playwright (chromium) to render the letter PDF
          // so Stannp still gets a clean FILE. Only fall back to HTML pages as a
          // last resort (Stannp mangles HTML pages with its own window overlay).
          try {
            console.log('[STANNP] pdfkit failed, rendering letter via Playwright:', pdfErr.message);
            var pwHtml = recipient.pages || pageBody;
            var pwBuf = await this.buildA4LetterPdfViaBrowser(pwHtml, recipient);
            letterParams.file = pwBuf.toString('base64');
          } catch(pwErr) {
            console.log('[STANNP] Playwright letter PDF also failed, using HTML pages:', pwErr.message);
            letterParams.pages = pageBody;
          }
        }
      }
      var res = await this.stannpRequest('/letters/create', letterParams);
      console.log('[STANNP] letter/create ' + recipient.email + ' mailType=' + mailType + ' sentAsFile=' + (!!letterParams.file) + ' hasPages=' + (!!letterParams.pages) + ' rcptName=' + (recipient.name || '') + ' rcptAddr=' + (recipient.address_line1 || '') + ' res=' + (res && res.success ? 'ok id=' + (res.data && res.data.id) : 'FAIL ' + (res && res.error)));
      if (res.success && res.data && res.data.id) {
        letterResult = { success: true, provider_campaign_id: String(res.data.id), cost: res.data.cost, status: res.data.status || 'processing', message: 'Letter sent to Stannp', raw: res };
      } else {
        if (isLetter) return { success: false, error: res.error || 'Failed to create letter', raw: res };
        // flyer_plus_letter: letter failed but flyer can still be attempted
        letterResult = null;
      }
    }

    // LETTER-ONLY: return the letter result here — previously this fell through to
    // "Unknown mail type: letter" and failed every plain-letter order.
    if (isLetter && !isBoth && letterResult) return letterResult;

    // Leaflet / postcard (A5 is the correct Stannp size for an A5 leaflet).
    // NOTE: Stannp requires a 'front' image or a 'template' for postcards —
    // it cannot print a leaflet from text alone.
      if (isFlyer || isBoth) {
        var front = (files || []).find(function(f) { return /flyer_front|front/i.test(f.name || ''); });
        var back = (files || []).find(function(f) { return /flyer_back|back/i.test(f.name || ''); });
        if ((!front || !front.file_data) && !isBoth) {
          return { success: false, error: 'A leaflet needs an uploaded front design. Please upload your leaflet front (Print & Post > Step 2) or choose the A4 letter instead.' };
        }
        // Resolve artwork size for the chosen format (px @300dpi incl 6mm bleed).
        // Fall back to A5-PORT (1819x2551) if no valid format was passed.
        var fw = 1819, fh = 2551;
        var fmtSpec = DM_FORMATS.find(function(f) { return f.id === format; }) || DM_FORMATS.find(function(f) { return f.size === wanted; });
        if (fmtSpec && fmtSpec.kind !== 'letter' && fmtSpec.width > 0) { fw = fmtSpec.width; fh = fmtSpec.height; flyerSize = fmtSpec.size; }
        // PREPARE + VALIDATE artwork BEFORE sending to Stannp. If the upload
        // doesn't meet the print spec (wrong aspect / unreadable), we ABORT here
        // so the customer never pays for a flyer that will print wrong.
        var prepErr = '';
        try {
          if (front && front.file_data) {
            var fp = await this.prepareA5Artwork(front, fw, fh, false);
            if (fp.error) { prepErr = fp.error; }
            else if (fp.ok && fp.file) { front = fp.file; }
          }
          if (!prepErr && back && back.file_data) {
            var bp = await this.prepareA5Artwork(back, fw, fh, true);
            if (bp.error) { prepErr = bp.error; }
            else if (bp.ok && bp.file) { back = bp.file; }
          }
        } catch(artErr) { console.log('[STANNP] A5 prep error:', artErr.message); prepErr = prepErr || artErr.message; }
        if (prepErr) {
          console.log('[STANNP] Blocking send — artwork failed validation: ' + prepErr);
          return { success: false, error: prepErr, blocked_by_spec: true };
        }
        // Send the customer's EXACT design at the chosen Stannp size. The artwork
        // is upscaled to the format's 300 DPI template so it fills the whole sheet
        // edge-to-edge with NO content cut. clearzone=true makes Stannp overlay the
        // white address zone at PRINT time (so the recipient address is
        // machine-readable) WITHOUT modifying the customer's design.
        var postcardParams = Object.assign({}, rcpt, { size: flyerSize, tags: rcpt.tags || '9amleads', padding: 0, clearzone: true });
        if (front && front.file_data) postcardParams.front = this.stripDataPrefix(front.file_data);
        if (back && back.file_data) postcardParams.back = this.stripDataPrefix(back.file_data);
        var res2 = await this.stannpRequest('/postcards/create', postcardParams);
        if (res2.success && res2.data && res2.data.id) {
          if (isBoth && letterResult) {
            // Return BOTH mailpiece ids so the caller can track the letter AND the
            // flyer as two separate Stannp orders. provider_mailpiece_ids lists each
            // individual order; provider_campaign_id holds the flyer id for backward
            // compatibility / proof lookup.
            var bothIds = [letterResult.provider_campaign_id, String(res2.data.id)];
            return { success: true, provider_campaign_id: String(res2.data.id), provider_mailpiece_ids: bothIds, mailpiece_types: ['letter', 'flyer'], cost: (parseFloat(letterResult.cost || 0) + parseFloat(res2.data.cost || 0)), status: res2.data.status || 'processing', message: 'Leaflet + letter sent to Stannp', raw: res2 };
          }
          return { success: true, provider_campaign_id: String(res2.data.id), provider_mailpiece_ids: [String(res2.data.id)], mailpiece_types: ['flyer'], cost: res2.data.cost, status: res2.data.status || 'processing', message: 'Leaflet sent to Stannp (' + flyerSize + ')', raw: res2 };
        }
        // Flyer failed — if it's a leaflet+letter combo, still report the letter
        if (isBoth && letterResult) {
          return { success: true, provider_campaign_id: letterResult.provider_campaign_id, cost: letterResult.cost, status: letterResult.status || 'processing', message: 'Letter sent to Stannp (leaflet failed: ' + (res2.error || 'unknown') + ')', raw: res2 };
        }
        return { success: false, error: res2.error || 'Failed to create leaflet', raw: res2 };
      }

    return { success: false, error: 'Unknown mail type: ' + mailType };
  }

  // VALIDATE an uploaded artwork file against the Stannp print spec for a format.
  // Returns { ok, warnings[], errors[], width, height, dpi, aspect, target_aspect }.
  // This runs BEFORE any send so a customer never pays for a flyer that will
  // print incorrectly (wrong aspect / too low resolution). 'ok' is false only
  // when the file can't be printed at all; warnings flag quality/risk items.


  // PREPARE FULL-BLEED ARTWORK for Stannp postcards at the requested format size.
  // Stannp templates are 300 DPI (A5 Portrait = 1819 x 2551, A5 Landscape = 2551 x
  // 1819, A6 = 1276 x 1819, DL = 1234 x 1890, A5-ENV = 1819 x 2551) incl 6mm bleed.
  // If the uploaded artwork is lower resolution (e.g. 746 x 1054 = ~128 DPI),
  // Stannp prints it letterboxed/too small. We upscale to the exact full-bleed
  // template so the design fills the whole card, then bake a white address
  // clearzone band at the bottom (matches Stannp's native clearzone=true overlay
  // so the recipient address has a dedicated space).


  async addRecipients(campaignId, recipients) {
    if (!recipients || recipients.length === 0) return { success: true, added: 0 };
    var added = 0, failed = 0, errors = [];
    for (var i = 0; i < recipients.length; i++) {
      var r = recipients[i];
      var params = {
        'recipient[firstname]': (r.name || '').split(' ')[0] || '',
        'recipient[lastname]': (r.name || '').split(' ').slice(1).join(' ') || '',
        'recipient[company]': r.company || '',
        'recipient[address1]': r.address_line1 || '',
        'recipient[city]': r.city || '',
        'recipient[postcode]': r.postcode || '',
        'recipient[country]': 'GB'
      };
      var result = await this.stannpRequest('/recipients/new', params);
      if (result.success) { added++; }
      else { failed++; if (errors.length < 3) errors.push(result.error || 'Recipient failed'); }
    }
    return { success: failed === 0, added: added, failed: failed, errors: errors };
  }

  async getBalance() {
    var result = await this.stannpRequest('/accounts/balance', {}, 'GET');
    if (result.success) {
      var bal = parseFloat(result.data && result.data.balance);
      return { success: true, balance: isNaN(bal) ? 0 : bal, raw: result };
    }
    return { success: false, error: result.error || 'Failed to get balance', raw: result };
  }

  async getCampaignStatus(providerCampaignId) {
    // Stannp's new API: mailpieces are queried via /letters/get/:id or /postcards/get/:id.
    // We try letters first, then postcards, since we don't know which type from the ID alone.
    if (!providerCampaignId) return { success: false, error: 'No provider ID' };
    var id = String(providerCampaignId).split(',')[0];
    var result = await this.stannpRequest('/letters/get/' + id, {}, 'GET');
    if (!result.success) result = await this.stannpRequest('/postcards/get/' + id, {}, 'GET');
    if (result.success && result.data) {
      var status = result.data.status || 'unknown';
      return { success: true, provider_campaign_id: id, status: status, raw: result };
    }
    return { success: false, error: result.error || 'Failed to get Stannp mailpiece status', raw: result };
  }

  async getProofOfPosting(providerCampaignId) {
    if (!providerCampaignId) return { success: false, error: 'No provider ID' };
    var id = String(providerCampaignId).split(',')[0];
    var result = await this.stannpRequest('/letters/get/' + id, {}, 'GET');
    if (!result.success) result = await this.stannpRequest('/postcards/get/' + id, {}, 'GET');
    if (result.success && result.data) {
      var d = result.data;
      return {
        success: true, provider_campaign_id: id,
        proof_url: d.pdf_file || d.pdf || '',
        generated_at: d.updated || d.timestamp || new Date().toISOString(),
        recipient_count: 1,
        postage_date: d.dispatched ? String(d.dispatched).split(' ')[0] : '',
        estimated_delivery: '',
        raw: result
      };
    }
    return { success: true, provider_campaign_id: id, proof_url: '', generated_at: new Date().toISOString(), recipient_count: 1, postage_date: '', estimated_delivery: '' };
  }

  // Reconciled mailpiece status lookup by exact mailpiece id (falls back through
  // letter/postcard endpoints). Returns Stannp's real status string.
  async getRealStatus(mailpieceId) {
    if (!mailpieceId) return { success: false, error: 'No mailpiece id' };
    var id = String(mailpieceId).trim();
    var r = await this.stannpRequest('/letters/get/' + id, {}, 'GET');
    if (!r.success || !r.data) r = await this.stannpRequest('/postcards/get/' + id, {}, 'GET');
    if (r.success && r.data && r.data.status) {
      return { success: true, mailpiece_id: id, status: String(r.data.status).toLowerCase(), raw: r.data };
    }
    return { success: false, mailpiece_id: id, error: (r.error || 'No status') };
  }

  // Reporting-based reconciliation: pull real mailpieces from the reporting API
  // for a date range and return a map of mailpiece id -> real status. Robust
  // fallback that only ever reflects what Stannp actually reports.
  async getReportingStatuses(daysBack) {
    var end = new Date(); var start = new Date(); start.setDate(start.getDate() - (daysBack || 7));
    function iso(d) { return d.toISOString().split('T')[0]; }
    var r = await this.stannpRequest('/reporting/list/' + iso(start) + '/' + iso(end), {}, 'GET');
    var map = {};
    if (r.success && r.data) {
      var inner = r.data.data || r.data;
      var singles = inner.singles || inner.mailpieces || inner.items || [];
      (Array.isArray(singles) ? singles : []).forEach(function(mp) {
        if (mp && mp.id) map[String(mp.id)] = String(mp.status || '').toLowerCase();
      });
    }
    return { success: true, count: Object.keys(map).length, statuses: map, raw: r };
  }

  async cancelCampaign(providerCampaignId) {
    var result = await this.stannpRequest('/campaigns/cancel', { campaign_id: providerCampaignId });
    if (result.success) {
      return { success: true, provider_campaign_id: providerCampaignId, status: 'cancelled', message: 'Campaign cancelled via Stannp', raw: result };
    }
    return { success: false, error: result.error || 'Failed to cancel Stannp campaign', raw: result };
  }

  async handleWebhook(payload) {
    // Verify webhook signature if secret is configured
    if (STANNP_WEBHOOK_SECRET) {
      // Stannp webhook verification would go here
    }
    return { success: true, received: true, payload: payload };
  }
}

function getDirectMailProvider() {
  var provider = DIRECT_MAIL_PROVIDER || 'mock';
  if (provider === 'stannp') {
    if (!STANNP_API_KEY) {
      console.log('[DM-PROVIDER] STANNP_API_KEY not set, falling back to mock');
      return new MockDirectMailProvider();
    }
    return new StannpProvider();
  }
  return new MockDirectMailProvider();
}




