function generateToken(customer) {
  return jwt.sign(
    { id: customer.id, email: customer.email, product: customer.product },
    JWT_SECRET,
    { expiresIn: '24h' }
  );
}

function authMiddleware(req, res, next) {
  const auth = req.headers.authorization;
  if (!auth || !auth.startsWith('Bearer ')) {
    return res.status(401).json({ error: 'No token provided' });
  }
  try {
    req.user = jwt.verify(auth.split(' ')[1], JWT_SECRET);
    // Cancelled accounts lose ALL dashboard/API access immediately — even with a
    // still-valid token they are locked out. (Admin routes use adminAuth, so this
    // only affects the customer dashboard.)
    try {
      var cc = db.prepare('SELECT plan FROM customers WHERE id = ?').get(req.user.id);
      if (cc && cc.plan === 'cancelled') {
        return res.status(403).json({ error: 'Your account has been cancelled. You no longer have access to the dashboard.', cancelled: true });
      }
    } catch(e) {}
    next();
  } catch {
    return res.status(401).json({ error: 'Invalid token' });
  }
}

// AUTH WITH QUERY TOKEN: <img src> tags in the dashboard cannot send an
// Authorization header, so the preview image endpoints accept the JWT via
// ?token=... as an alternative. Same verification as authMiddleware.
function authQueryOrHeader(req, res, next) {
  var token = req.query.token || (req.headers.authorization && req.headers.authorization.startsWith('Bearer ') ? req.headers.authorization.split(' ')[1] : '');
  if (!token) return res.status(401).json({ error: 'No token provided' });
  try {
    req.user = jwt.verify(token, JWT_SECRET);
    next();
  } catch {
    return res.status(401).json({ error: 'Invalid token' });
  }
}

function validateEmail(email) {
  return /^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(email);
}

// HANG-GUARD for the standalone daily scrapers (OTM, funeral): aborts after ms so
// a blocked source can never stall supply.
function moduleWithTimeout(promise, ms, label) {
  return new Promise(function(resolve) {
    var t = setTimeout(function() { console.log('[SCRAPER] TIMEOUT ' + label + ' exceeded ' + ms + 'ms - skipping'); resolve([]); }, ms);
    Promise.resolve(promise).then(function(v) { clearTimeout(t); resolve(v); }).catch(function(e) { clearTimeout(t); console.log('[SCRAPER] ' + label + ' error:', e.message); resolve([]); });
  });
}

// ===== AFFILIATE PROGRAM =====
// Referral terms (product-agnostic - works for every lead type):
//   - A customer signs up using an affiliate's NAME or CODE -> gets 14 days free
//     trial (standard is 7). The affiliate is credited with that signup.
//   - The affiliate earns £25 per referred customer WHO saves a card and carries
//     on (stripe_payment_method_id set). The payout is PAID one month after the
//     signup, provided the customer is still active (not cancelled).
// Payout lifecycle: pending (card saved, waiting out the month) -> due (month
// reached + still active, ready to be paid) -> paid (admin marks it paid).
var AFFILIATE_PAYOUT_RATE = 25;
// New affiliate sign-ups are activated immediately (true) so they can log in right
// away. Set AFFILIATE_AUTO_ACTIVATE=false in env to require manual admin approval.
var AFFILIATE_AUTO_ACTIVATE = process.env.AFFILIATE_AUTO_ACTIVATE !== 'false';

function escHtml(s) {
  return String(s == null ? '' : s).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;').replace(/"/g, '&quot;');
}

function resolveAffiliate(codeOrName) {
  var q = String(codeOrName || '').trim();
  if (!q) return null;
  var affs = (getDb().affiliates || []);
  var ql = q.toLowerCase();
  return affs.find(function(a) {
    if (a.status === 'paused' || a.status === 'suspended' || a.status === 'rejected' || a.status === 'closed') return false;
    return String(a.code || '').toLowerCase() === ql || String(a.referral_code || '').toLowerCase() === ql || String(a.name || '').toLowerCase() === ql || String(a.referral_slug || '').toLowerCase() === ql;
  }) || null;
}

function affiliateToken(aff) {
  return jwt.sign({ id: aff.id, email: aff.email, role: 'affiliate' }, JWT_SECRET, { expiresIn: '24h' });
}

function affiliateAuth(req, res, next) {
  var auth = req.headers.authorization || '';
  if (!auth.startsWith('Bearer ')) return res.status(401).json({ error: 'No token provided' });
  try {
    var tok = jwt.verify(auth.split(' ')[1], JWT_SECRET);
    if (tok.role !== 'affiliate') return res.status(403).json({ error: 'Not an affiliate account' });
    var aff = (getDb().affiliates || []).find(function(a) { return a.id === tok.id; });
    if (!aff) return res.status(401).json({ error: 'Affiliate not found' });
    req.affiliate = aff;
    next();
  } catch(e) { return res.status(401).json({ error: 'Invalid token' }); }
}



// Revert daily lead caps that were temporarily raised (e.g. "5 free leads today")

// Revert daily lead caps that were temporarily raised (e.g. "5 free leads today")
// once they expire, so the customer returns to their normal plan limit. Runs
// daily from the 09:00 cron BEFORE delivery so the promise count is correct.
function revertExpiredCapOverrides() {
  try {
    var now = new Date();
    var reverted = 0;
    (getDb().customers || []).forEach(function(c) {
      if (!c.cap_override_expires) return;
      var exp = new Date(c.cap_override_expires);
      if (now < exp) return;
      var prev = parseInt(c.cap_override_prev, 10);
      if (prev && prev > 0 && parseInt(c.leads_per_day, 10) !== prev) {
        c.leads_per_day = prev;
        reverted++;
      }
      c.cap_override_at = null; c.cap_override_prev = null; c.cap_override_expires = null;
    });
    if (reverted) saveDb();
    return reverted;
  } catch(e) { console.log('[CAP-OVERRIDE] revert error:', e.message); return 0; }
}

// Transition pending payouts to "due" once their month has passed and the
// referred customer is still active. Runs daily from the 09:00 cron.
function processAffiliatePayouts() {  try {
    var now = new Date();
    var changed = 0;
    (getDb().customers || []).forEach(function(c) {
      if (!c.affiliate_id) return;
      if (c.affiliate_payout_status !== 'pending' && c.affiliate_payout_status !== 'due') return;
      var due = c.affiliate_payout_due ? new Date(c.affiliate_payout_due) : null;
      if (!due) return;
      if (now < due) return;
      if (c.plan === 'cancelled' || c.plan === 'revoked') { c.affiliate_payout_status = 'ineligible'; changed++; return; }
      if (c.affiliate_payout_status !== 'due') { c.affiliate_payout_status = 'due'; changed++; }
    });
    if (changed) saveDb();
    return changed;
  } catch(e) { console.log('[AFFILIATE] Payout process error:', e.message); return 0; }
}

// ===== APP =====
const app = express();

// ===== LIVE POST TRACKING (Stannp) =====
// Map a Stannp mailpiece status to our friendly status + label + step index.
var STANNP_STATUS_MAP = [
  { match: ['accepted', 'queued', 'received'], status: 'queued', label: 'Accepted', step: 1, emoji: '\u2705', desc: 'Order accepted by the print house' },
  { match: ['processing', 'printing', 'in_progress', 'produced', 'producing'], status: 'printing', label: 'Printing', step: 2, emoji: '\uD83D\uDD27', desc: 'Your mail is being printed' },
  { match: ['dispatched', 'posted', 'handed_over'], status: 'dispatched', label: 'Dispatched', step: 3, emoji: '\uD83D\uDE9A', desc: 'Handed to Royal Mail' },
  { match: ['local_delivery', 'out_for_delivery'], status: 'out_for_delivery', label: 'Out for delivery', step: 4, emoji: '\uD83D\uDEE3\uFE0F', desc: 'At the local delivery office' },
  { match: ['delivered', 'completed'], status: 'delivered', label: 'Delivered', step: 5, emoji: '\uD83D\uDCEB', desc: 'Delivered to the address' },
  { match: ['returned'], status: 'returned', label: 'Returned', step: 6, emoji: '\u21A9\uFE0F', desc: 'Returned to sender' },
  { match: ['cancelled', 'canceled', 'failed', 'rejected'], status: 'cancelled', label: 'Cancelled / Failed', step: 6, emoji: '\u26D4', desc: 'This item was not posted' }
];
function mapStannpStatus(rawStatus) {
  var s = String(rawStatus || '').toLowerCase().trim();
  for (var i = 0; i < STANNP_STATUS_MAP.length; i++) {
    var m = STANNP_STATUS_MAP[i];
    for (var j = 0; j < m.match.length; j++) { if (s === m.match[j]) return m; }
  }
  // Fallback: keep raw but treat unknown as queued
  return { status: 'unknown', label: s || 'Unknown', step: 0, emoji: '\uD83D\uDD0D', desc: s || 'Unknown status' };
}

// Record a tracking update for a recipient + its campaign (idempotent, preserves timeline).
function recordMailpieceTracking(customerId, campaignId, recipientId, mailpieceId, rawStatus, eventTime) {
  try {
    var dbT = getDb();
    var mapped = mapStannpStatus(rawStatus);
    var when = eventTime || new Date().toISOString();
    // Only move forward (don't downgrade a delivered item back to printing on late webhooks)
    var rcpt = (dbT.direct_mail_recipients || []).find(function(r) { return r.id === recipientId && r.customer_id === customerId; });
    if (rcpt) {
      var curStep = rcpt.tracking_step || 0;
      if (mapped.step >= curStep || mapped.status === 'cancelled' || mapped.status === 'returned') {
        rcpt.provider_status = mapped.status;
        rcpt.provider_status_label = mapped.label;
        rcpt.tracking_step = mapped.step;
        rcpt.provider_updated_at = when;
        rcpt.provider_emoji = mapped.emoji;
        if (!rcpt.tracking_history) rcpt.tracking_history = [];
        var lastEvt = rcpt.tracking_history.length ? rcpt.tracking_history[rcpt.tracking_history.length - 1] : null;
        if (!lastEvt || lastEvt.status !== mapped.status) {
          rcpt.tracking_history.push({ status: mapped.status, label: mapped.label, at: when, desc: mapped.desc });
        }
      }
    }
    // Campaign-level: aggregate status from recipients
    var camp = (dbT.direct_mail_campaigns || []).find(function(c) { return c.id === campaignId && c.customer_id === customerId; });
    if (camp) {
      camp.provider_status = mapped.status;
      camp.provider_status_label = mapped.label;
      camp.provider_updated_at = when;
      var campRcpts = (dbT.direct_mail_recipients || []).filter(function(r) { return r.campaign_id === campaignId && r.customer_id === customerId; });
      if (campRcpts.length) {
        var deliv = campRcpts.filter(function(r) { return r.provider_status === 'delivered'; }).length;
        var disp = campRcpts.filter(function(r) { return r.provider_status === 'dispatched' || r.provider_status === 'out_for_delivery'; }).length;
        var print = campRcpts.filter(function(r) { return r.provider_status === 'printing' || r.provider_status === 'queued'; }).length;
        camp.tracking_summary = { total: campRcpts.length, delivered: deliv, dispatched: disp, printing: print };
        camp.provider_status = deliv === campRcpts.length ? 'delivered' : (deliv > 0 || disp > 0 ? 'dispatched' : 'printing');
        camp.provider_status_label = camp.provider_status === 'delivered' ? 'Delivered' : camp.provider_status === 'dispatched' ? 'Dispatched' : 'Printing';
      }
      if (!camp.tracking_history) camp.tracking_history = [];
      var lastCampEvt = camp.tracking_history.length ? camp.tracking_history[camp.tracking_history.length - 1] : null;
      if (!lastCampEvt || lastCampEvt.status !== camp.provider_status) {
        camp.tracking_history.push({ status: camp.provider_status, label: camp.provider_status_label, at: when, desc: mapped.desc, delivered_count: deliv || 0, total: campRcpts.length || 0 });
      }
    }
    saveDb();
    return { success: true, mapped: mapped.status };
  } catch(e) { console.log('[DM-TRACKING] recordMailpieceTracking error:', e.message); return { success: false, error: e.message }; }
}

// REAL-DATA RECONCILE: refresh recipient tracking from Stannp's reporting API.
// This is the authoritative source — it only ever reflects what Stannp reports,
// never mock/guessed values. Called by the poller as a fallback and manually.
async function reconcileTrackingFromStannp(daysBack) {
  try {
    var provider = getDirectMailProvider();
    if (provider.name !== 'stannp' || typeof provider.getReportingStatuses !== 'function') return { success: false, error: 'Stannp provider not active' };
    var rep = await provider.getReportingStatuses(daysBack || 14);
    if (!rep.success || !rep.statuses) return { success: false, error: 'Reporting lookup failed' };
    var dbR = getDb();
    var statusMap = rep.statuses;
    var updated = 0;
    // Match by exact numeric mailpiece id
    (dbR.direct_mail_recipients || []).forEach(function(r) {
      var mid = String(r.provider_mailpiece_id || '');
      if (!/^\d+$/.test(mid)) return;
      var real = statusMap[mid];
      if (!real) return;
      // Only move forward (delivered stays delivered)
      var curStep = r.tracking_step || 0;
      var mapped = mapStannpStatus(real);
      if (mapped.step >= curStep || mapped.status === 'cancelled' || mapped.status === 'returned') {
        recordMailpieceTracking(r.customer_id, r.campaign_id, r.id, mid, real, new Date().toISOString());
        updated++;
      }
    });
    if (updated) saveDb();
    return { success: true, reported: Object.keys(statusMap).length, updated: updated };
  } catch(e) { return { success: false, error: e.message }; }
}

// POST /api/webhooks/stannp — Stannp real-time mailpiece_status webhook.
// Payload: { webhook_id, event: "mailpiece_status" | "test_url", created, retries, mailpieces: [...] }
app.post('/api/webhooks/stannp', express.raw({ type: 'application/json' }), (req, res) => {
  var rawBody = req.rawBody || req.body.toString('utf-8');
  var body = {};
  try { body = JSON.parse(rawBody || '{}'); } catch(e) { body = req.body || {}; }
  // Signature verification (optional but recommended) — X-Stannp-Signature = HMAC-SHA256(secret, rawBody)
  if (STANNP_WEBHOOK_SECRET) {
    try {
      var sig = req.headers['x-stannp-signature'] || '';
      var expected = require('crypto').createHmac('sha256', STANNP_WEBHOOK_SECRET).update(rawBody).digest('hex');
      var ok = sig && sig.length > 10 && expected === sig;
      // Fall back to timing-safe compare
      if (sig) {
        var buf1 = Buffer.from(String(expected));
        var buf2 = Buffer.from(String(sig));
        ok = buf1.length === buf2.length && require('crypto').timingSafeEqual(buf1, buf2);
      }
      if (!ok) { console.log('[DM-WEBHOOK] Stannp signature mismatch'); return res.status(401).json({ success: false, error: 'Invalid signature' }); }
    } catch(sigErr) { console.log('[DM-WEBHOOK] signature check error:', sigErr.message); }
  }
  // Test URL validation — Stannp sends this when the webhook is first created.
  if (body.event === 'test_url') { return res.status(200).json({ success: true }); }
  if (body.event === 'mailpiece_status' || (body.mailpieces && body.mailpieces.length)) {
    var mailpieces = Array.isArray(body.mailpieces) ? body.mailpieces : [];
    var dbW = getDb();
    var updated = 0;
    for (var wi = 0; wi < mailpieces.length; wi++) {
      var mp = mailpieces[wi] || {};
      var mpId = String(mp.id || '');
      if (!mpId) continue;
      // Find the recipient with this provider_mailpiece_id
      var rcpt = (dbW.direct_mail_recipients || []).find(function(r) { return String(r.provider_mailpiece_id || '') === mpId; });
      if (!rcpt) { console.log('[DM-WEBHOOK] No recipient for mailpiece ' + mpId); continue; }
      recordMailpieceTracking(rcpt.customer_id, rcpt.campaign_id, rcpt.id, mpId, mp.status || '', mp.timestamp || new Date().toISOString());
      updated++;
    }
    console.log('[DM-WEBHOOK] Stannp mailpiece_status: ' + updated + ' recipients updated (' + mailpieces.length + ' in payload)');
    return res.status(200).json({ success: true, updated: updated });
  }
  res.status(200).json({ success: true, received: true, event: body.event || 'unknown' });
});

// GET /api/direct-mail/tracking — customer dashboard: live post tracking for their campaigns.
app.get('/api/direct-mail/tracking', authMiddleware, async (req, res) => {
  try {
    backfillMailpieceIds();
    var dbT = getDb();
    var all = (dbT.direct_mail_campaigns || []).filter(function(c) { return c.customer_id === req.user.id && c.status !== 'draft'; });
    var out = [];
    var demos = [];
    all.forEach(function(c) {
      var rcpts = (dbT.direct_mail_recipients || []).filter(function(r) { return r.campaign_id === c.id && r.customer_id === req.user.id; });
      var record = {
        id: c.id, name: c.name, description: c.description, status: c.status, provider_status: c.provider_status || '',
        provider_status_label: c.provider_status_label || '', provider_updated_at: c.provider_updated_at || '',
        created_at: c.created_at, sent_count: c.sent_count || rcpts.length, tracking_summary: c.tracking_summary || null,
        tracking_history: c.tracking_history || [], proof_url: c.proof_url || '',
        recipients: rcpts.map(function(r) { return { id: r.id, name: r.name, address: (r.address_line1 || '') + (r.city ? ', ' + r.city : '') + (r.postcode ? ', ' + r.postcode : ''), provider_status: r.provider_status || 'pending', provider_status_label: r.provider_status_label || 'Pending', tracking_step: r.tracking_step || 0, provider_emoji: r.provider_emoji || '\uD83D\uDD0D', provider_updated_at: r.provider_updated_at || '', tracking_history: r.tracking_history || [], lead_id: r.lead_id || '', mailpiece_type: r.mailpiece_type || '' }; })
      };
      if (isRealTrackingCampaign(c, rcpts)) out.push(record);
      else if (c.notes === 'DEMO_TRACKING') { record.is_demo = true; demos.push(record); }
      // else: legacy/mock records are dropped entirely from customer view
    });
    res.json({ success: true, count: out.length, campaigns: out, demo_count: demos.length, demos: demos, synced_at: new Date().toISOString() });
  } catch(e) { res.status(500).json({ error: e.message }); }
});

// POST /api/direct-mail/tracking/sync — force a live refresh of campaign statuses from Stannp.
app.post('/api/direct-mail/tracking/sync', authMiddleware, async (req, res) => {
  try {
    var dbS = getDb();
    var provider = getDirectMailProvider();
    var syncable = (dbS.direct_mail_recipients || []).filter(function(r) {
      if (r.customer_id !== req.user.id || !r.provider_mailpiece_id) return false;
      if (!/^\d+$/.test(String(r.provider_mailpiece_id)) || String(r.provider_mailpiece_id).length < 4) return false;
      var cRow = (dbS.direct_mail_campaigns || []).find(function(c) { return c.id === r.campaign_id; });
      if (cRow && cRow.notes === 'DEMO_TRACKING') return false;
      if (cRow && String(cRow.provider || '').toLowerCase() !== 'stannp') return false;
      return (!r.provider_status || ['queued','printing','dispatched','out_for_delivery','processing','accepted'].indexOf(r.provider_status) !== -1);
    });
    var seen = {}; var ids = [];
    syncable.forEach(function(r) { var mid = String(r.provider_mailpiece_id); if (!seen[mid]) { seen[mid] = 1; ids.push(mid); } });
    var updated = 0;
    for (var ci = 0; ci < ids.length; ci++) {
      try {
        var st = await provider.getCampaignStatus(ids[ci]);
        if (st && st.success && st.status) {
          var rcpt = (dbS.direct_mail_recipients || []).find(function(r) { return String(r.provider_mailpiece_id || '') === ids[ci]; });
          if (rcpt) { recordMailpieceTracking(rcpt.customer_id, rcpt.campaign_id, rcpt.id, ids[ci], st.status, new Date().toISOString()); updated++; }
        }
      } catch(syncErr) {}
    }
    res.json({ success: true, updated: updated });
  } catch(e) { res.status(500).json({ error: e.message }); }
});

// POST /api/direct-mail/tracking/bulk-delete — bulk delete tracking records.
// Body: { campaign_ids?: string[], delete_older_than?: '7d'|'30d'|'90d'|'180d' }
// Removes the campaigns, their recipients and status history. Demo campaigns are
// always excluded unless explicitly in campaign_ids.


// GET /api/direct-mail/tracking/calendar — group tracking by date for calendar/week views.

app.use(cors({ origin: ['https://www.9amleads.com', 'https://9amleads.com', 'http://localhost:8012'], credentials: true }));
// NEVER cache any /api response. Admin dashboards (customers/leads/stats) are live
// data and Cloudflare/Netlify/browsers must not serve a stale snapshot (a cached
// customers response made the admin page appear to show only one customer).
app.use('/api', function(req, res, next) { res.setHeader('Cache-Control', 'no-store'); next(); });
// Capture raw body for Stripe signature verification (preserve stream for express.json)
// Raised from 2mb to 20mb so Print & Post leaflet/letter uploads (sent as base64)
// don't fail with a body-too-large error when a customer saves their setup.
app.use(express.json({
  limit: '20mb',
  verify: function(req, res, buf) { req.rawBody = buf.toString('utf-8'); }
}));

// Rate limiting — signup gets a much higher ceiling than login so a launch burst
// isn't blocked (the 60/min global API limiter still protects the server).
const apiLimiter = rateLimit({ windowMs: 60 * 1000, max: 60, message: { error: 'Too many requests. Please slow down.' } });
const authLimiter = rateLimit({ windowMs: 15 * 60 * 1000, max: 10, message:

 { error: 'Too many login attempts. Try again in 15 minutes.' } });
const signupLimiter = rateLimit({ windowMs: 15 * 60 * 1000, max: 100, message: { error: 'Too many signups right now. Please try again in a few minutes.' } });
app.use('/api/', apiLimiter);
app.use('/api/auth/login', authLimiter);
app.use('/api/auth/signup', signupLimiter);

// ============================================================
// ===== 9amLeads PARTNER PROGRAMME ============================
// Extends the existing affiliate system into a full partner
// programme supporting AFFILIATE (one-off £25) and SALES PARTNER
// (monthly £25 recurring) commission partners.
//
// Data lives in the JSON db (getDb()). Partners reuse the existing
// 'affiliates' array (backwards compatible). New collections:
//   partner_attribution, partner_prospects, partner_notes,
//   partner_feedback, partner_commissions, partner_payouts,
//   partner_audit_log, partner_resources, partner_announcements,
//   partner_config.
// Commission = REAL ledger (never front-end calculations).
// Idempotency: one commission per (partner, customer, period, type).
// ============================================================

function partnerConfig() {
  var dbc = getDb();
  if (!dbc.partner_config) {
    dbc.partner_config = {
      affiliate_one_off_amount: 25,
      sales_partner_monthly_amount: 25,
      affiliate_trial_days: 14,
      sales_partner_trial_days: 14,
      standard_trial_days: 7,
      attribution_window_days: 30,
      commission_clearance_days: 30,
      commission_qualification_days: 30,
      sales_partner_commission_duration_months: null,
      affiliate_qualifying_payment_count: 1,
      partners_open: true,
      attribution_first_click_wins: true,
      affiliate_commission_model: 'monthly',
      retention_followup_days: 14
    };
  }
  // Backfill any keys added in newer versions so existing configs stay complete.
  var defaults = {
    affiliate_one_off_amount: 25, sales_partner_monthly_amount: 25, affiliate_trial_days: 14,
    sales_partner_trial_days: 14, standard_trial_days: 7, attribution_window_days: 30,
    commission_clearance_days: 30, commission_qualification_days: 30,
    sales_partner_commission_duration_months: null, affiliate_qualifying_payment_count: 1,
    partners_open: true, attribution_first_click_wins: true,
    affiliate_commission_model: 'monthly', retention_followup_days: 14
  };
  for (var k in defaults) { if (dbc.partner_config[k] === undefined) dbc.partner_config[k] = defaults[k]; }
  return dbc.partner_config;
}
function partnerAudit(action, data) {
  try {
    var dbc = getDb();
    if (!dbc.partner_audit_log) dbc.partner_audit_log = [];
    dbc.partner_audit_log.push(Object.assign({ action: action, at: new Date().toISOString() }, data || {}));
    if (dbc.partner_audit_log.length > 10000) dbc.partner_audit_log = dbc.partner_audit_log.slice(-10000);
    saveDb();
  } catch(e) {}
}
// Partner notification: alerts the partner who owns a customer's attribution
// about payment/cancellation/commission-relevant events (retention support).
function partnerNotify(partnerId, type, message, customerId) {
  try {
    if (!partnerId) return;
    var dbc = getDb();
    if (!dbc.partner_notifications) dbc.partner_notifications = [];
    dbc.partner_notifications.push({ id: uuidv4(), partner_id: partnerId, customer_id: customerId || '', type: String(type || ''), message: String(message || '').substring(0, 500), read: false, created_at: new Date().toISOString() });
    if (dbc.partner_notifications.length > 5000) dbc.partner_notifications = dbc.partner_notifications.slice(-5000);
    saveDb();
  } catch(e) {}
}
function partnerForCustomer(customerId) {
  try {
    var a = partnerAttributionForCustomer(customerId);
    if (!a || !a.partner_id) return null;
    return (getDb().affiliates || []).find(function(p){ return p.id === a.partner_id; }) || null;
  } catch(e) { return null; }
}
function partnerRefCode(existing) {
  var chars = 'ABCDEFGHJKLMNPQRSTUVWXYZ23456789';
  for (var i = 0; i < 50; i++) {
    var c = '9AM';
    for (var j = 0; j < 5; j++) c += chars[Math.floor(Math.random() * chars.length)];
    var clash = (existing || []).some(function(p){ return String(p.referral_code || p.code || '').toUpperCase() === c; });
    if (!clash) return c;
  }
  return '9AM' + Date.now().toString(36).toUpperCase();
}
function partnerStatusActive(p) {
  if (!p) return false;
  var st = String(p.status || '').toLowerCase();
  return st === 'active' || st === '' || st === 'approved';
}
function partnerTypeOf(p) { return (p && p.partner_type) || 'affiliate'; }
function isSalesPartner(p) { return partnerTypeOf(p) === 'sales_partner'; }
function partnerByCode(code) {
  if (!code) return null;
  var ql = String(code).trim().toLowerCase();
  return (getDb().affiliates || []).find(function(p) {
    return String(p.referral_code || p.code || '').toLowerCase() === ql || String(p.referral_slug || '').toLowerCase() === ql;
  }) || null;
}
// requirePartner: unified auth for both partner types (uses the existing affiliate token)
function requirePartner(req, res, next) {
  var auth = req.headers.authorization || '';
  if (!auth.startsWith('Bearer ')) return res.status(401).json({ error: 'No token provided' });
  try {
    var tok = jwt.verify(auth.split(' ')[1], JWT_SECRET);
    if (tok.role !== 'affiliate') return res.status(403).json({ error: 'Not a partner account' });
    var aff = (getDb().affiliates || []).find(function(a) { return a.id === tok.id; });
    if (!aff) return res.status(401).json({ error: 'Partner not found' });
    req.partner = aff;
    next();
  } catch(e) { return res.status(401).json({ error: 'Invalid token' }); }
}
function requireSalesPartner(req, res, next) {
  if (!isSalesPartner(req.partner)) return res.status(403).json({ error: 'Sales Partner access only' });
  next();
}
function partnerDashboardSafe(p) {
  return {
    id: p.id, partner_type: partnerTypeOf(p), status: p.status || 'active',
    referral_code: p.referral_code || p.code, referral_slug: p.referral_slug || (p.referral_code || p.code),
    full_name: p.name || p.full_name, business_name: p.business_name || '', email: p.email,
    joined_at: p.created_at || p.joined_at || '', approved_at: p.approved_at || '',
    commission_type: p.commission_type || (isSalesPartner(p) ? 'recurring' : 'one_off'),
    commission_amount: p.commission_amount || (isSalesPartner(p) ? partnerConfig().sales_partner_monthly_amount : partnerConfig().affiliate_one_off_amount),
    commission_duration_months: p.commission_duration_months === undefined ? null : p.commission_duration_months,
    hide_from_leaderboard: !!p.hide_from_leaderboard
  };
}
function partnerRefLink(p) {
  var code = p.referral_code || p.code;
  return 'https://www.9amleads.com/portal/?ref=' + encodeURIComponent(code) + '&src=' + partnerTypeOf(p);
}
function partnerAttributionForCustomer(customerId) {
  try { return (getDb().partner_attribution || []).filter(function(a){ return a.customer_id === customerId; })[0] || null; } catch(e) { return null; }
}
// Commission period key: monthly anniversary (YYYY-MM-DD) derived from the
// customer's first paid conversion (converted_at). One commission per month.
function commissionPeriodKey(convertedAt, refDate) {
  var d = new Date(convertedAt);
  var now = refDate ? new Date(refDate) : new Date();
  // current due period = the most recent anniversary that has occurred
  var anniv = new Date(d);
  anniv.setMonth(anniv.getMonth() + 1);
  var best = null;
  while (anniv <= now) {
    best = new Date(anniv);
    anniv = new Date(anniv); anniv.setMonth(anniv.getMonth() + 1);
  }
  if (!best) return null;
  return { key: best.getFullYear() + '-' + String(best.getMonth() + 1).padStart(2, '0'), date: best.toISOString(), annivDay: d.getDate() };
}
function customerIsPaying(c) {
  if (!c) return false;
  if (String(c.plan || '') === 'cancelled') return false;
  if (['starter', 'pro', 'enterprise'].indexOf(c.plan) !== -1) return true;
  return !!c.stripe_subscription_id;
}
function customerRefunded(c) {
  try { return !!(c.stripe_refunded || (c.payment_state && String(c.payment_state).toLowerCase() === 'refunded')); } catch(e) { return false; }
}
function commissionExists(partnerId, customerId, period, type) {
  return (getDb().partner_commissions || []).some(function(cm) {
    return cm.partner_id === partnerId && cm.customer_id === customerId && cm.commission_period === period && (type ? cm.commission_type === type : true);
  });
}
function partnerCommissionKey(c) { return c && c.partner_id + '|' + c.customer_id + '|' + c.commission_period + '|' + (c.commission_type || 'recurring'); }

// ===== COMMISSION ENGINE =====
// Runs on a safe schedule + can be triggered by admin. Creates PENDING
// commissions (real ledger). Approval happens after the clearance period.
function processPartnerCommissions() {
  var dbc = getDb();
  var cfg = partnerConfig();
  var now = new Date();
  var created = [];
  try {
    var partners = dbc.affiliates || [];
    var custs = dbc.customers || [];
    var attr = dbc.partner_attribution || [];
    partners.forEach(function(p) {
      if (!partnerStatusActive(p)) return;
      var isSales = isSalesPartner(p);
      if (isSales) {
        var monthly = Number(p.commission_amount) || Number(cfg.sales_partner_monthly_amount) || 25;
        var duration = p.commission_duration_months !== undefined && p.commission_duration_months !== null ? Number(p.commission_duration_months) : Number(cfg.sales_partner_commission_duration_months);
        attr.filter(function(a){ return a.partner_id === p.id && a.attribution_status !== 'released'; }).forEach(function(a) {
          var c = custs.find(function(x){ return x.id === a.customer_id; });
          if (!c || !customerIsPaying(c) || customerRefunded(c)) return;
          var conv = a.converted_at || a.signup_at;
          if (!conv) return;
          // Initial qualification: no commission before the qualification period passes
          var qDays = Number(cfg.commission_qualification_days) || 30;
          if ((now.getTime() - new Date(conv).getTime()) < qDays * 86400000) return;
          var period = commissionPeriodKey(conv, now);
          if (!period) return;
          // Duration limit
          if (duration !== null && duration !== undefined) {
            var monthsSince = Math.floor((now.getTime() - new Date(conv).getTime()) / (30.44 * 86400000));
            if (monthsSince >= duration) return;
          }
          if (commissionExists(p.id, c.id, period.key, 'recurring')) return;
          var cm = { id: uuidv4(), partner_id: p.id, customer_id: c.id, commission_period: period.key,
            commission_type: 'recurring', commission_amount: monthly, currency: 'GBP', status: 'pending',
            qualifying_date: period.date, created_at: now.toISOString() };
          if (!dbc.partner_commissions) dbc.partner_commissions = [];
          dbc.partner_commissions.push(cm);
          created.push(cm);
        });
      } else {
        // Affiliate: commission model is configurable. Default is MONTHLY:
        // £25 one-off when the customer first pays + £25/month for as long as
        // they stay a paying subscriber. The 'one_off' option keeps only the
        // single £25 referral payment.
        var affMonthly = String(cfg.affiliate_commission_model || 'monthly') === 'monthly';
        var affAmount = Number(p.commission_amount) || Number(cfg.affiliate_one_off_amount) || 25;
        attr.filter(function(a){ return a.partner_id === p.id; }).forEach(function(a) {
          var c = custs.find(function(x){ return x.id === a.customer_id; });
          if (!c || !customerIsPaying(c) || customerRefunded(c)) return;
          var conv = a.converted_at || a.signup_at;
          if (!conv) return;
          var qDays = Number(cfg.commission_qualification_days) || 30;
          if ((now.getTime() - new Date(conv).getTime()) < qDays * 86400000) return;
          if (!dbc.partner_commissions) dbc.partner_commissions = [];
          if (affMonthly) {
            // 1) One-off £25 "sign-up" commission (created once per customer).
            if (!commissionExists(p.id, c.id, 'ONEOFF', 'one_off')) {
              var cm0 = { id: uuidv4(), partner_id: p.id, customer_id: c.id, commission_period: 'ONEOFF',
                commission_type: 'one_off', commission_amount: affAmount, currency: 'GBP', status: 'pending',
                qualifying_date: conv, created_at: now.toISOString() };
              dbc.partner_commissions.push(cm0); created.push(cm0);
            }
            // 2) Monthly recurring £25 for the current period (idempotent).
            var period = commissionPeriodKey(conv, now);
            if (period && !commissionExists(p.id, c.id, period.key, 'recurring')) {
              var cm = { id: uuidv4(), partner_id: p.id, customer_id: c.id, commission_period: period.key,
                commission_type: 'recurring', commission_amount: affAmount, currency: 'GBP', status: 'pending',
                qualifying_date: period.date, created_at: now.toISOString() };
              dbc.partner_commissions.push(cm); created.push(cm);
            }
          } else {
            if (!commissionExists(p.id, c.id, 'ONEOFF', 'one_off')) {
              var cm2 = { id: uuidv4(), partner_id: p.id, customer_id: c.id, commission_period: 'ONEOFF',
                commission_type: 'one_off', commission_amount: affAmount, currency: 'GBP', status: 'pending',
                qualifying_date: conv, created_at: now.toISOString() };
              dbc.partner_commissions.push(cm2); created.push(cm2);
            }
          }
        });
      }
    });
    saveDb();
    return { created: created.length };
  } catch(e) { return { created: created.length, error: e.message }; }
}
// Clearance: pending -> approved after the clearance period (if customer still paying)
function processCommissionClearance() {
  var dbc = getDb();
  var cfg = partnerConfig();
  var days = Number(cfg.commission_clearance_days) || 30;
  var now = Date.now();
  var approved = 0;
  try {
    var custs = dbc.customers || [];
    (dbc.partner_commissions || []).forEach(function(cm) {
      if (cm.status !== 'pending') return;
      if ((now - new Date(cm.created_at).getTime()) < days * 86400000) return;
      var c = custs.find(function(x){ return x.id === cm.customer_id; });
      if (!c || !customerIsPaying(c) || customerRefunded(c)) return; // hold while not paying
      cm.status = 'approved'; cm.approved_at = new Date().toISOString();
      approved++;
    });
    saveDb();
    return { approved: approved };
  } catch(e) { return { approved: approved, error: e.message }; }
}
// Mark cancelled customers' pending commissions as held (no future commission)
function holdCommissionsForCancelled() {
  var dbc = getDb();
  var custs = dbc.customers || [];
  var held = 0;
  try {
    (dbc.partner_commissions || []).forEach(function(cm) {
      if (cm.status !== 'pending') return;
      var c = custs.find(function(x){ return x.id === cm.customer_id; });
      if (!c || String(c.plan || '') === 'cancelled' || !customerIsPaying(c)) { cm.status = 'held'; held++; }
    });
    saveDb();
    return { held: held };
  } catch(e) { return { held: held, error: e.message }; }
}
// Cron wrapper (safe): runs the engine daily + clearance + hold. Logged.
function runPartnerJobs() {
  var r1 = processPartnerCommissions();
  var r2 = processCommissionClearance();
  var r3 = holdCommissionsForCancelled();
  console.log('[PARTNER] commission job: created=' + r1.created + ' approved=' + r2.approved + ' held=' + r3.held);
  return { created: r1.created, approved: r2.approved, held: r3.held };
}

// ===== PARTNER APPLICATION / JOIN =====
app.post('/api/partner/apply', async (req, res) => {
  try {
    var cfg = partnerConfig();
    if (!cfg.partners_open) return res.status(403).json({ error: 'Partner applications are currently closed.' });
    var partner_type = String(req.body.partner_type || '').toLowerCase();
    if (partner_type !== 'affiliate' && partner_type !== 'sales_partner') return res.status(400).json({ error: 'partner_type must be affiliate or sales_partner' });
    var name = String(req.body.full_name || req.body.name || '').trim();
    var email = String(req.body.email || '').toLowerCase().trim();
    var phone = String(req.body.phone || '').trim();
    var password = String(req.body.password || '');
    if (!name || !email || !password) return res.status(400).json({ error: 'Name, email and password are required' });
    if (!validateEmail(email)) return res.status(400).json({ error: 'Invalid email format' });
    if (password.length < 8) return res.status(400).json({ error: 'Password must be at least 8 characters' });
    var affs = getDb().affiliates || [];
    if (affs.some(function(a){ return String(a.email || '').toLowerCase() === email; })) return res.status(409).json({ error: 'An account with this email already exists. Please log in.' });
    if (partner_type === 'sales_partner') {
      if (!req.body.terms_accepted) return res.status(400).json({ error: 'You must accept the Partner Terms to apply.' });
      if (!req.body.compliance_acknowledged) return res.status(400).json({ error: 'You must acknowledge the compliance rules.' });
    }
    var passwordHash = await bcrypt.hash(password, 10);
    var code = partnerRefCode(affs);
    var p = {
      id: uuidv4(), partner_type: partner_type, status: 'pending',
      referral_code: code, referral_slug: code.toLowerCase(),
      name: name, full_name: name, email: email, phone: phone,
      business_name: String(req.body.business_name || '').trim(),
      sales_experience: String(req.body.sales_experience || '').substring(0, 2000),
      preferred_sectors: Array.isArray(req.body.preferred_sectors) ? req.body.preferred_sectors : [],
      commission_type: partner_type === 'sales_partner' ? 'recurring' : 'one_off',
      commission_amount: partner_type === 'sales_partner' ? Number(cfg.sales_partner_monthly_amount) : Number(cfg.affiliate_one_off_amount),
      commission_duration_months: null,
      terms_version: req.body.terms_version || 'v1',
      terms_accepted_at: partner_type === 'sales_partner' ? new Date().toISOString() : null,
      compliance_acknowledged_at: partner_type === 'sales_partner' ? new Date().toISOString() : null,
      password_hash: passwordHash, payout_rate: Number(cfg.affiliate_one_off_amount), status_note: '',
      created_at: new Date().toISOString(), joined_at: new Date().toISOString(), payouts: [], last_active_at: null
    };
    affs.push(p); saveDb();
    partnerAudit('partner_applied', { partner_id: p.id, partner_type: partner_type, email: email });
    res.status(201).json({ success: true, message: partner_type === 'sales_partner' ? 'Sales Partner application received for review.' : 'Affiliate application received. You can log in once approved.', partner_id: p.id });
  } catch(e) { res.status(500).json({ error: e.message }); }
});

// ===== PARTNER AUTH =====
app.post('/api/partner/login', async (req, res) => {
  try {
    var email = String(req.body.email || '').toLowerCase().trim();
    var password = String(req.body.password || '');
    var p = (getDb().affiliates || []).find(function(a) { return String(a.email || '').toLowerCase() === email; });
    if (!p) return res.status(401).json({ error: 'Invalid email or password' });
    var ok = await bcrypt.compare(password, p.password_hash || '');
    if (!ok) return res.status(401).json({ error: 'Invalid email or password' });
    if (String(p.status || '') === 'pending') return res.status(403).json({ error: 'Your partner account is awaiting activation. Please check back shortly.', pending: true });
    if (['paused', 'suspended', 'rejected', 'closed'].indexOf(String(p.status || '')) !== -1) return res.status(403).json({ error: 'Your partner account is ' + p.status + '. Contact hello@9amleads.com.' });
    p.last_active_at = new Date().toISOString(); saveDb();
    res.json({ token: affiliateToken(p), partner: partnerDashboardSafe(p) });
  } catch(e) { res.status(500).json({ error: e.message }); }
});

// ===== PARTNER DASHBOARD =====
app.get('/api/partner/dashboard', requirePartner, (req, res) => {
  try {
    var p = req.partner; var dbc = getDb(); var now = new Date();
    var isSales = isSalesPartner(p);
    var cfg = partnerConfig();
    var code = p.referral_code || p.code;
    var custs = dbc.customers || [];
    var attr = (dbc.partner_attribution || []).filter(function(a){ return a.partner_id === p.id; });
    var commissions = (dbc.partner_commissions || []).filter(function(c){ return c.partner_id === p.id; });
    // Clicks from analytics events
    var clicks = (dbc.analytics || []).filter(function(e){ return e.event === 'partner_ref_click' && e.props && (e.props.code === code || e.props.partner_id === p.id); }).length;
    var referred = attr.map(function(a){ return custs.find(function(c){ return c.id === a.customer_id; }); }).filter(Boolean);
    var trials = referred.filter(function(c){ return String(c.plan || '') === 'free_trial'; }).length;
    var paidCusts = referred.filter(function(c){ return ['starter','pro','enterprise'].indexOf(c.plan) !== -1; });
    var pending = commissions.filter(function(c){ return c.status === 'pending'; });
    var approved = commissions.filter(function(c){ return c.status === 'approved'; });
    var paid = commissions.filter(function(c){ return c.status === 'paid'; });
    var sum = function(arr){ return arr.reduce(function(a,c){ return a + Number(c.commission_amount || 0); }, 0); };
    var out = {
      partner: partnerDashboardSafe(p),
      referral_link: partnerRefLink(p), referral_code: code,
      clicks: clicks,
      trials: trials, paid: paidCusts.length,
      pending_commission: sum(pending), approved_commission: sum(approved), paid_commission: sum(paid),
      lifetime_earnings: sum(pending) + sum(approved) + sum(paid),
      referrals: referred.map(function(c){ var a = partnerAttributionForCustomer(c.id); return { customer_id: c.id, company: c.company || '', product: c.product, plan: c.plan, signup_at: (a && a.signup_at) || c.created_at, converted_at: (a && a.converted_at) || '' }; }),
      earnings: commissions.slice().sort(function(a,b){ return String(a.commission_period) < String(b.commission_period) ? 1 : -1; }).map(function(c){ return { id: c.id, period: c.commission_period, type: c.commission_type, amount: c.commission_amount, status: c.status, paid_at: c.paid_at || '', customer_ref: c.customer_id.substring(0, 8) }; })
    };
    if (isSales) {
      var prospects = (dbc.partner_prospects || []).filter(function(x){ return x.partner_id === p.id; });
      var feedback = (dbc.partner_feedback || []).filter(function(x){ return x.partner_id === p.id; });
      var today = now.toISOString().split('T')[0];
      var followUps = [];
      prospects.forEach(function(pr) {
        if (pr.status !== 'lost' && pr.status !== 'do_not_contact' && pr.next_follow_up_at && pr.next_follow_up_at.split('T')[0] <= today) {
          followUps.push({ id: pr.id, business_name: pr.business_name, status: pr.status, next_follow_up_at: pr.next_follow_up_at });
        }
      });
      // customer health (deterministic signals only)
      var needsAttention = [], atRisk = [];
      paidCusts.concat(referred.filter(function(c){ return String(c.plan || '') === 'free_trial'; })).forEach(function(c) {
        var a = partnerAttributionForCustomer(c.id);
        var te = c.trial_ends ? new Date(c.trial_ends) : null;
        var daysLeft = te ? Math.ceil((te - now) / 86400000) : 99;
        var risk = (dbc.partner_feedback || []).some(function(f){ return f.customer_id === c.id && f.feedback_type === 'cancellation_risk'; });
        if (risk || (String(c.plan) === 'free_trial' && daysLeft <= 2 && daysLeft > 0)) atRisk.push({ customer_id: c.id, company: c.company || '', product: c.product, plan: c.plan, reason: risk ? 'Cancellation risk reported' : 'Trial ending soon' });
        else if (String(c.plan) === 'free_trial' && daysLeft <= 6 && daysLeft > 0) needsAttention.push({ customer_id: c.id, company: c.company || '', product: c.product, plan: c.plan, reason: 'Trial Day ' + (7 - daysLeft + 1) });
      });
      out.sales = {
        prospects: prospects.map(function(x){ return Object.assign({}, x); }),
        follow_ups_today: followUps,
        active_paying_customers: paidCusts.length,
        active_trials: trials,
        needs_attention: needsAttention, at_risk: atRisk,
        monthly_commission_est: paidCusts.length * (Number(p.commission_amount) || Number(cfg.sales_partner_monthly_amount) || 25),
        pending_commission: sum(pending), approved_commission: sum(approved), paid_commission: sum(paid), lifetime_earnings: sum(pending) + sum(approved) + sum(paid),
        feedback_recent: feedback.slice().sort(function(a,b){ return String(a.created_at) < String(b.created_at) ? 1 : -1; }).slice(0, 10).map(function(f){ return { id: f.id, customer_id: f.customer_id, feedback_type: f.feedback_type, category: f.category, status: f.status, created_at: f.created_at }; })
      };
    }
    // Notifications + portfolio with payment status + recent leads + retention check-ins
    var notifs = (dbc.partner_notifications || []).filter(function(n){ return n.partner_id === p.id; }).slice().sort(function(a,b){ return String(a.created_at) < String(b.created_at) ? 1 : -1; }).slice(0, 20);
    var payStatus = function(c) {
      if (String(c.plan || '') === 'cancelled') return 'cancelled';
      if (['starter', 'pro', 'enterprise'].indexOf(c.plan) !== -1) return 'active';
      if (String(c.plan || '') === 'free_trial') {
        var _te = c.trial_ends ? new Date(c.trial_ends) : null;
        return (_te && _te < new Date()) ? 'trial_expired' : 'trial';
      }
      return 'inactive';
    };
    var followupDue = function(c) {
      var days = Number(partnerConfig().retention_followup_days) || 14;
      var lastContact = null;
      (dbc.partner_notes || []).forEach(function(n){ if (n.partner_id === p.id && n.customer_id === c.id && n.created_at) { if (!lastContact || n.created_at > lastContact) lastContact = n.created_at; } });
      var since = lastContact ? (Date.now() - new Date(lastContact).getTime()) / 86400000 : 999;
      return since >= days;
    };
    out.notifications = notifs.map(function(n){ return { id: n.id, type: n.type, message: n.message, customer_id: n.customer_id, read: !!n.read, created_at: n.created_at }; });
    out.portfolio = referred.map(function(c) {
      var leads = [];
      try { leads = db.prepare('SELECT id, data, status, created_at FROM leads WHERE customer_id = ? ORDER BY created_at DESC LIMIT 6').all(c.id) || []; } catch(le) { leads = []; }
      var received = leads.length, contacted = leads.filter(function(l){ return l.status && String(l.status).toLowerCase() !== 'new'; }).length;
      return {
        customer_id: c.id, company: c.company || '', email: c.email, product: c.product, plan: c.plan,
        payment_status: payStatus(c), followup_due: followupDue(c),
        leads_received: received, leads_contacted: contacted,
        recent_leads: leads.map(function(l){ try { var d = typeof l.data === 'string' ? JSON.parse(l.data) : (l.data || {}); return { address: d.address || d.title || d.company_name || '', town: d.town || d.city || '', source: d.source || d.source_url || '', status: l.status || 'new', created_at: l.created_at }; } catch(e) { return { address: '', status: l.status, created_at: l.created_at }; } })
      };
    });
    res.json({ success: true, dashboard: out });
  } catch(e) { res.status(500).json({ error: e.message }); }
});

