// SPA fallback - serve index.html for unknown routes (but not API routes)
app.get(/^\/(?!api\/).*$/, (req, res) => {
  const paths = [
    path.join(FRONTEND_DIR, req.path === '/' ? 'index.html' : req.path),
    path.join(FRONTEND_DIR, req.path, 'index.html'),
    path.join(ROOT_DIR, req.path === '/' ? '' : req.path.substring(1)),
    path.join(ROOT_DIR, req.path.substring(1), 'index.html'),
    path.join(FRONTEND_DIR, 'index.html')
  ];
  for (const p of paths) {
    if (fs.existsSync(p)) {
      // Block serving sensitive files
      const ext = path.extname(p).toLowerCase();
      if (ext === '.json' || ext === '.md' || ext === '.env' || ext === '.py' || path.basename(p) === 'node_modules') continue;
      // Long browser cache for static media (video/images/css/js) served via the SPA
      // fallback — repeat visitors don't re-download the 7.9MB hero video every visit.
      if (/\.(mp4|webm|png|jpg|jpeg|webp|gif|svg|css|js|woff2?|ttf)$/i.test(p)) res.setHeader('Cache-Control', 'public, max-age=2592000, immutable');
      res.sendFile(p); return;
    }
  }
  // AFFILIATES: /affiliates and /affiliate are public pages served from the portal.
  if (req.path === '/affiliates' || req.path === '/affiliate') {
    return res.redirect('/portal/affiliate.html');
  }
  res.sendFile(path.join(FRONTEND_DIR, 'index.html'));
});

