// POST /api/admin/block-pool-lead — permanently block a moving-pool lead by URL so
// it is NEVER delivered to any customer again (commercial / wrong-address /
// out-of-area leads the founder flagged). Marks the pool entry rejected + removes
// any already-delivered instance from customers. Body: { url, reason? }
app.post('/api/admin/block-pool-lead', adminAuth, (req, res) => {
  try {
    var targetUrl = String((req.body && req.body.url) || '').split('#')[0].split('?')[0].replace(/\/+$/, '').toLowerCase().trim();
    var reason = (req.body && req.body.reason) || 'blocked by admin';
    if (!targetUrl) return res.status(400).json({ error: 'url required' });
    var dbB = getDb();
    var blockedNow = 0;
    // Mark matching leads rejected in the moving pool files
    ['moving-leads.json', 'moving-leads-fresh.json'].forEach(function(pf) {
      try {
        var fp = path.join(DATA_DIR, pf);
        var poolArr = JSON.parse(fs.readFileSync(fp, 'utf-8'));
        if (!Array.isArray(poolArr)) return;
        var changed = false;
        poolArr.forEach(function(l) {
          var lu = String(l.url || '').split('#')[0].split('?')[0].replace(/\/+$/, '').toLowerCase().trim();
          if (lu === targetUrl) { l.rejected = true; l.rejected_at = new Date().toISOString(); l.reject_reason = reason; blockedNow++; changed = true; }
        });
        if (changed) fs.writeFileSync(fp, JSON.stringify(poolArr, null, 2));
      } catch(e) {}
    });
    // Also remove any already-delivered instance from customers (so it leaves today's
    // batches and a replacement is sent on the next delivery).
    var removedLeads = 0;
    dbB.leads = (dbB.leads || []).map(function(l) {
      var d = {}; try { d = JSON.parse(l.data || '{}'); } catch(e) {}
      var lu = String(d.url || '').split('#')[0].split('?')[0].replace(/\/+$/, '').toLowerCase().trim();
      if (lu === targetUrl) {
        if (l.delivered) { removedLeads++; l.delivered = 0; l.delivered_at = null; l.status = 'removed'; }
        d.rejected = true; d.reject_reason = reason;
        l.data = JSON.stringify(d);
      }
      return l;
    });
    saveDb();
    res.json({ success: true, blocked_in_pool: blockedNow, removed_from_customers: removedLeads, url: targetUrl, reason: reason });
  } catch(e) { res.status(500).json({ error: e.message }); }
});

// POST /api/admin/reject-lead — admin rejects a lead (wrong address etc.) + sends a
// replacement, same as the customer's reject. Body: { lead_id, reason? }
app.post('/api/admin/reject-lead', adminAuth, (req, res) => {
  try {
    var leadId = (req.body && req.body.lead_id) || '';
    var reason = (req.body && req.body.reason) || 'rejected by admin';
    if (!leadId) return res.status(400).json({ error: 'lead_id required' });
    var dbR = getDb();
    var lead = (dbR.leads || []).find(function(l) { return l.id === leadId; });
    if (!lead) return res.status(404).json({ error: 'Lead not found' });
    var d = {}; try { d = JSON.parse(lead.data || '{}'); } catch(e) {}
    d.rejected = true;
    d.rejected_at = new Date().toISOString();
    d.reject_reason = reason;
    lead.data = JSON.stringify(d);
    saveDb();
    // A replacement is picked by the next delivery (the pool has in-area leads).
    res.json({ success: true, message: 'Lead rejected. A replacement will be sent with the next delivery.', lead_id: leadId });
  } catch(e) { res.status(500).json({ error: e.message }); }
});

// GET /api/admin/rejected-leads — all rejected leads across customers (with the
// customer + address + reason) so admin can review before replacing.
app.get('/api/admin/rejected-leads', adminAuth, (req, res) => {
  try {
    var dbR = getDb();
    var custMap = {};
    (dbR.customers || []).forEach(function(c) { custMap[c.id] = c; });
    var rows = (dbR.leads || []).map(function(l) {
      var d = {}; try { d = JSON.parse(l.data || '{}'); } catch(e) {}
      if (!d.rejected) return null;
      var cust = custMap[l.customer_id] || {};
      return { lead_id: l.id, customer_id: l.customer_id, customer_email: cust.email || '', customer_company: cust.company || '', product: l.product || cust.product || '', address: d.fullAddress || d.address || d.deceasedAddress || '', postcode: d.postcode || '', url: d.url || '', reason: d.reject_reason || 'rejected', rejected_at: d.rejected_at || l.created_at || '', delivered: !!l.delivered };
    }).filter(Boolean).sort(function(a, b) { return String(b.rejected_at).localeCompare(String(a.rejected_at)); });
    res.json({ success: true, count: rows.length, leads: rows });
  } catch(e) { res.status(500).json({ error: e.message }); }
});

// POST /api/auth/update-areas — customer updates their postcode areas from the
// dashboard. Enforces the same rules as signup: max 5 areas, no "all of UK".
// These areas are what delivery uses to send leads, so keeping them correct here
// is what guarantees the customer only receives leads from their chosen areas.
app.post('/api/auth/update-areas', authMiddleware, (req, res) => {
  try {
    var areas = req.body && req.body.areas;
    if (!Array.isArray(areas)) return res.status(400).json({ error: 'areas must be an array' });
    var me = db.prepare('SELECT * FROM customers WHERE id = ?').get(req.user.id);
    var planKey = String((me && me.plan) || 'free_trial').toLowerCase();
    var isPaidUnlimited = (planKey === 'pro' || planKey === 'enterprise');
    var maxAreas = parseInt(process.env.MAX_POSTCODE_AREAS_PER_PLAN || '5', 10);
    var allUk = areas.some(function(a){ return /all.?uk|uk.?wide|nationwide|whole.?uk/i.test(String(a)); });
    if (allUk) {
      // "All of UK" is available to EVERY customer now — no specific postcode
      // areas needed. Coverage becomes ukwide so the delivery skips area matching.
      db.prepare('UPDATE customers SET coverage = ?, target_areas = ? WHERE id = ?').run('ukwide', JSON.stringify(['All UK']), req.user.id);
      try {
        var pcfgU = {}; try { pcfgU = JSON.parse(me.product_config || '{}'); } catch(e) {}
        var pProdU = String((me && me.product) || '').toLowerCase();
        if (pcfgU[pProdU]) { pcfgU[pProdU].target_areas = JSON.stringify(['All UK']); pcfgU[pProdU].coverage = 'ukwide'; }
        else pcfgU[pProdU] = { target_areas: JSON.stringify(['All UK']), coverage: 'ukwide' };
        db.prepare('UPDATE customers SET product_config = ? WHERE id = ?').run(JSON.stringify(pcfgU), req.user.id);
      } catch(e2) {}
      saveDb();
      return res.json({ success: true, areas: ['All UK'], coverage: 'ukwide' });
    }
    if (areas.length === 0) return res.status(400).json({ error: 'Please choose at least one area or county, or select All of UK.', too_few_areas: true });
    if (!isPaidUnlimited && areas.length > maxAreas) return res.status(400).json({ error: 'Please choose at most ' + maxAreas + ' postcode areas.', too_many_areas: true, max_areas: maxAreas });
    var clean = areas.map(function(a){ return String(a).toUpperCase().trim(); }).filter(Boolean);
    // PER-PRODUCT MINIMUMS (same rules as signup): moving must keep exactly the
    // full 5 postcode areas; other products must keep at least 3 areas/counties —
    // otherwise delivery under-supplies and the customer's daily promise breaks.
    var prodKey = String((me && me.product) || '').toLowerCase();
    if (!isPaidUnlimited && prodKey === 'moving' && clean.length < maxAreas) {
      return res.status(400).json({ error: 'Moving leads require exactly ' + maxAreas + ' postcode areas (you selected ' + clean.length + ').', too_few_areas: true, max_areas: maxAreas });
    }
    if (!isPaidUnlimited && prodKey !== 'moving' && clean.length > 0 && clean.length < 3) {
      return res.status(400).json({ error: 'Please keep at least 3 areas or counties for your ' + prodKey + ' leads (you selected ' + clean.length + ').', too_few_areas: true, min_areas: 3 });
    }
    // Coverage: infer from the chosen areas. Postcode-area codes (1-2 letters)
    // => 'postcode'; anything else (county/region names) => 'county'. This also
    // resets a stale 'ukwide' coverage when a customer switches back from All of
    // UK to specific areas — otherwise the dashboard keeps showing All of UK.
    var newCov = clean.every(function(a){ return /^[A-Z]{1,3}$/i.test(a); }) ? 'postcode' : (me.coverage === 'region' ? 'region' : 'county');
    db.prepare('UPDATE customers SET target_areas = ?, coverage = ? WHERE id = ?').run(JSON.stringify(clean), newCov, req.user.id);
    // Keep product_config in sync so the delivery + dashboard read the SAME areas.
    try {
      var pcfg = {}; try { pcfg = JSON.parse(me.product_config || '{}'); } catch(e) {}
      if (pcfg[prodKey]) {
        pcfg[prodKey].target_areas = JSON.stringify(clean);
        pcfg[prodKey].coverage = newCov;
        db.prepare('UPDATE customers SET product_config = ? WHERE id = ?').run(JSON.stringify(pcfg), req.user.id);
      }
    } catch(e2) {}
    saveDb();
    res.json({ success: true, areas: clean, coverage: newCov });
  } catch(e) { res.status(500).json({ error: e.message }); }
});

// POST /api/auth/reactivate-trial — claim the "fresh 1-week free trial" offered
// after ~3 months. Resets trial_ends (+7 days), restarts the campaign sequence
// (so they get the full trial journey again) and resumes delivery. Capped by
// MAX_TRIAL_RESETS (default 2) so the funnel converts, not freeloads.
app.post('/api/auth/reactivate-trial', authMiddleware, (req, res) => {
  try {
    var cust = db.prepare('SELECT * FROM customers WHERE id = ?').get(req.user.id);
    if (!cust) return res.status(404).json({ error: 'User not found' });
    if (cust.plan !== 'free_trial') {
      return res.json({ success: true, already_active: true, message: 'Your account is already active \u2014 no need to reactivate.' });
    }
    var maxResets = parseInt(process.env.MAX_TRIAL_RESETS || '2', 10);
    var resets = parseInt(cust.trial_resets || '0', 10);
    if (resets >= maxResets) {
      return res.status(400).json({ error: 'You\u2019ve already used your free reactivations. Your package options are in your dashboard.', limit_reached: true, resets_used: resets, max_resets: maxResets });
    }
    var newEnd = new Date(Date.now() + 7 * 86400000).toISOString();
    db.prepare('UPDATE customers SET trial_ends = ?, trial_cancelled = NULL, campaign_sent = ?, trial_resets = ? WHERE id = ?')
      .run(newEnd, '[]', resets + 1, req.user.id);
    saveDb();
    res.json({ success: true, message: 'Your 1-week free trial has been reactivated. Your leads resume at 9am tomorrow.', trial_ends: newEnd, resets_used: resets + 1, max_resets: maxResets });
  } catch(e) { res.status(500).json({ error: e.message }); }
});

// ===== PASSWORD RESET =====

// POST /api/auth/forgot-password — send reset link
app.post('/api/auth/forgot-password', async (req, res) => {
  try {
    const { email } = req.body;
    if (!email) return res.status(400).json({ error: 'Email is required' });

    const customer = db.prepare('SELECT * FROM customers WHERE email = ?').get(email.toLowerCase());
    // Always return success to prevent email enumeration
    if (!customer) return res.json({ message: 'If that email exists, a reset link has been sent.' });

    const resetToken = require('crypto').randomBytes(32).toString('hex');
    const resetExpires = new Date(Date.now() + 3600000).toISOString(); // 1 hour

    db.prepare('UPDATE customers SET reset_token = ?, reset_expires = ? WHERE id = ?').run(resetToken, resetExpires, customer.id);
    saveDb();

    const resetUrl = PUBLIC_URL.replace(/\/+$/, '') + '/portal/reset-password.html?token=' + resetToken;

    try {
      await sendBrevoEmail(
        { email: customer.email, name: customer.contact_name || customer.company },
        'Reset your 9amLeads password',
        '<div style="font-family:Inter,Arial,Helvetica,sans-serif;background:#f1f5f9;color:#1e293b;padding:28px 20px"><div style="max-width:600px;margin:0 auto"><table width="100%" cellpadding="0" cellspacing="0"><tbody>' + buildEmailHeader() + '<tr><td style="background:#ffffff;padding:28px 30px;color:#1e293b;text-align:center"><h2 style="font-size:20px;font-weight:800;color:#0f172a;margin:0 0 12px;text-align:center">Password Reset</h2><p style="font-size:14px;color:#475569;line-height:1.7;margin:0 0 16px;text-align:center">Click the button below to reset your password. This link expires in 1 hour.</p><table width="100%" cellpadding="0" cellspacing="0"><tr><td align="center" style="padding:4px 0 16px"><a href="' + resetUrl + '" style="display:inline-block;padding:12px 32px;background-color:#0ea5e9;background-image:linear-gradient(135deg,#0ea5e9,#2563eb);color:#fff;text-decoration:none;border-radius:50px;font-size:14px;font-weight:700">Reset Password</a></td></tr></table><p style="font-size:13px;color:#64748b;line-height:1.6;margin:0;text-align:center">If you did not request this, please ignore this email.</p></td></tr>' + buildEmailFooter() + '</tbody></table></div></div>'
      );
    } catch (e) {
      console.log('[PASSWORD] Reset email failed:', e.message, '- Token stored for manual reset:', resetToken);
    }

    res.json({ message: 'If that email exists, a reset link has been sent.', reset_url: resetUrl });
  } catch (e) {
    console.error('Forgot password error:', e);
    res.status(500).json({ error: 'Internal server error' });
  }
});

// POST /api/auth/reset-password — reset password with token
app.post('/api/auth/reset-password', async (req, res) => {
  try {
    const { token, password } = req.body;
    if (!token || !password) return res.status(400).json({ error: 'Token and password are required' });
    if (password.length < 8) return res.status(400).json({ error: 'Password must be at least 8 characters' });

    const customer = db.prepare('SELECT * FROM customers WHERE reset_token = ?').get(token);
    if (!customer) return res.status(400).json({ error: 'Invalid or expired reset token' });

    const expires = new Date(customer.reset_expires);
    if (new Date() > expires) return res.status(400).json({ error: 'Reset token has expired. Please request a new one.' });

    const password_hash = await bcrypt.hash(password, 10);
    db.prepare('UPDATE customers SET password_hash = ?, reset_token = NULL, reset_expires = NULL WHERE id = ?').run(password_hash, customer.id);
    saveDb();

    res.json({ message: 'Password reset successfully. You can now log in with your new password.' });
  } catch (e) {
    console.error('Reset password error:', e);
    res.status(500).json({ error: 'Internal server error' });
  }
});

// ===== ONBOARDING API =====
// GET /api/onboarding — customer onboarding checklist and progress
app.get('/api/onboarding', authMiddleware, (req, res) => {
  try {
    var db2 = getDb();
    const customer = db.prepare('SELECT * FROM customers WHERE id = ?').get(req.user.id);
    if (!customer) return res.status(404).json({ error: 'User not found' });
    const leads = (db2.leads || []).filter(l => l.customer_id === req.user.id);
    const hasLeads = leads.length > 0;
    const hasContacted = leads.some(l => l.lead_status === 'contacted' || l.lead_status === 'interested' || l.lead_status === 'quoted' || l.lead_status === 'won');
    const hasPipeline = leads.some(l => l.lead_status && l.lead_status !== 'new' && l.lead_status !== 'lost');
    const hasWon = leads.some(l => l.lead_status === 'won');
    const hasCrm = !!(customer.crm_webhook_url || (db.crm_webhooks || []).find(w => w.customer_id === req.user.id));
    const hasProfile = !!(customer.company && customer.contact_name);
    const hasAreas = (customer.target_areas && JSON.parse(customer.target_areas).length > 0);
    const hasFilters = !!(customer.biz_field2);

    const checklist = [
      { id: 'profile', label: 'Complete business profile', done: hasProfile },
      { id: 'lead_type', label: 'Confirm lead type', done: !!customer.product },
      { id: 'coverage', label: 'Confirm coverage area', done: hasAreas },
      { id: 'crm', label: 'Connect CRM', done: hasCrm },
      { id: 'first_delivery', label: 'View first 9am delivery', done: hasLeads },
      { id: 'first_contact', label: 'Contact first lead', done: hasContacted },
      { id: 'pipeline', label: 'Move first lead to pipeline', done: hasPipeline },
      { id: 'win', label: 'Mark lead outcome (won/lost)', done: hasWon }
    ];
    const total = checklist.length;
    const completed = checklist.filter(i => i.done).length;
    const progress = Math.round((completed / total) * 100);
    const state = progress === 100 ? 'completed' : (completed > 0 ? 'in_progress' : 'not_started');

    // Save onboarding state to customer record
    if (customer.onboarding_state !== state) {
      db.prepare('UPDATE customers SET onboarding_state = ?, onboarding_progress = ? WHERE id = ?').run(state, progress, req.user.id);
      saveDb();
    }

    res.json({ state, progress, completed, total, checklist, customer_name: customer.contact_name || customer.company || '' });
  } catch(e) { res.status(500).json({ error: e.message }); }
});

// GET /api/health-score — customer health score
app.get('/api/health-score', authMiddleware, (req, res) => {
  try {
    var db2 = getDb();
    const customer = db.prepare('SELECT * FROM customers WHERE id = ?').get(req.user.id);
    if (!customer) return res.status(404).json({ error: 'User not found' });
    const leads = (db.leads || []).filter(l => l.customer_id === req.user.id);
    const delivered = leads.filter(l => l.delivered);
    const contacted = leads.filter(l => l.lead_status && l.lead_status !== 'new');
    const wonLeads = leads.filter(l => l.lead_status === 'won');
    const contactedRate = delivered.length > 0 ? Math.round((contacted.length / delivered.length) * 100) : 0;
    const hasRecentLogin = customer.last_login_at && (Date.now() - new Date(customer.last_login_at).getTime()) < 7 * 86400000;
    const hasCrm = !!(customer.crm_webhook_url || (db.crm_webhooks || []).find(w => w.customer_id === req.user.id));
    const hasLowSupply = db.scraper_logs && db.scraper_logs.length > 0;
    const failedPayment = parseInt(customer.fail_count) > 0;

    let score = 100;
    if (!hasRecentLogin) score -= 20;
    if (contactedRate < 30) score -= 15;
    if (!hasCrm) score -= 10;
    if (wonLeads.length === 0) score -= 10;
    if (delivered.length === 0) score -= 10;
    if (failedPayment) score -= 25;
    if (customer.plan === 'cancelled') score -= 50;

    const status = score >= 80 ? 'Healthy' : score >= 60 ? 'Needs Attention' : score >= 40 ? 'At Risk' : 'Critical';
    res.json({ score, status, contacted_rate: contactedRate, recent_login: hasRecentLogin, crm_connected: hasCrm, won_count: wonLeads.length, failed_payment: failedPayment });
  } catch(e) { res.status(500).json({ error: e.message }); }
});


// GET /api/admin/founder-dashboard — founder analytics (admin only)
app.get('/api/admin/founder-dashboard', adminAuth, (req, res) => {
  try {
    const db = getDb();
    const customers = (db.customers || []);
    const leads = (db.leads || []);
    const subscriptions = (db.subscriptions || []);
    const activeCustomers = customers.filter(c => c.plan && c.plan !== 'cancelled' && (!c.trial_ends || new Date(c.trial_ends) > new Date()));
    const trialCustomers = customers.filter(c => c.plan === 'free_trial');
    const cancelledCustomers = customers.filter(c => c.plan === 'cancelled');

    // MRR calculation
    const planPrices = { starter: 25, pro: 49, enterprise: 99 };
    var mrr = activeCustomers.reduce(function(sum, c) { return sum + (planPrices[c.plan] || 0); }, 0);
    var weeklyRr = activeCustomers.reduce(function(sum, c) { return sum + (planPrices[c.plan] || 0); }, 0);

    // Trial conversion
    var everTrialled = customers.filter(c => c.plan === 'free_trial' || (c.created_at && (c.plan === 'starter' || c.plan === 'pro' || c.plan === 'enterprise')));
    var converted = customers.filter(c => c.plan !== 'free_trial' && c.plan !== 'cancelled' && c.plan !== '');
    var trialConversion = everTrialled.length > 0 ? Math.round((converted.length / everTrialled.length) * 100) : 0;

    // Churn
    var totalEver = customers.length;
    var churnRate = totalEver > 0 ? Math.round((cancelledCustomers.length / totalEver) * 100) : 0;

    // Revenue by product
    var revenueByProduct = {};
    customers.forEach(function(c) {
      if (!revenueByProduct[c.product]) revenueByProduct[c.product] = 0;
      revenueByProduct[c.product] += planPrices[c.plan] || 0;
    });

    // Lead stats
    var today = new Date().toISOString().split('T')[0];
    var leadsToday = leads.filter(l => l.created_at && l.created_at.startsWith(today));
    var deliveredToday = leads.filter(l => l.delivered_at && l.delivered_at.startsWith(today));

    // Customer health overview
    var atRiskCustomers = activeCustomers.filter(function(c) { return c.last_login_at && (Date.now() - new Date(c.last_login_at).getTime()) > 7 * 86400000; });
    var failedPayments = activeCustomers.filter(function(c) { return parseInt(c.fail_count) > 0; });

    res.json({
      mrr: mrr,
      weekly_revenue: weeklyRr,
      active_customers: activeCustomers.length,
      trial_customers: trialCustomers.length,
      trial_conversion_rate: trialConversion,
      cancelled_customers: cancelledCustomers.length,
      churn_rate: churnRate,
      failed_payments: failedPayments.length,
      revenue_by_product: revenueByProduct,
      customers_by_plan: { starter: customers.filter(c => c.plan === 'starter').length, pro: customers.filter(c => c.plan === 'pro').length, enterprise: customers.filter(c => c.plan === 'enterprise').length, free_trial: trialCustomers.length, cancelled: cancelledCustomers.length },
      leads_scraped_today: leadsToday.length,
      leads_delivered_today: deliveredToday.length,
      at_risk_customers: atRiskCustomers.length,
      total_customers: customers.length,
      total_leads: leads.length,
      support_requests: (db.support_requests || []).filter(s => !s.resolved).length
    });
  } catch(e) { res.status(500).json({ error: e.message }); }
});

// GET /api/public-stats — public trust metrics (cached, safe for website)
var publicStatsCache = { data: null, expires: 0 };
app.get('/api/public-stats', async (req, res) => {
  try {
    if (publicStatsCache.data && publicStatsCache.expires > Date.now()) {
      return res.json(publicStatsCache.data);
    }
    const db = getDb();
    const today = new Date().toISOString().split('T')[0];
    const thisMonth = today.substring(0, 7);
    const leads = (db.leads || []);
    const leadsThisMonth = leads.filter(l => l.created_at && l.created_at.startsWith(thisMonth));
    const customers = (db.customers || []).filter(c => c.plan && c.plan !== 'cancelled');
    const delivered = leads.filter(l => l.delivered);
    const totalValue = delivered.reduce(function(sum, l) { return sum + (parseInt(l.estimated_value) || parseInt(l.deal_value) || 0); }, 0);

    // Get areas covered
    var areasSet = new Set();
    customers.forEach(function(c) {
      try { JSON.parse(c.target_areas || '[]').forEach(function(a) { areasSet.add(a); }); } catch(e) {}
    });

    var stats = {
      opportunities_this_month: leadsThisMonth.length,
      estimated_value_delivered: totalValue,
      active_businesses: customers.length,
      average_roi: customers.length > 0 ? Math.round(totalValue / (customers.length * 100)) : 0,
      leads_scraped_today: leads.filter(l => l.created_at && l.created_at.startsWith(today)).length,
      uk_areas_covered: areasSet.size,
      friendly_label: leadsThisMonth.length > 10 ? (leadsThisMonth.length + ' opportunities delivered this month') : 'Fresh opportunities delivered daily across the UK',
      generated_at: new Date().toISOString()
    };
    publicStatsCache = { data: stats, expires: Date.now() + 300000 }; // 5 min cache
    res.json(stats);
  } catch(e) { res.status(500).json({ error: e.message }); }
});

