// GET /api/leads
app.get('/api/leads', authMiddleware, (req, res) => {
  const customer = db.prepare('SELECT * FROM customers WHERE id = ?').get(req.user.id);
  // TRIAL-GATE: an expired free trial's leads are HIDDEN until the customer pays
  // for a package (Starter/Pro/Enterprise). Once they pay, plan != free_trial and
  // their previous + new leads show again. This stops a trial account that ended
  // from continuing to use the dashboard's lead history for free.
  var now = new Date();
  var trialGated = customer && customer.plan === 'free_trial' && customer.trial_ends && new Date(customer.trial_ends) < now;
  if (trialGated) {
    return res.json({ gated: true, trial_ended: true, message: 'Your free trial has ended. Upgrade to a Starter, Pro or Enterprise package to unlock your leads again.', leads: [] });
  }
  const leads = db.prepare(
    'SELECT * FROM leads WHERE customer_id = ? ORDER BY created_at DESC LIMIT 50'
  ).all(req.user.id);

  const nowIso = new Date().toISOString();
  const visible = leads.filter(function(l) {
    // Hide rejected leads from the customer dashboard (they're queued for replacement).
    var d0 = {}; try { d0 = JSON.parse(l.data || '{}'); } catch(e) {}
    if (d0.rejected) return false;
    // Hide REMOVED leads (reset by admin replace-leads / force-replace, or blocked).
    // A reset marks today's leads delivered=0 + status='removed' so a force re-delivery
    // REPLACES them — the customer must only ever see their CURRENT, correct batch.
    if (l.status === 'removed') return false;
    if (l.delivered || l.delivered_at) return true;
    return !(l.release_at && l.release_at > nowIso);
  });

    res.json(visible
    // Only filter PENDING leads by address completeness. DELIVERED leads are the
    // customer's real history (they were emailed + confirmed) and must ALWAYS show
    // on the dashboard — even older ones scraped before full postcodes were
    // standardised ("36 Cambridge Road, Kingston Upon Thames, Surrey" with no
    // postcode still counts toward Today/Week/Month/All-Time). The address filter
    // exists to hide incomplete PENDING leads, never delivered history.
    .filter(function(l) { return l.delivered || leadHasUsableAddress(l, customer ? customer.product : l.product); })
    // DEDUPE by URL/address+postcode: repeated/churned deliveries can leave duplicate
    // rows for the same property (same URL, or same street+number+postcode from
    // multiple scrapes). The customer must see each UNIQUE lead once, and the
    // dashboard KPIs (today/week/month) must never be inflated by duplicates.
    .filter(function(l, idx, arr) {
      var _k = (function() { try { var d = JSON.parse(l.data || '{}'); var u = String(d.url || '').split('#')[0].split('?')[0].replace(/\/+$/,'').toLowerCase().trim(); if (u) return 'u:' + u; var a = String(d.fullAddress || d.address || '').toLowerCase().replace(/[^a-z0-9]/g, '').slice(0, 28); var pc = String(d.postcode || '').toUpperCase().replace(/[^A-Z0-9]/g, ''); return 'a:' + a + '|' + pc; } catch(e) { return ''; } })();
      if (!_k) return true;
      for (var _j = 0; _j < idx; _j++) {
        var _other = (function() { try { var d2 = JSON.parse(arr[_j].data || '{}'); var u2 = String(d2.url || '').split('#')[0].split('?')[0].replace(/\/+$/,'').toLowerCase().trim(); if (u2) return 'u:' + u2; var a2 = String(d2.fullAddress || d2.address || '').toLowerCase().replace(/[^a-z0-9]/g, '').slice(0, 28); var pc2 = String(d2.postcode || '').toUpperCase().replace(/[^A-Z0-9]/g, ''); return 'a:' + a2 + '|' + pc2; } catch(e) { return ''; } })();
        if (_other && _other === _k) return false;
      }
      return true;
    })
    .map(l => {
    const parsed = JSON.parse(l.data || '{}');
    if (customer && customer.product === 'moving') {
      if (parsed.address) parsed.address = stripPartialPostcode(stripRegionTags(stripGuessedFlatPrefix(parsed.address)));
      if (parsed.fullAddress) parsed.fullAddress = stripPartialPostcode(stripRegionTags(stripGuessedFlatPrefix(parsed.fullAddress)));
    }
    const scored = attachOpportunityScore(parsed, customer?.product || l.product);
    // DIAGNOSTIC: expose the raw lead id + customer_id so the direct-mail payment
    // path can be debugged against the exact ids the dashboard hands to send-lead.
    var dRow = { ...l, data: parsed, opportunity_score: scored.score, opportunity_category: scored.category, opportunity_label: scored.label, opportunity_reasons: scored.reasons };
    if (l.id && l.id.toString().indexOf('17de6e99') !== -1) {
      dRow._diag = { lead_id: l.id, customer_id: l.customer_id, session_customer_id: customer ? customer.id : null, has_data: !!l.data, postcode: parsed.postcode };
    }
    return dRow;
  }));
});

