// POST /api/admin/rejected-leads/approve — admin approves a replacement for a rejected
// lead: marks the old one replaced, and (optionally) adds a fresh lead to the customer
// for their next delivery or sends it now.
app.post('/api/admin/rejected-leads/approve', adminAuth, async (req, res) => {
  try {
    var leadId = (req.body && req.body.lead_id) || '';
    var sendNow = !!(req.body && req.body.send_now);
    if (!leadId) return res.status(400).json({ error: 'lead_id required' });
    var lead = db.prepare('SELECT * FROM leads WHERE id = ?').get(leadId);
    if (!lead) return res.status(404).json({ error: 'Lead not found' });
    var parsed = {}; try { parsed = JSON.parse(lead.data || '{}'); } catch(e) {}
    parsed.replaced = true;
    parsed.replaced_at = new Date().toISOString();
    db.prepare('UPDATE leads SET data = ? WHERE id = ?').run(JSON.stringify(parsed), leadId);
    var result = { success: true, message: 'Rejected lead marked as replaced.' };
    // Add a fresh replacement lead to the customer's account (undelivered), so the
    // next 9am delivery sends it. Optionally send now via the deliver endpoint.
    try {
      var cust = db.prepare('SELECT * FROM customers WHERE id = ?').get(lead.customer_id);
      if (cust) {
        var repLead = await createReplacementLead(cust, lead.product || 'moving');
        result.replacement = repLead ? { lead_id: repLead.id, address: repLead.address, postcode: repLead.postcode } : null;
      }
    } catch(rErr) { result.replacement_error = rErr.message; }
    res.json(result);
  } catch(e) { res.status(500).json({ error: e.message }); }
});

// Create a replacement lead for a customer from the moving pool — a fresh lead in
// their chosen postcode areas with a PROPER address (door number / flat / named
// building). Added as undelivered so the next 9am delivery sends it. Returns the
// lead or null if none available.
function hasProperAddressModule(addr, pc) {
  return hasUsablePremiseAddress(addr, pc);
}
async function createReplacementLead(cust, product) {
  try {
    var areas = [];
    try { areas = JSON.parse(cust.target_areas || '[]'); } catch(e) {}
    var file = (PRODUCT_LEAD_FILES[product] && PRODUCT_LEAD_FILES[product].file) || 'moving-leads.json';
    var poolPath = path.join(DATA_DIR, file);
    var pool = [];
    try {
      var raw = JSON.parse(fs.readFileSync(poolPath, 'utf-8'));
      if (Array.isArray(raw)) pool = raw;
      else if (raw && typeof raw === 'object') { Object.keys(raw).forEach(function(k){ if (k.indexOf('_') === 0) return; if (Array.isArray(raw[k])) pool = pool.concat(raw[k]); }); }
    } catch(e) {}
    var cutoff = getFreshCutoffIso();
    var seen = {};
    // County-aware matching (mirrors the main delivery loop). Set up only if needed.
    var countyPostcodes = {
      'essex': ['CM','CO','SS','IG'],'hertfordshire':['AL','EN','HP','SG','WD'],'kent':['CT','DA','ME','TN'],
      'surrey':['CR','GU','KT','RH','SM','TW'],'sussex':['BN','RH','TN'],'hampshire':['GU','PO','SO','SP','RG'],
      'berkshire':['RG','SL'],'buckinghamshire':['HP','MK','SL'],'oxfordshire':['OX'],'bedfordshire':['LU','MK'],
      'cambridgeshire':['CB','PE'],'norfolk':['IP','NR','PE'],'suffolk':['CO','IP','NR'],
      'london':['E','EC','N','NW','SE','SW','W','WC','BR','CR','DA','EN','HA','IG','KT','RM','SM','TN','TW','UB'],
      'greater-london':['E','EC','N','NW','SE','SW','W','WC','BR','CR','DA','EN','HA','IG','KT','RM','SM','TN','TW','UB'],
      'birmingham':['B'],'manchester':['M'],'liverpool':['L'],'leeds':['LS'],'sheffield':['S'],
      'bristol':['BS'],'nottingham':['NG'],'leicester':['LE'],'cardiff':['CF'],'edinburgh':['EH'],
      'glasgow':['G'],'belfast':['BT'],'cheshire':['CH','WA'],'lancashire':['BB','BL','FY','LA','PR'],
      'north-east':['DH','DL','NE','SR','TS'],'north-west':['BB','BL','CH','CW','FY','L','LA','M','OL','PR','SK','WA','WN'],
      'yorkshire':['BD','HD','HG','HU','HX','LS','S','WF','YO'],'yorkshire-and-the-humber':['BD','HD','HG','HU','HX','LS','S','WF','YO'],
      'east-midlands':['DE','DN','LE','LN','NG','NN','PE'],'west-midlands-region':['B','CV','DY','HR','ST','SY','TF','WR','WS','WV'],
      'east-of-england':['AL','CB','CM','CO','HP','IP','LU','NR','PE','SG','SS'],'south-east':['BN','CT','DA','GU','HP','KT','ME','MK','OX','PO','RG','RH','SL','SN','SO','SS','TN','TW'],
      'south-west':['BA','BS','DT','EX','GL','PL','SN','SP','TA','TQ','TR'],'wales':['CF','LD','LL','NP','SA','SY']
    };
    var ukwide = /all.?uk|uk.?wide/i.test((areas||[]).join(' '));
    for (var i=0;i<pool.length;i++){
      var fl = pool[i];
      if (fl.commercial || seen[fl.id]) continue;
      seen[fl.id]=1;
      var fd = fl.firstVisibleDate || fl.addedOn || fl.updateDate || fl.scrapedAt || fl.publishedDate || fl.receivedDate || fl.grantDate || fl.incorporationDate || '';
      if (fd && fd < cutoff) continue;
      var fpc = String(fl.postcode || fl.location || '').toUpperCase().trim();
      // Must be in the customer's chosen areas (or all-uk for paid).
      if (!ukwide && areas.length) {
        var areaOfPool = extractPostcodeArea(fpc || fl.address || '');
        if (!areaOfPool) continue;
        var hit = false;
        var areasAreCounties = areas.some(function(a){ return !/^[A-Z]{1,3}$/i.test(a); });
        if (areasAreCounties) {
          for (var _cc=0; _cc<areas.length; _cc++) {
            var al = String(areas[_cc] || '').toLowerCase().replace(/[\s-]+/g,'-');
            if ((countyPostcodes[al] || []).indexOf(areaOfPool) >= 0) { hit = true; break; }
          }
        } else {
          hit = areas.some(function(a){ return extractPostcodeArea(a) === areaOfPool; });
        }
        // NATIONAL FALLBACK for tenders/probate: accept even if no area matched.
        if (!hit && (product === 'tenders' || product === 'probate')) hit = true;
        if (!hit) continue;
      }
      // Must have a PROPER address (door number / flat / named building), not a bare street.
      var fAddr = fl.fullAddress || fl.address || '';
      if (!fAddr) continue;
      if (!hasProperAddressModule(fAddr, fpc)) continue;
      var fld = Object.assign({}, fl, { id: fl.id, address: fAddr, postcode: fpc, product: product });
      var nr = { id: 'lead_' + Date.now() + '_repl_' + Math.floor(Math.random()*1000), customer_id: cust.id, product: product, data: JSON.stringify(fld), status: 'new', delivered: 0, created_at: new Date().toISOString(), delivered_at: null, release_at: new Date().toISOString().split('T')[0] + 'T09:00:00.000Z' };
      db.prepare('INSERT INTO leads (id, customer_id, product, data, status, delivered, created_at, delivered_at, release_at) VALUES (?,?,?,?,?,?,?,?,?)').run(nr.id, cust.id, product, nr.data, 'new', 0, nr.created_at, null, nr.release_at);
      return { id: nr.id, address: fAddr, postcode: fpc };
    }
    return null;
  } catch(e) { return null; }
}

// PATCH /api/leads/:id/status
app.patch('/api/leads/:id/status', authMiddleware, (req, res) => {
  const { status } = req.body;
  const valid = ['new', 'contacted', 'booked', 'closed', 'lost'];
  if (!valid.includes(status)) {
    return res.status(400).json({ error: 'Invalid status' });
  }

  const lead = db.prepare('SELECT * FROM leads WHERE id = ? AND customer_id = ?').get(req.params.id, req.user.id);
  if (!lead) return res.status(404).json({ error: 'Lead not found' });

  db.prepare('UPDATE leads SET status = ? WHERE id = ?').run(status, req.params.id);
  res.json({ success: true });
});

