// GET /api/postcodes — List all UK postcode districts grouped by area with availability
app.get('/api/postcodes', (req, res) => {
  const districts = loadPostcodeDistricts();
  const areas = loadPostcodeAreas();
  const assignments = loadAssignments();
  const product = req.query.product || 'moving';

  // Group districts by area, return area-level overview
  const areaMap = {};
  for (const [code, info] of Object.entries(districts)) {
    const areaCode = info.area;
    if (!areaMap[areaCode]) {
      areaMap[areaCode] = {
        code: areaCode,
        name: (areas[areaCode] || {}).name || areaCode,
        region: info.region,
        district_count: 0,
        available: true,
        taken_by: null
      };
    }
    areaMap[areaCode].district_count++;
  }

  const result = Object.values(areaMap);
  const regions = [...new Set(Object.values(districts).map(d => d.region))];

  res.json({ areas: result, total_areas: result.length, regions });
});

// GET /api/postcodes/mine — Get current customer's assigned postcode areas with limits
app.get('/api/postcodes/mine', authMiddleware, (req, res) => {
  const customer = db.prepare('SELECT * FROM customers WHERE id = ?').get(req.user.id);
  if (!customer) return res.status(404).json({ error: 'User not found' });

  const areas = loadPostcodeAreas();
  const currentAreas = JSON.parse(customer.target_areas || '[]');
  const extraPostcodes = parseInt(customer.extra_postcodes) || 0;
  const maxLimit = getPostcodeLimit(customer.plan, extraPostcodes);

  const withDetails = currentAreas.map(code => {
    const upper = code.toUpperCase();
    const areaInfo = areas[upper];
    if (areaInfo) {
      return { code: upper, name: areaInfo.name, region: areaInfo.region || '' };
    }
    // City/region name (not a standard postcode area)
    return { code: upper, name: upper, region: '', isCity: true };
  });

  res.json({
    areas: withDetails,
    count: withDetails.length,
    max_limit: maxLimit,
    plan: customer.plan,
    can_add_more: withDetails.length < maxLimit,
    limit_label: maxLimit >= 999 ? 'Unlimited' : String(maxLimit),
    base_limit: getPostcodeLimit(customer.plan, 0),
    extra_postcodes: extraPostcodes,
    can_extra: customer.plan !== 'free_trial' && customer.plan !== 'cancelled'
  });
});

// GET /api/postcodes/check — Check if a postcode area is valid
app.get('/api/postcodes/check', async (req, res) => {
  try {
    var code = (req.query.code || '').toUpperCase().trim();
    if (!code) return res.json({ valid: false, error: 'No postcode provided' });
    var areas = loadPostcodeAreas();
    if (!areas[code]) return res.json({ valid: false, error: '"' + code + '" is not a valid UK postcode area (use 1 or 2-letter code like B, N, EN, SG, CM)' });
    res.json({ valid: true, area: code, name: (areas[code] || {}).name || code, region: (areas[code] || {}).region || '' });
  } catch(e) { res.json({ valid: false, error: 'Server error' }); }
});

// PUT /api/postcodes/update — Update the customer's selected postcode areas
app.put('/api/postcodes/update', authMiddleware, (req, res) => {
  const { postcodes } = req.body;
  const customer = db.prepare('SELECT * FROM customers WHERE id = ?').get(req.user.id);
  if (!customer) return res.status(404).json({ error: 'User not found' });

  const validation = validatePostcodes(postcodes, customer.plan, customer.product, req.user.id);
  if (!validation.valid) {
    return res.status(400).json({ error: validation.errors.join(' ') });
  }

  // Release old postcodes, claim new ones
  releasePostcodes(req.user.id);
  claimPostcodes(postcodes, req.user.id, customer.product);

  db.prepare('UPDATE customers SET target_areas = ? WHERE id = ?').run(JSON.stringify(postcodes), req.user.id);
  saveDb();

  res.json({ success: true, areas: postcodes, count: postcodes.length, max_limit: getPostcodeLimit(customer.plan) });
});

// PUT /api/areas/update — Update the customer's coverage areas.
// Used by tenders (and other county/region products) which select counties or
// regions rather than postcode-area codes. Stores target_areas + coverage so the
// distributor/delivery match on county/region names.
const KNOWN_COUNTIES = ['bedfordshire','berkshire','bristol','buckinghamshire','cambridgeshire','cheshire','city-of-london','cornwall','cumbria','derbyshire','devon','dorset','durham','east-sussex','essex','gloucestershire','greater-london','greater-manchester','hampshire','herefordshire','hertfordshire','isle-of-wight','kent','lancashire','leicestershire','lincolnshire','merseyside','norfolk','north-yorkshire','northamptonshire','northumberland','nottinghamshire','oxfordshire','rutland','shropshire','somerset','south-yorkshire','staffordshire','suffolk','surrey','tyne-and-wear','warwickshire','west-midlands','west-sussex','west-yorkshire','wiltshire','worcestershire','east-midlands','east-of-england','london','north-east','north-west','south-east','south-west','west-midlands-region','yorkshire','yorkshire-and-the-humber','wales','scotland','all-uk','ukwide','all uk','south-england','west-england','north-england','northern-ireland'];
// BROAD UK REGIONS -> postcode AREA codes. Lets a customer choose a whole region
// (e.g. "South England") instead of specific counties — ideal for tenders (which
// are national opportunities) and gives much better coverage than town-level
// counties. Used by area validation + delivery matching.
const REGION_TO_POSTCODE_AREAS = {
  'south-england': ['AL','BA','BH','BN','BR','BS','CB','CM','CO','CR','CT','DA','DT','E','EC','EN','EX','GL','GU','HA','HP','IG','IP','KT','LU','ME','MK','N','NE','NR','NW','OX','PE','PO','RG','RH','RM','SE','SG','SL','SM','SN','SO','SP','SS','SW','TQ','TN','TR','TW','UB','W','WC','WD'],
  'east-of-england': ['AL','CB','CM','CO','EN','HP','IG','IP','LU','MK','NR','PE','RM','SG','SS','WD'],
  'west-england': ['BA','BH','BS','DT','EX','GL','PL','SN','SP','TA','TQ','TR'],
  'north-england': ['BB','BD','BL','CH','CW','DH','DL','DN','FY','HD','HG','HU','HX','L','LA','LD','LS','M','NE','OL','PR','S','SK','SR','ST','TF','TS','WA','WF','WN','YO'],
  'scotland': ['AB','DD','DG','EH','FK','G','HS','IV','KA','KW','KY','ML','PA','PH','TD','ZE'],
  'northern-ireland': ['BT'],
  'wales': ['CF','LD','LL','NP','SA','SY']
};
app.put('/api/areas/update', authMiddleware, (req, res) => {
  try {
    var { areas, coverage } = req.body;
    if (!areas || !Array.isArray(areas)) return res.status(400).json({ error: 'Areas required' });
    var cleanAreas = areas.map(function(a) { return String(a).toLowerCase().trim().replace(/\s+/g, '-'); }).filter(Boolean);
    // Validate against known counties/regions when coverage is county/region
    if (coverage === 'county' || coverage === 'region') {
      var invalid = cleanAreas.filter(function(a) { return a === 'all-uk' ? false : KNOWN_COUNTIES.indexOf(a) === -1; });
      if (invalid.length) return res.status(400).json({ error: 'Unknown area: ' + invalid.join(', ') });
    }
    var cov = coverage || 'county';
    db.prepare('UPDATE customers SET target_areas = ?, coverage = ? WHERE id = ?').run(JSON.stringify(cleanAreas), cov, req.user.id);
    saveDb();
    res.json({ success: true, areas: cleanAreas, coverage: cov });
  } catch(e) { res.status(500).json({ error: e.message }); }
});

