// PUT /api/settings
app.put('/api/settings', authMiddleware, (req, res) => {
  const { company, name, phone, target_areas, notifications, password, moving_type } = req.body;
  const customer = db.prepare('SELECT * FROM customers WHERE id = ?').get(req.user.id);
  if (!customer) return res.status(404).json({ error: 'User not found' });

  if (company) db.prepare('UPDATE customers SET company = ? WHERE id = ?').run(company, req.user.id);
  if (name) db.prepare('UPDATE customers SET contact_name = ? WHERE id = ?').run(name, req.user.id);
  if (phone) db.prepare('UPDATE customers SET phone = ? WHERE id = ?').run(phone, req.user.id);
  if (password && password.length >= 8) { var pwHash = require('bcryptjs').hashSync(password, 10); db.prepare('UPDATE customers SET password_hash = ? WHERE id = ?').run(pwHash, req.user.id); }
  // moving_type: residential | commercial | both (moving product filter).
  // BUSINESS RULE: customers CANNOT switch to commercial/both on their own — a
  // commercial mix is only granted at signup or by us (admin). If a customer
  // sends commercial/both, force it back to residential so the choice is locked.
  if (moving_type && ['residential','commercial','both'].indexOf(moving_type) !== -1) {
    if (moving_type === 'commercial' || moving_type === 'both') {
      moving_type = 'residential';
    }
    var mtCfg = {}; try { mtCfg = JSON.parse(customer.product_config || '{}'); } catch(e) {}
    if (!mtCfg.moving) mtCfg.moving = {};
    // Commercial-only is NOT offered — every moving customer keeps a residential
    // base with commercial mixed in when available.
    mtCfg.moving.moving_type = (moving_type === 'commercial') ? 'both' : moving_type;
    db.prepare('UPDATE customers SET product_config = ? WHERE id = ?').run(JSON.stringify(mtCfg), req.user.id);
  }
  if (target_areas) {
    // "All UK" selection => ukwide coverage (no specific postcode areas needed).
    const hasAllUK = target_areas.some(function(a){ return /all[\s-]?uk/i.test(String(a)); });
    if (hasAllUK) {
      db.prepare('UPDATE customers SET coverage = ?, target_areas = ? WHERE id = ?').run('ukwide', JSON.stringify(['All UK']), req.user.id);
      res.json({ success: true });
      return;
    }
    // PROBATE USES AREAS (counties/regions), NOT postcodes — probate supply is
    // national so a county/region gives a steady daily flow, whereas a single
    // postcode area starves the customer (probate is sparse). Enforce county/region
    // selection and a minimum of 3 areas here (and on sign-up).
    if (customer.product === 'probate') {
      if (!Array.isArray(target_areas) || target_areas.length < 3) {
        return res.status(400).json({ error: 'Please choose at least 3 areas (counties or regions) — you can select as many as you like.' });
      }
      var probateRegions = ['East Midlands','East of England','London','North East','North West','South East','South West','West Midlands','Yorkshire and the Humber'];
      var badPAreas = target_areas.filter(function(a) {
        var k = String(a).toLowerCase().replace(/[\s-]+/g, '-');
        return !COUNTY_POSTCODE_MAP[k] && probateRegions.indexOf(a) === -1 && !isPostcodeAreaTarget(a);
      });
      if (badPAreas.length) {
        return res.status(400).json({ error: '"' + badPAreas.join(', ') + '" is not a valid area. For probate, choose UK counties or regions from the list.' });
      }
      releasePostcodes(req.user.id);
      db.prepare('UPDATE customers SET target_areas = ?, coverage = ? WHERE id = ?').run(JSON.stringify(target_areas), 'county', req.user.id);
      try {
        var pcSyncP = JSON.parse(customer.product_config || '{}');
        var pcProdP = customer.product;
        if (!pcSyncP[pcProdP]) pcSyncP[pcProdP] = {};
        pcSyncP[pcProdP].target_areas = JSON.stringify(target_areas);
        pcSyncP[pcProdP].coverage = 'county';
        db.prepare('UPDATE customers SET product_config = ? WHERE id = ?').run(JSON.stringify(pcSyncP), req.user.id);
      } catch(pcPErr) { console.log('[SETTINGS] probate product_config sync error:', pcPErr.message); }
      res.json({ success: true });
      return;
    }
    const validation = validatePostcodes(target_areas, customer.plan, customer.product, req.user.id);
    if (!validation.valid) {
      return res.status(400).json({ error: validation.errors.join(' ') });
    }
    releasePostcodes(req.user.id);
    claimPostcodes(target_areas, req.user.id, customer.product);
    // Reset a stale 'ukwide' coverage back to 'postcode' so a customer who
    // switches from All of UK to specific areas doesn't keep UK-wide state.
    db.prepare('UPDATE customers SET target_areas = ?, coverage = ? WHERE id = ?').run(JSON.stringify(target_areas), 'postcode', req.user.id);
    // SYNC the per-product config too — the delivery reads product_config[<product>].target_areas
    // FIRST (before the generic target_areas column), so a dashboard area change MUST update
    // it or the next 9am delivery keeps using the customer's OLD areas.
    try {
      var pcSync = JSON.parse(customer.product_config || '{}');
      var pcProd = customer.product;
      if (pcSync[pcProd]) pcSync[pcProd].target_areas = JSON.stringify(target_areas);
      else pcSync[pcProd] = Object.assign({}, pcSync[pcProd] || {}, { target_areas: JSON.stringify(target_areas), coverage: 'postcode' });
      pcSync[pcProd].coverage = 'postcode';
      db.prepare('UPDATE customers SET product_config = ? WHERE id = ?').run(JSON.stringify(pcSync), req.user.id);
    } catch(pcSyncErr) { console.log('[SETTINGS] product_config sync error:', pcSyncErr.message); }
    // Sync postcodes to scraper customer file
    try {
      var p2 = customer.product;
      var scraperFile2 = path.join(__dirname, 'data', p2 + '-leads-customers.json');
      var scrCusts2 = {};
      try { scrCusts2 = JSON.parse(fs.readFileSync(scraperFile2, 'utf-8')); } catch(e) {}
      if (scrCusts2[req.user.id]) {
        scrCusts2[req.user.id].postcodes = target_areas;
        fs.writeFileSync(scraperFile2, JSON.stringify(scrCusts2, null, 2));
        console.log('[SCRAPER] Postcodes synced for ' + req.user.id);
      }
    } catch(e) { console.log('[SCRAPER] Postcode sync error:', e.message); }
  }

  res.json({ success: true });
});

