// GET /api/admin/leads-overview — per-customer lead delivery stats (today/week/month)
// so the admin can verify each customer receives their promised lead count.
app.get('/api/admin/leads-overview', adminAuth, (req, res) => {
  try {
    var dbL = getDb();
    var now = new Date();
    var todayStr = now.toISOString().split('T')[0];
    var monthStr = todayStr.substring(0, 7);
    var weekStart = new Date(now); weekStart.setDate(weekStart.getDate() - weekStart.getDay());
    var weekStartStr = weekStart.toISOString().split('T')[0];

    var rows = (dbL.customers || []).map(function(c) {
      var custLeads = (dbL.leads || []).filter(function(l) { return l.customer_id === c.id; });
      var delivered = custLeads.filter(function(l) { return l.delivered || l.delivered_at; });
      var todayC = delivered.filter(function(l) { var d = (l.delivered_at || l.created_at || '').split('T')[0]; return d === todayStr; }).length;
      var weekC = delivered.filter(function(l) { var d = (l.delivered_at || l.created_at || '').split('T')[0]; return d >= weekStartStr; }).length;
      var monthC = delivered.filter(function(l) { var d = (l.delivered_at || l.created_at || '').split('T')[0]; return d.substring(0,7) === monthStr; }).length;
      return {
        id: c.id, email: c.email, company: c.company || c.email,
        product: c.product, plan: c.plan || 'free_trial',
        promised_per_day: (function() { try { return getPlanLimit(c.product, c.plan, c.coverage || 'postcode'); } catch(e) { return 5; } })(),
        coverage: c.coverage || 'postcode',
        leads_today: todayC,
        leads_week: weekC,
        leads_month: monthC,
        total_leads: delivered.length,
        trial_ends: c.trial_ends || '',
        created_at: c.created_at || ''
      };
    });
    res.json({ success: true, customers: rows, generated_at: now.toISOString() });
  } catch(e) { res.status(500).json({ error: e.message }); }
});

// GET /api/admin/pool-quality?product=moving — show per-area pool supply and how
// many leads actually pass the strict full-address gate (premise + full postcode),
// so we can prove the promised daily count is deliverable in every customer area.
app.get('/api/admin/pool-quality', adminAuth, (req, res) => {
  try {
    var prod = req.query.product || 'moving';
    var poolFile = path.join(DATA_DIR, PRODUCT_LEAD_FILES[prod] ? PRODUCT_LEAD_FILES[prod].file : (prod + '-leads.json'));
    var poolArr = [];
    try { var raw = JSON.parse(fs.readFileSync(poolFile, 'utf-8')); if (Array.isArray(raw)) poolArr = raw; else if (raw && typeof raw === 'object') Object.keys(raw).forEach(function(k){ if (k.indexOf('_') !== 0 && Array.isArray(raw[k])) poolArr = poolArr.concat(raw[k]); }); } catch(e2) {}
    poolArr = poolArr.filter(function(l) { return !/zoopla/i.test(String(l.source || '')); });
    var cutoff = getFreshCutoffIso();
    var per = {};
    for (var i = 0; i < poolArr.length; i++) {
      var l = poolArr[i];
      var d = pickFreshDate(l);
      if (!d || d < cutoff) continue;
      var area = extractPostcodeArea(l.postcode || l.address || l.location || l.name || '') || 'none';
      if (!per[area]) per[area] = { total: 0, has_premise: 0, full_postcode: 0, both: 0, url: 0 };
      per[area].total++;
      var addr = l.fullAddress || l.address || l.deceasedAddress || '';
      var pc = l.postcode || '';
      if (hasUsablePremiseAddress(addr, pc)) per[area].has_premise++;
      if (/^[A-Z]{1,2}[0-9][A-Z0-9]?\s?[0-9][A-Z]{2}$/i.test(String(pc || '').trim())) per[area].full_postcode++;
      if (hasUsablePremiseAddress(addr, pc) && /^[A-Z]{1,2}[0-9][A-Z0-9]?\s?[0-9][A-Z]{2}$/i.test(String(pc || '').trim())) per[area].both++;
      if (l.url) per[area].url++;
    }
    res.json({ success: true, product: prod, fresh_cutoff: cutoff, areas: per });
  } catch(e) { res.status(500).json({ error: e.message }); }
});

// GET /api/admin/delivered-leads?email=X&date=YYYY-MM-DD — list a customer's
