function adminAuth(req, res, next) {
  const auth = req.headers.authorization;
  if (!auth || auth !== 'Bearer ' + ADMIN_PASSWORD) {
    return res.status(401).json({ error: 'Unauthorized' });
  }
  next();
}

// GET /api/admin/stats — overall system stats
app.get('/api/admin/stats', adminAuth, (req, res) => {
  const totalCustomers = db.prepare('SELECT COUNT(*) as count FROM customers').get();
  const freeTrials = db.prepare('SELECT COUNT(*) as count FROM customers WHERE plan = \'free_trial\'').get();
  // A customer is "paid" if their plan is not a free trial, OR they have an active
  // Stripe subscription / non-trial selected plan (trial_ends passed and paid).
  var allCusts = getDb().customers || [];
  var paidCustomers = allCusts.filter(function(c) {
    if (c.plan && c.plan !== 'free_trial') return true;
    if (c.stripe_subscription_id || (c.selected_plan && c.selected_plan !== 'free_trial' && c.selected_plan !== 'starter')) return true;
    return false;
  }).length;
  const totalLeads = db.prepare('SELECT COUNT(*) as count FROM leads').get();
  const todayLeads = db.prepare('SELECT COUNT(*) as count FROM leads WHERE date(created_at) = date(\'now\')').get();
  // Deliveries are recorded by setting delivered=1 + delivered_at on each lead
  // (there is no populated 'deliveries' table), so count delivered leads today.
  const deliveriesToday = db.prepare('SELECT COUNT(*) as count FROM leads WHERE delivered = 1 AND date(delivered_at) = date(\'now\')').get();
  const bounced = db.prepare('SELECT COUNT(*) as count FROM customers WHERE bounced > 0').get();
  const rejectedLeads = db.prepare("SELECT COUNT(*) as count FROM leads WHERE status = 'rejected'").get();

  const byProduct = (function() {
    var counts = {};
    (getDb().customers || []).forEach(function(c) { var p = c.product || 'unknown'; counts[p] = (counts[p] || 0) + 1; });
    return Object.keys(counts).map(function(p) { return { product: p, count: counts[p] }; });
  })();
  const bySource = (function() {
    var counts = {};
    (getDb().customers || []).forEach(function(c) { var s = c.source || 'unknown'; counts[s] = (counts[s] || 0) + 1; });
    return Object.keys(counts).map(function(s) { return { source: s, count: counts[s] }; });
  })();
  const recentSignups = (function() {
    var counts = {};
    (getDb().customers || []).forEach(function(c) { var d = String(c.created_at || '').split('T')[0]; if (d) counts[d] = (counts[d] || 0) + 1; });
    return Object.keys(counts).sort().reverse().slice(0, 7).map(function(d) { return { day: d, count: counts[d] }; });
  })();

  // JSON-level stats (expired trials, weekly signups, CRM connected)
  var dbS = getDb();
  var now = new Date().toISOString();
  var weekAgo = new Date(Date.now() - 7 * 86400000).toISOString();
  var expiredTrials = (dbS.customers || []).filter(function(c) { return c.plan === 'free_trial' && c.trial_ends && new Date(c.trial_ends) < now; }).length;
  var weekSignups = (dbS.customers || []).filter(function(c) { return c.created_at && c.created_at >= weekAgo; }).length;
  var crmConnected = (dbS.customers || []).filter(function(c) { return c.crm_webhook_url; }).length;

  res.json({
    total_customers: totalCustomers.count,
    free_trials: freeTrials.count,
    paid_customers: paidCustomers,
    expired_trials: expiredTrials,
    this_week_signups: weekSignups,
    crm_connected: crmConnected,
    total_leads: totalLeads.count,
    today_leads: todayLeads.count,
    deliveries_today: deliveriesToday.count,
    bounced_emails: bounced.count,
    rejected_leads: rejectedLeads.count,
    by_product: byProduct,
    by_source: bySource,
    recent_signups: recentSignups
  });
});

// GET /api/admin/customers — list all customers (paginated)
app.get('/api/admin/customers', adminAuth, (req, res) => {
  const page = parseInt(req.query.page) || 1;
  const limit = parseInt(req.query.limit) || 50;

  const allCustomers = db.prepare('SELECT * FROM customers ORDER BY created_at DESC').all();
  const total = db.prepare('SELECT COUNT(*) as count FROM customers').get();
  const customers = allCustomers.slice((page - 1) * limit, page * limit);

  // Get lead counts for each customer
  const result = customers.map(c => {
    const leadCount = db.prepare('SELECT COUNT(*) as count FROM leads WHERE customer_id = ?').get(c.id);
    return { ...c, lead_count: leadCount.count };
  });

  res.json({
    customers: result,
    total: total.count,
    page,
    total_pages: Math.ceil(total.count / limit)
  });
});

// POST /api/admin/bulk-create-customers — create test customers directly in DB// (bypasses the signup rate limit for bulk testing). Admin auth only.
app.post('/api/admin/bulk-create-customers', adminAuth, (req, res) => {
  try {
    const list = Array.isArray(req.body) ? req.body : (req.body && req.body.customers);
    if (!Array.isArray(list) || list.length === 0) return res.status(400).json({ error: 'customers array required' });
    var db = getDb();
    if (!db.customers) db.customers = [];
    var bcrypt = require('bcryptjs');
    var created = 0, errors = [];
    for (var i = 0; i < list.length; i++) {
      var a = list[i];
      if (!a.email || !a.product) { errors.push((a.email || '?') + ': missing email/product'); continue; }
      if (db.customers.some(function(c) { return c.email === a.email.toLowerCase(); })) { errors.push(a.email + ': already exists'); continue; }
      var id = (require('uuid').v4)();
      var pwHash = bcrypt.hashSync(a.password || 'Wemovehomes321', 10);
      var coverage = a.coverage || (a.product === 'moving' || a.product === 'newbusiness' ? 'postcode' : 'county');
      var areas = a.areas || [];
      var plan = a.plan || 'free_trial';
      var isAllUK = areas.some(function(x) { return /all[\s-]?uk/i.test(String(x)); });
      if (isAllUK) coverage = 'ukwide';
      var trialEnds = plan === 'free_trial' ? new Date(Date.now() + 7 * 86400000).toISOString() : null;
      var dailyLimit = getPlanLimit(a.product, plan, coverage) || 5;
      var cust = {
        id: id,
        email: a.email.toLowerCase(),
        company: a.company || a.email,
        contact_name: a.name || a.company || '',
        phone: a.phone || '',
        password_hash: pwHash,
        product: a.product,
        lead_type: a.product,
        business_type: a.product,
        target_areas: JSON.stringify(isAllUK ? ['All UK'] : areas),
        coverage: coverage,
        biz_field2: a.bizField2 || '',
        biz_field3: JSON.stringify([a.product]),
        source: a.source || 'test',
        plan: plan,
        trial_ends: trialEnds,
        marketing_consent: a.marketingConsent ? 1 : 0,
        created_at: new Date().toISOString(),
        extra_postcodes: '0',
        crm_webhook_url: a.crmWebhookUrl || '',
        campaign_sent: '[]',
        signup_ip: 'bulk-test',
        leads_per_day: dailyLimit,
        email_verified: 1,
        verification_token: ''
      };
      db.customers.push(cust);
      created++;
    }
    saveDb();
    res.json({ success: true, created: created, errors: errors });
  } catch(e) { res.status(500).json({ error: e.message }); }
});

// ===== BREVO EMAIL INTEGRATION =====
const BREVO_API_KEY = process.env.BREVO_API_KEY || ''; // Set via Render env var - do not hardcode

async function addBrevoContact(customer) {
  if (!BREVO_API_KEY) return;
  const https = require('https');
  
  // Map product to the correct Brevo list
  const LIST_IDS = {
    'moving': 44,
    'probate': 45,
    'newbusiness': 46,
    'planning': 47,
    'tenders': 48
  };
  const product = customer.product || customer.lead_type || 'moving';
  const listId = LIST_IDS[product] || 44;
  
  const data = JSON.stringify({
    email: customer.email,
    attributes: {
      COMPANY: customer.company || customer.business_name || '',
      FIRSTNAME: customer.contact_name || customer.name || '',
      PHONE: customer.phone || '',
      PRODUCT: product,
      LEAD_TYPE: customer.lead_type || product,
      PLAN: customer.plan || 'free_trial',
      SOURCE: customer.source || 'direct',
      SIGNUP_DATE: customer.created_at || new Date().toISOString()
    },
    listIds: [listId],
    updateEnabled: true
  });

  return new Promise((resolve, reject) => {
    const req = https.request({
      hostname: 'api.brevo.com',
      path: '/v3/contacts',
      method: 'POST',
      headers: {
        'Content-Type': 'application/json',
        'api-key': BREVO_API_KEY,
        'Content-Length': Buffer.byteLength(data)
      }
    }, (res) => {
      let body = '';
      res.on('data', c => body += c);
      res.on('end', () => {
        if (res.statusCode < 300) try { resolve(JSON.parse(body)); } catch(e) { resolve({ id: 'ok' }); }
        else reject(new Error(body));
      });
    });
    req.on('error', reject);
    req.write(data);
    req.end();
  });
}

async function stripHtmlToText(html) {
  return String(html || '')
    .replace(/<style[\s\S]*?<\/style>/gi, ' ')
    .replace(/<br\s*\/?>/gi, '\n')
    .replace(/<\/(p|div|tr|h1|h2|h3|li|table)>/gi, '\n')
    .replace(/<[^>]+>/g, ' ')
    .replace(/&nbsp;/g, ' ')
    .replace(/&amp;/g, '&')
    .replace(/&lt;/g, '<')
    .replace(/&gt;/g, '>')
    .replace(/&#39;/g, "'")
    .replace(/&quot;/g, '"')
    .replace(/[ \t]+/g, ' ')
    .replace(/\n\s*\n+/g, '\n\n')
    .trim();
}

function sendBrevoEmail(to, subject, htmlContent) {
  if (!BREVO_API_KEY) return;
  const https = require('https');
  // Sender: hello@9amleads.com is the registered Brevo sender with SPF/DKIM/DMARC
  // published (9amleads.com). A plain-text version + reply-to improve deliverability
  // (spam filters reward text alternatives; a reply address builds sender trust).
  var senderFrom = 'hello@9amleads.com';
  var senderName = '9amLeads';
  const data = JSON.stringify({
    sender: { name: senderName, email: senderFrom },
    replyTo: { email: 'hello@9amleads.com', name: '9amLeads Support' },
    to: [{ email: to.email, name: to.name }],
    subject,
    htmlContent,
    headers: {
      'X-Brevo-Tag': '9amleads',
      'X-Mailgun-Tag': '9amleads',
      'List-Unsubscribe': '<mailto:hello@9amleads.com?subject=unsubscribe>'
    }
  });

  return new Promise((resolve, reject) => {
    // RETRY WITH BACKOFF: Brevo rate-limits (429) are common during the 9am batch
    // (many customers emailed at once). Retry up to 4 times with 1s/2s/4s/8s waits
    // so a temporary 429 never silently drops a customer's daily email. This is
    // critical for the "every customer gets exactly what they pay for" guarantee.
    function attempt(attemptNum) {
      const req = https.request({
        hostname: 'api.brevo.com',
        path: '/v3/smtp/email',
        method: 'POST',
        headers: {
          'Content-Type': 'application/json',
          'api-key': BREVO_API_KEY,
          'Content-Length': Buffer.byteLength(data)
        }
      }, (res) => {
        let body = '';
        res.on('data', c => body += c);
        res.on('end', () => {
          if (res.statusCode < 300) {
            bumpBrevoSentToday();
            try { resolve(JSON.parse(body)); } catch(e) { resolve({}); }
          } else if ((res.statusCode === 429 || res.statusCode >= 500) && attemptNum < 4) {
            var delay = 1000 * Math.pow(2, attemptNum - 1);
            console.log('[BREVO] Rate-limited (HTTP ' + res.statusCode + '), retrying in ' + delay + 'ms (' + to.email + ')');
            setTimeout(function() { attempt(attemptNum + 1); }, delay);
          } else {
            reject(new Error(body.substring(0, 200)));
          }
        });
      });
      req.on('error', function(err) {
        if (attemptNum < 4) { var d2 = 1000 * Math.pow(2, attemptNum - 1); setTimeout(function() { attempt(attemptNum + 1); }, d2); }
        else reject(err);
      });
      req.write(data);
      req.end();
    }
    attempt(1);
  });
}

