// Build the broadened area set for a customer: chosen areas + nearest neighbours.
function broadenAreas(areas) {
  var out = [];
  (areas || []).forEach(function(a) {
    if (out.indexOf(a) === -1) out.push(a);
    var k = String(a).toLowerCase().replace(/[\s-]+/g, '-');
    var nbr = /^[A-Z]{1,3}$/i.test(String(a)) ? POSTCODE_AREA_NEIGHBORS[String(a).toUpperCase()] : COUNTY_NEIGHBORS[k];
    (nbr || []).forEach(function(n) { if (out.indexOf(n) === -1) out.push(n); });
  });
  return out;
}

// ===== 9AM DAILY DELIVERY SCHEDULER =====
// Runs at 9:00 AM every day to prepare and send lead sheets
// ===== LEAD LIMITS PER PLAN PER PRODUCT =====
// Realistic daily lead volumes based on available UK data supply
const PRODUCT_LEAD_FILES = {
  moving: { file: 'moving-leads.json', key: 'customerId' },
  probate: { file: 'probate-leads.json', key: 'customerId' },
  newbusiness: { file: 'newbusiness-leads.json', key: 'customerId' },
  planning: { file: 'planning-leads.json', key: 'customerId' },
  tenders: { file: 'tenders-leads.json', key: 'customerId' },
};

// Lead type rules: per-product, per-plan, per-coverage-area daily limits
// Coverage types: 'postcode', 'county', 'region', 'ukwide'
// POST /api/check-availability — check if a lead type/package can be fulfilled
app.post('/api/check-availability', async (req, res) => {
  try {
    const { product, plan, coverage, postcodes } = req.body;
    const rule = getLeadTypeRule(product);
    const dailyLimit = getPlanLimit(product, plan || 'starter', coverage || 'region');

    // Check coverage validity for this lead type
    if (rule.coverage.indexOf(coverage) === -1) {
      return res.json({ available: false, message: coverage + ' coverage is not available for ' + rule.name + '.', recommendation: 'Choose ' + rule.coverage.join(', ') + ' instead.', limited: true, recommended_coverage: rule.min_area });
    }

    // Check minimum area requirement
    const areaOrder = { postcode: 1, county: 2, region: 3, ukwide: 4 };
    if (areaOrder[coverage] < areaOrder[rule.min_area]) {
      return res.json({ available: false, message: rule.name + ' in ' + coverage + ' areas are limited. To receive more daily opportunities, please choose ' + rule.min_area + ', ' + (rule.coverage.filter(c => c !== coverage).join(' or ')) + ' coverage.', recommendation: 'Recommended coverage: ' + rule.min_area + ' or wider.', limited: true, recommended_coverage: rule.min_area });
    }

    // Check if product is enabled
    if (!rule.enabled) {
      return res.json({ available: false, message: rule.name + ' are coming soon. Join the waiting list to be notified.', limited: true, waiting_list: true });
    }

    // Basic availability heuristic
    const db = getDb();
    const existingCustomers = (db.customers || []).filter(c => c.product === product && c.plan !== 'cancelled' && (!c.trial_ends || new Date(c.trial_ends) > new Date()));
    // Committed daily demand = sum of each customer's ACTUAL plan daily limit (from
    // LEAD_TYPE_RULES), not the raw leads_per_day field (which defaults to 5 and
    // over-counts demand — e.g. probate is now 1/day but would count as 5, making
    // the hard cap 5x more restrictive than it should be).
    const totalCommitted = existingCustomers.reduce((sum, c) => sum + getPlanLimit(product, c.plan || 'starter', c.coverage || 'default'), 0);
    var leadsToday = (db.leads || []).filter(function(l) { return l.product === product && l.delivered === 0; }).length;

    // HARD SALES CAP based on the PHYSICAL supply ceiling of each data source.
    // The market only produces a fixed number of fresh leads per day:
    //   moving ~3,000, newbusiness ~1,500 (Companies House), probate ~27 (UK
    //   Gazette deceased-estates notices), planning ~2,000 (Plota), tenders ~300.
    // To honour the "exactly what's promised" guarantee we must NEVER sell more
    // daily-lead capacity than the source can physically produce. The cap keeps
    // a safety margin so every customer's full promise is always deliverable.
    var supplyCeiling = {
      moving: 300, newbusiness: 1500, probate: 300, planning: 400, tenders: 100
    };
    var ceiling = supplyCeiling[product] || 100;
    // After this signup, committed demand would be totalCommitted + dailyLimit.
    var projectedCommitted = totalCommitted + dailyLimit;
    if (projectedCommitted > Math.floor(ceiling * 0.7)) {
      return res.json({
        available: false, limited: true, hard_cap: true,
        message: rule.name + ' are currently at capacity in the UK. We only sell what we can reliably deliver every day, so this package is not available right now.',
        recommendation: 'Join the waiting list and we\'ll contact you the moment we can guarantee your daily lead promise.',
        daily_limit: dailyLimit, committed_demand: totalCommitted, supply_ceiling: ceiling, projected_demand: projectedCommitted,
        max_accounts_at_this_plan: Math.floor((ceiling * 0.7) / dailyLimit)
      });
    }

    // Estimate available supply
    var weeklyAvg = leadsToday; // Simplified: use today's available leads
    var supplyRatio = dailyLimit > 0 ? (weeklyAvg / (totalCommitted + dailyLimit)) : 0;

    if (supplyRatio < 0.3 && totalCommitted > 0) {
      return res.json({ available: true, limited: true, message: rule.name + ' in this area have limited availability.', recommendation: 'Consider wider coverage or a starter package to begin with.', supply_ratio: supplyRatio });
    }

    res.json({ available: true, limited: supplyRatio < 0.8, daily_limit: dailyLimit, supply_ratio: supplyRatio, coverage: coverage });
  } catch (e) {
    res.status(500).json({ error: e.message });
  }
});

// GET /api/signup/competition-areas — per-area competition counts for the signup
// picker. For tenders (and county products) it returns, for EVERY county, how many
// active businesses are already signed up there, so the picker can label each area
// as "shared with N" and the customer agrees before committing.
app.get('/api/signup/competition-areas', (req, res) => {
  try {
    var product = String((req.query && req.query.product) || '').toLowerCase().trim();
    if (!product || !['moving','probate','planning','newbusiness','tenders'].includes(product)) return res.status(400).json({ error: 'Valid product required' });
    var dbA = getDb();
    var now = new Date();
    var custs = (dbA.customers || []).filter(function(c) {
      if (String(c.product || '').toLowerCase() !== product) return false;
      if (c.plan === 'cancelled') return false;
      if (isLeadsPaused(c)) return false;
      var te = c.trial_ends ? new Date(c.trial_ends) : null;
      if (c.plan === 'free_trial' && te && now > te) return false;
      return true;
    });
    var totalActive = custs.length;
    var areasFor = function(c) {
      var a = [];
      try { a = JSON.parse(c.target_areas || '[]'); } catch(e) { a = []; }
      if (!a.length) { try { var cfg = JSON.parse(c.product_config || '{}'); a = (cfg[product] && cfg[product].target_areas) ? JSON.parse(cfg[product].target_areas) : []; } catch(e2) {} }
      return a;
    };
    var perArea = {};
    var allUkCount = 0;
    custs.forEach(function(c) {
      var ca = areasFor(c);
      var isAllUk = ca.some(function(x){ return /all.?uk|uk.?wide|nationwide|whole.?uk/i.test(String(x)); });
      if (isAllUk) { allUkCount++; return; }
      ca.forEach(function(x) { var k = String(x).toLowerCase().replace(/[\s-]+/g,'-'); perArea[k] = (perArea[k]||0)+1; });
    });
    // For tenders, all-uk customers compete in EVERY area, so add them to each.
    var list = [];
    var allCounties = KNOWN_COUNTIES || [];
    allCounties.forEach(function(cnty) {
      var name = cnty.replace(/-/g, ' ').replace(/\b\w/g, function(m){ return m.toUpperCase(); });
      var k = String(cnty).toLowerCase().replace(/[\s-]+/g,'-');
      var count = (perArea[k] || 0) + (product === 'tenders' ? allUkCount : 0);
      if (count > 0) list.push({ name: name, count: count });
    });
    list.sort(function(a,b){ return b.count - a.count; });
    // Area-specific overlap: how many OTHER active businesses compete in the
    // CUSTOMER'S chosen areas (union of any selected area). Tenders are public,
    // so a business competes in every area it covers (or all-uk = everywhere).
    var reqAreas = String(req.query.areas || '').split(',').map(function(x){ return String(x).trim().toLowerCase().replace(/[\s-]+/g,'-'); }).filter(Boolean);
    var overlapCount = 0;
    if (reqAreas.length) {
      custs.forEach(function(c) {
        var ca = areasFor(c);
        var isAllUk = ca.some(function(x){ return /all.?uk|uk.?wide|nationwide|whole.?uk/i.test(String(x)); });
        if (isAllUk) { overlapCount++; return; }
        var norm = ca.map(function(x){ return String(x).toLowerCase().replace(/[\s-]+/g,'-'); });
        var hits = reqAreas.filter(function(r){ return norm.indexOf(r) !== -1; });
        if (hits.length) overlapCount++;
      });
    }
    res.json({ success: true, product: product, total_active: totalActive, all_uk_customers: allUkCount, areas: list, overlap_count: overlapCount });
  } catch (e) {
    res.status(500).json({ error: e.message });
  }
});

// GET /api/signup/competition — honest lead-sharing disclosure for the signup form.
// Counts how many OTHER active businesses currently receive the same leads for the
// chosen product + areas, so a customer knows up-front how much competition they
// have. Tenders are shared UK-wide (every supplier sees the same notices); area
// products are shared within overlapping areas.
app.get('/api/signup/competition', (req, res) => {
  try {
    var product = String((req.query && req.query.product) || '').toLowerCase().trim();
    var rawAreas = (req.query && req.query.areas) || '';
    var areas = String(rawAreas).split(',').map(function(a){ return a.trim().toLowerCase().replace(/[\s-]+/g,'-'); }).filter(Boolean);
    if (!product || !['moving','probate','planning','newbusiness','tenders'].includes(product)) return res.status(400).json({ error: 'Valid product required' });
    var dbC = getDb();
    var now = new Date();
    var custs = (dbC.customers || []).filter(function(c) {
      if (String(c.product || '').toLowerCase() !== product) return false;
      if (c.plan === 'cancelled') return false;
      if (isLeadsPaused(c)) return false;
      var te = c.trial_ends ? new Date(c.trial_ends) : null;
      if (c.plan === 'free_trial' && te && now > te) return false;
      return true;
    });
    var totalActive = custs.length;
    var inArea = totalActive;
    if (product !== 'tenders' && areas.length) {
      // Count customers whose target areas overlap the chosen areas.
      var mapFor = function(c) {
        var a = [];
        try { a = JSON.parse(c.target_areas || '[]'); } catch(e) { a = []; }
        if (!a.length) { try { var cfg = JSON.parse(c.product_config || '{}'); a = (cfg[product] && cfg[product].target_areas) ? JSON.parse(cfg[product].target_areas) : []; } catch(e2) {} }
        return a.map(function(x){ return String(x).toLowerCase().replace(/[\s-]+/g,'-'); });
      };
      inArea = custs.filter(function(c) {
        var ca = mapFor(c);
        if (!ca.length) return false;
        return ca.some(function(x) { return areas.indexOf(x) !== -1; });
      }).length;
    }
    var shared = product === 'tenders';
    var message;
    if (product === 'tenders') {
      message = totalActive === 0
        ? 'Your tender leads are not re-sold or shared. Tenders are public opportunities by nature — every supplier can see them on the official portals. What we give you is a curated feed of the ones relevant to your business, delivered early so you can respond first. Note: some areas and sectors have fewer tenders than others.'
        : 'Your tender leads are not re-sold or shared with you. Tenders are public opportunities by nature — ' + totalActive + ' other business' + (totalActive === 1 ? '' : 'es') + ' can also see them on the official portals. What we give you is a curated feed of the ones relevant to your business, delivered early so you can respond first. Note: some areas and sectors have fewer tenders than others.';
    } else if (inArea === 0) {
      message = 'No other businesses currently receive these leads in your chosen areas — you have the first pick.';
    } else {
      message = inArea + ' other business' + (inArea === 1 ? '' : 'es') + ' currently receive' + (inArea === 1 ? 's' : '') + ' these leads in your chosen areas. We deliver fresh leads daily, and whoever contacts them first typically wins the work.';
    }
    res.json({ success: true, product: product, shared: shared, total_active: totalActive, in_area: inArea, message: message });
  } catch (e) {
    res.status(500).json({ error: e.message });
  }
});

// POST /api/waiting-list — join waiting list for unavailable packages
app.post('/api/waiting-list', async (req, res) => {
  try {
    const { name, email, phone, business_type, lead_type, area, package: pkg } = req.body;
    if (!email || !lead_type) return res.status(400).json({ error: 'Email and lead type required' });
    const db = getDb();
    if (!db.waiting_list) db.waiting_list = [];
    db.waiting_list.push({ id: uuidv4(), name: name || '', email, phone: phone || '', business_type: business_type || '', lead_type, area: area || '', package: pkg || '', date_joined: new Date().toISOString(), notified: false, notes: '' });
    saveDb();
    res.json({ success: true, message: 'You\'ve been added to the waiting list. We\'ll contact you when supply becomes available.' });
  } catch(e) { res.status(500).json({ error: e.message }); }
});

// GET /api/admin/availability — admin overview of supply vs demand
app.get('/api/admin/availability', adminAuth, (req, res) => {
  try {
    const db = getDb();
    const customers = db.customers || [];
    const leads = db.leads || [];
    const result = {};
    for (const [key, rule] of Object.entries(LEAD_TYPE_RULES)) {
      const activeCustomers = customers.filter(c => c.product === key && c.plan !== 'cancelled');
      const totalCommitted = activeCustomers.reduce((sum, c) => sum + (parseInt(c.leads_per_day) || 5), 0);
      const availableLeads = leads.filter(l => l.product === key && l.delivered === 0).length;
      const leadsToday = leads.filter(l => l.product === key && l.delivered === 0 && l.created_at && l.created_at.startsWith(new Date().toISOString().split('T')[0])).length;
      result[key] = {
        name: rule.name,
        enabled: rule.enabled,
        active_customers: activeCustomers.length,
        total_committed_daily: totalCommitted,
        available_inventory: availableLeads,
        leads_today: leadsToday,
        supply_ratio: totalCommitted > 0 ? Math.min(1, availableLeads / totalCommitted) : 1,
        oversold: totalCommitted > 0 && availableLeads < totalCommitted * 0.3,
        coverage: rule.coverage
      };
    }
    res.json({ lead_types: result, warnings: Object.values(result).filter(r => r.oversold).map(r => r.name + ' oversold') });
  } catch(e) { res.status(500).json({ error: e.message }); }
});

// GET /api/lead-types — return lead type rules for frontend
app.get('/api/lead-types', (req, res) => {
  const summary = {};
  for (const [key, rule] of Object.entries(LEAD_TYPE_RULES)) {
    summary[key] = {
      name: rule.name,
      local: rule.local,
      model: rule.model || 'daily',
      coverage: rule.coverage,
      min_area: rule.min_area,
      up_to: rule.up_to,
      enabled: rule.enabled,
      plans: Object.keys(rule.plans).filter(p => p !== 'free_trial'),
      plan_details: rule.plans,
      weekly_est: rule.weekly_est,
      monthly_est: rule.monthly_est
    };
  }
  res.json({ lead_types: summary });
});

