app.get('/api/campaigns/:product', (req, res) => {
  var kit = CAMPAIGN_KITS[req.params.product];
  if (!kit) return res.status(404).json({ error: 'Campaign not found for this lead type' });
  res.json({ success: true, kit: kit });
});

app.get('/api/campaigns', authMiddleware, (req, res) => {
  var summaries = {};
  var cust = db.prepare('SELECT plan FROM customers WHERE id = ?').get(req.user.id);
  if (cust && cust.plan === 'free_trial') {
    return res.json({ success: true, locked: true, campaigns: {} });
  }
  for (var p in CAMPAIGN_KITS) {
    summaries[p] = { name: CAMPAIGN_KITS[p].name, icon: CAMPAIGN_KITS[p].icon, color: CAMPAIGN_KITS[p].color, summary: CAMPAIGN_KITS[p].summary, header: CAMPAIGN_KITS[p].header };
  }
  res.json({ success: true, campaigns: summaries });
});



// ===== PRINT & POST PRICING =====
// Your markup is added on top of Stannp's print+post costs
var PRINT_POST_PRICES = {
  // Per-item prices charged to customer (GBP), priced against Stannp's actual
  // Royal Mail Standard rates so we stay profitable. A letter is cheaper than a
  // leaflet — Stannp's own rates reflect this (A4 letter £1.02, A5 postcard £1.18).
  // Margins: letter £0.47, leaflet £0.81, pack £0.79 per item.
  flyer_a5: { label: 'A5 Leaflet', customer: 1.99, stannp: 1.18 },
  letter_a4: { label: 'A4 Letter', customer: 1.49, stannp: 1.02 },
  flyer_plus_letter: { label: 'A5 Leaflet + A4 Letter', customer: 2.99, stannp: 2.20 },
  // Postage included in above prices (Royal Mail Standard)
  markup_percent: function(item) { return Math.round((this[item].customer - this[item].stannp) / this[item].stannp * 100); }
};

// Clean markdown / paste artifacts out of cover-letter text so the printed or
// downloaded letter matches exactly what the customer wrote. AI copywriters
// often return markdown (**bold**, * bullets) that should NOT appear in a letter.
// STRIP stray ADDRESS BLOCKS + the marketing PREAMBLE from a printed letter so the
// letter starts at the real content. Stannp prints the RECIPIENT address itself in
// the envelope window, so the letter must NOT repeat the name/address block (which
// was showing duplicated + missing the door number). It also drops unmerged
// placeholder tokens ("00000 / 0000"). It is DEFENSIVE: if the letter body has a
// product/services list heading (PLANNING & CONSTRUCTION etc.), it trims everything
// above it; if it's a normal business letter with no such heading, it keeps the
// whole body intact (never empties the letter).
function cleanLetterBodyForPrint(text) {
  var s = String(text || '');
  if (!s) return '';
  var lines = s.split('\n').map(function(l){ return l.trim(); });
  // Is this a "5 types / product list" style letter? Look for the section headings.
  var productHeadingRe = /^(PLANNING & CONSTRUCTION|MOVING & PROPERTY|PROBATE & LEGAL|NEW BUSINESS & B2B|PUBLIC SECTOR & GOVERNMENT TENDERS|PLANNING|MOVING|PROBATE|NEW BUSINESS|PUBLIC SECTOR|OUR SERVICES|WHAT WE|HOW WE|WHY CHOOSE|ABOUT US|OUR PRODUCTS)/i;
  var startIdx = -1;
  for (var i = 0; i < lines.length; i++) {
    if (productHeadingRe.test(lines[i])) { startIdx = i; break; }
  }
  // Address-block line detector: name / street / town / postcode / digits-only lines
  // that appear as a standalone block (not part of a real sentence).
  var addrLineRe = /^[A-Z]{1,2}[0-9][A-Z0-9]?\s?[0-9][A-Z]{2}$/i; // full postcode
  var nameLineRe = /^[A-Z][a-z]+(?:\s[A-Z][a-z]+){0,2}$/;          // "Ket Mandalia"
  var townLineRe = /^[A-Z]{2,}(?:\s[A-Z]{2,})*$/;                  // "HARROW"
  var out = [];
  for (var j = 0; j < lines.length; j++) {
    var line = lines[j];
    if (!line) { if (out.length) out.push(''); continue; }
    // Drop the marketing preamble ABOVE the product list (only when a product
    // heading exists — a normal business letter is kept whole).
    if (startIdx >= 0 && j < startIdx) continue;
    // STOP at the 9amLeads marketing FOOTER ("MORE THAN JUST LEADS ... START YOUR
    // 1-WEEK FREE TRIAL ... www.9amleads.com ... The 9amLeads Team"). The letter
    // should end after the last product section (PUBLIC SECTOR & GOVERNMENT
    // TENDERS), not carry 9amLeads self-promotion.
    if (/^(MORE THAN JUST LEADS|START YOUR|BE FIRST|See how 9amLeads|The principle is|Rather than waiting|9amLeads gives you|www\.9amleads|Kind regards,|The 9amLeads Team|Fresh opportunities delivered|Hyper-local postcode|Real & verified|No competition leads|Track contacts|Professional marketing|Flyers & letters printed|Proof of posting)/i.test(line)) break;
    // Drop unmerged placeholder tokens like "00000  /  0000" and "[name]" etc.
    if (/^\s*\d{3,}\s*\/\s*\d{3,}\s*$/.test(line)) continue;
    if (/^\[[a-z_]+\]$/i.test(line)) continue;
    // Drop full-postcode-only lines (Stannp adds the recipient address itself).
    if (addrLineRe.test(line)) continue;
    // Drop a duplicated/standalone name line when it is followed by another name
    // line or a street-looking line (the address block). Keep it if it is a normal
    // greeting/sign-off word like "Regards" or the sender's signature.
    if (nameLineRe.test(line) && j + 1 < lines.length && lines[j+1]) {
      var nxt = lines[j+1];
      if ((nameLineRe.test(nxt) || /^[0-9][A-Za-z0-9'.,\/\- ]{2,60}$/.test(nxt) || addrLineRe.test(nxt))) continue;
    }
    // Drop an ALL-CAPS town line that follows a street-looking line (address block).
    if (townLineRe.test(line) && j > 0 && /^[0-9][A-Za-z0-9'.,\/\- ]{2,60}$/.test(lines[j-1])) continue;
    // Drop a standalone numbered-street line (e.g. "4 Farmborough Close") that is
    // clearly an address remnant, when it is NOT a real body sentence. Addresses
    // start with a number + short street words and usually contain no verb.
    if (/^[0-9][A-Za-z0-9'.,\/\- ]{2,60}$/.test(line) && /^(the|a|an|we|i|you|please|call|visit|our|your|get|don't|do\s|is|are|this|that|it|if|when|for|with|to|on|at|by|as|in|of)\b/i.test(line) === false && !/[.;!?]$/.test(line)) continue;
    out.push(line);
  }
  var joined = out.join('\n').replace(/\n{3,}/g, '\n\n').trim();
  // Final multi-line address-block strip: a 3-5 line block ending in a postcode or
  // all-caps town (e.g. "Ket Mandalia\nKet Mandalia\n4 Farmborough Close\nHARROW\nHA1 3YG").
  joined = joined.replace(/(?:^|\n)(?:[A-Z][a-zA-Z'.\- ]{1,40}\n){1,2}(?:[A-Za-z0-9'.,\/\- ]{2,60}\n){1,3}(?:[A-Z]{1,2}[0-9][A-Z0-9]?\s?[0-9][A-Z]{2}|[A-Z]{2,}(?:\s[A-Z]{2,})*)\s*(?=\n|$)/gm, '\n').replace(/\n{3,}/g, '\n\n').trim();
  return joined;
}

// Build the CLEAN A4 letter HTML: sender return address top-right, date, divider,
// then the cleaned letter body (no recipient address — Stannp prints that in its
// own envelope window). Used by both the live Stannp send path and the free admin
// preview endpoint so they always match.
function buildCleanLetterHtml(templateBody, senderName, senderAddr) {
  var printBody = cleanLetterBodyForPrint(templateBody || '')
    .replace(/\b0{4,}\s*\/\s*0{3,}\b/g, '') // "00000 / 0000" token residue
    .replace(/\[?[a-zA-Z_]+(?:_[a-zA-Z_]+)*\]?/g, function(tok) { return /^\[[a-z_]+\]$/.test(tok) ? '' : tok; });
  // NO sender name/address/date header: Stannp prints the RECIPIENT address in its
  // envelope window itself, so the letter is just the clean body content. Keeping
  // a header here duplicated the name/address on the printed letter.
  var letterHtml =
    '<html><body style="margin:0;padding:0;font-family:Arial,Helvetica,sans-serif;color:#1e293b">' +
    '<div style="font-size:11px;line-height:1.7;white-space:pre-wrap;padding-top:130px">' + (printBody || '').split('\n').join('<br>') + '</div>' +
    '</body></html>';
  return { html: letterHtml, body: printBody };
}

function cleanMailText(text) {
  if (!text) return '';
  var s = String(text);
  // 1. Normalise Windows/HTML line endings
  s = s.replace(/\r\n?/g, '\n');
  // 2. Convert markdown bullets FIRST (line-anchored: * item / - item / + item)
  //    so a lone line-start * is treated as a bullet, never an emphasis marker.
  s = s.replace(/^\s*\*+\s+/gm, '• ');
  s = s.replace(/^\s*(-\s+|\+\s+)/gm, '• ');
  // 3. Strip markdown bold (**bold**) — remove only the asterisk pairs
  s = s.replace(/\*\*/g, '');
  // 4. Strip markdown headings (#) and horizontal rules
  s = s.replace(/^\s*#{1,6}\s*/gm, '');
  s = s.replace(/^\s*(---+|\*\*\*+|___+)\s*$/gm, '');
  // 5. Non-greedy italic *text* (single line) — keep the words
  s = s.replace(/\*([^*\n]+)\*/g, '$1');
  // 6. Strip inline backticks and links (but keep the link text)
  s = s.replace(/`/g, '');
  s = s.replace(/\[([^\]]+)\]\([^)]+\)/g, '$1');
  // 7. Remove any remaining stray asterisks (defensive)
  s = s.replace(/\*+/g, '');
  // 8. Collapse 3+ blank lines to one
  s = s.replace(/\n{3,}/g, '\n\n');
  return s.trim();
}

