// FULL send-to-provider flow: create campaign + upload artwork + add recipients + send.
// Used by both manual send and the Stripe webhook (one-click print & post).
async function sendDmCampaign(campaignId, customerId) {
  // Concurrency guard: if this campaign is already mid-send (e.g. the Stripe
  // webhook and the dashboard verify-payment both fire), do NOT send it a second
  // time — that would create duplicate paid orders at our print partner.
  var _dmSendLock = global.__dmSendLock || (global.__dmSendLock = {});
  if (_dmSendLock[campaignId]) {
    console.log('[DM-SEND] Campaign already in-flight, skipping duplicate send: ' + campaignId);
    return { success: false, error: 'Send already in progress for this campaign', duplicate: true };
  }
  _dmSendLock[campaignId] = true;
  try {
    return await sendDmCampaignInner(campaignId, customerId);
  } finally {
    delete _dmSendLock[campaignId];
  }
}

async function sendDmCampaignInner(campaignId, customerId) {
  var campaign = db.prepare('SELECT * FROM direct_mail_campaigns WHERE id = ? AND customer_id = ?').get(campaignId, customerId);
  if (!campaign) return { success: false, error: 'Campaign not found' };
  if (campaign.status === 'completed' || campaign.status === 'dispatched') return { success: false, error: 'Campaign already sent' };

  var recipients = db.prepare('SELECT * FROM direct_mail_recipients WHERE campaign_id = ? AND customer_id = ?').all(campaign.id, customerId);
  var provider = getDirectMailProvider();

  // 1. Validate addresses
  var addresses = recipients.map(function(r) { return { name: r.name, company: r.company, address_line1: r.address_line1, city: r.city, postcode: r.postcode, lead_id: r.lead_id, id: r.id }; });
  var validationResult = await provider.validateAddresses(addresses);
  var validAddresses = validationResult.details ? validationResult.details.filter(function(d) { return d.valid; }) : [];
  var recipientCount = validAddresses.length;
  if (recipientCount === 0) return { success: false, error: 'No valid postal addresses in this campaign.' };

  // Load artwork (flyer front/back/letter) from template materials if any
  var template = null;
  if (campaign.template_id) { template = db.prepare('SELECT * FROM direct_mail_templates WHERE id = ? AND customer_id = ?').get(campaign.template_id, customerId); }
  var materialIds = [];
  if (template) {
    if (template.flyer_front_material_id) materialIds.push(template.flyer_front_material_id);
    if (template.flyer_back_material_id) materialIds.push(template.flyer_back_material_id);
    if (template.letter_material_id) materialIds.push(template.letter_material_id);
  }
  var files = [];
  for (var mi = 0; mi < materialIds.length; mi++) {
    var mat = db.prepare('SELECT * FROM direct_mail_materials WHERE id = ? AND customer_id = ?').get(materialIds[mi], customerId);
    if (mat && mat.file_data) files.push({ name: mat.name || 'artwork.' + (mat.file_type === 'pdf' ? 'pdf' : 'png'), file_data: mat.file_data });
  }
  // FALLBACK: if the template had no linked materials (common for My Leads one-click
  // sends where materials are uploaded separately), use the customer's most recent
  // uploaded materials of each type. This guarantees the flyer front/back/letter
  // actually get sent even when the template material columns are empty.
  if (files.length === 0) {
    var fallbackTypes = [['flyer_front','flyer_front'],['flyer_back','flyer_back'],['letter','letter']];
    fallbackTypes.forEach(function(ft) {
      var latest = null;
      try { latest = db.prepare('SELECT id FROM direct_mail_materials WHERE customer_id = ? AND type = ? ORDER BY created_at DESC LIMIT 1').get(customerId, ft[0]); } catch(e) {}
      if (latest) {
        var fm = null; try { fm = db.prepare('SELECT * FROM direct_mail_materials WHERE id = ? AND customer_id = ?').get(latest.id, customerId); } catch(e) {}
        if (fm && fm.file_data) files.push({ name: fm.name || (ft[1] + '.png'), file_data: fm.file_data });
      }
    });
  }
  // Determine mail type: one-click campaigns store it in description; template-based
  // campaigns default to the template type (letter or flyer).
  var mailType = 'letter';
  var mailTypeHint = campaign.description || campaign.notes || '';
  if (mailTypeHint === 'flyer_plus_letter' || /flyer.*letter/i.test(mailTypeHint)) mailType = 'flyer_plus_letter';
  else if (mailTypeHint === 'flyer_a5' || mailTypeHint === 'flyer' || /^flyer$|^flyer_a5$/i.test(mailTypeHint)) mailType = 'flyer';
  // Resolve the chosen print format (id like 'flyer_a5_portrait') from the
  // campaign notes/description so the artwork is sized & sent at the right
  // Stannp size. Falls back to A5-PORT for flyers.
  var chosenFormat = '';
  var fmtHint = String(campaign.notes || '') + ' ' + String(campaign.description || '');
  var fmtMatch = fmtHint.match(/FORMAT:([a-zA-Z0-9_]+)/);
  if (fmtMatch) chosenFormat = fmtMatch[1];

  // Template content (HTML) used when no letter PDF is uploaded
  var templateBody = '';
  if (template && template.ai_generated_text) {
    templateBody = cleanMailText(template.ai_generated_text)
      .replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;').replace(/"/g, '&quot;')
      .replace(/\r?\n/g, '<br>');
  }

  // STANNP path: send each valid recipient as its own mailpiece via the new API.
  if (provider.name === 'stannp') {
    var sentIds = [];
    var failedIds = [];
    var errors = [];
    for (var si = 0; si < validAddresses.length; si++) {
      var rcpt = validAddresses[si].original;
      var pieceFiles = files;
      if (!pieceFiles.length) {
        pieceFiles = [{ name: 'letter.pdf', file_data: '' }];
      }
      // Provide template body as the letter content (replacing placeholders per recipient)
      var rcptWithPages = Object.assign({}, rcpt);
      // Attach a cross-reference tag so Stannp reporting / reporting/list can be
      // matched back to our exact recipient (lead). Stannp stores custom tags per
      // mailpiece and returns them in reporting/list — a reliable fallback to the
      // webhook for reconciling real delivery status.
      rcptWithPages.tags = '9amleads:' + String(rcpt.id).substring(0, 18) + (rcpt.lead_id ? ':' + String(rcpt.lead_id).substring(0, 18) : '');
      if (templateBody) {
        // CLEAN the letter body for print BEFORE rendering: strip the marketing
        // preamble (address block, "Dear...", "5 TYPES OF BUSINESS LEADS",
        // "GET FRESH...", "MORE THAN JUST LEADS"), any unmerged placeholder tokens
        // like "00000 / 0000", and stray duplicated names — the letter should start
        // at the real product/services content. Stannp prints the recipient address
        // itself in the envelope window, so it must not appear in the letter.
        // Look up the customer's business profile for the return address
        var bizP = null;
        try { bizP = db.prepare('SELECT * FROM customer_business_profiles WHERE customer_id = ?').get(customerId); } catch(e) {}
        var senderName = (bizP && bizP.company_name) || (bizP && bizP.contact_name) || '9amLeads';
        var senderAddr = '';
        if (bizP) {
          senderAddr = [bizP.address_line1, bizP.address_line2, bizP.city, bizP.postcode].filter(Boolean).join(', ');
        }
        rcptWithPages.sender = { name: senderName, address: senderAddr };
        var _clean = buildCleanLetterHtml(templateBody || '', senderName, senderAddr);
        // Do NOT insert the recipient address into the letter body — Stannp prints
        // the recipient name + address itself in the envelope window. Inserting it
        // here makes the address appear TWICE on the printed letter.
        rcptWithPages.pages = _clean.html
          .replace(/\[name\]/gi, rcpt.name || '')
          .replace(/\[address\]/gi, '')
          .replace(/\[company\]/gi, rcpt.company || rcpt.name || '');
        // The clean letter BODY (no sender/date) for the A4 PDF layout.
        rcptWithPages.letter_body = _clean.body;
      }
      var pieceResult = await provider.sendMailpiece(mailType, rcptWithPages, pieceFiles, chosenFormat);
      if (pieceResult && pieceResult.success) {
        // A 'flyer_plus_letter' order produces TWO Stannp mailpieces (letter + flyer).
        // Each is tracked as its own recipient row so the customer sees two separate
        // orders with independent live status in their dashboard.
        var pieceIds = (pieceResult.provider_mailpiece_ids && pieceResult.provider_mailpiece_ids.length) ? pieceResult.provider_mailpiece_ids : [pieceResult.provider_campaign_id];
        var pieceTypes = (pieceResult.mailpiece_types && pieceResult.mailpiece_types.length) ? pieceResult.mailpiece_types : ['mailpiece'];
        pieceIds.forEach(function(mid, pi) {
          if (!mid) return;
          sentIds.push(String(mid));
          var pType = pieceTypes[pi] || 'mailpiece';
          var trackingId = (pType === 'flyer') ? uuidv4() : rcpt.id;
          // Live tracking: store the Stannp mailpiece ID against this recipient so
          // webhook/poller status updates can be matched back to the exact lead.
          try {
            if (trackingId === rcpt.id) {
              db.prepare('UPDATE direct_mail_recipients SET provider_mailpiece_id = ?, mailpiece_type = ?, provider_status = ?, updated_at = ? WHERE id = ? AND customer_id = ?').run(String(mid), pType, 'processing', new Date().toISOString(), rcpt.id, customerId);
            } else {
              // Second piece (flyer) → a separate tracked recipient row on the same lead.
              db.prepare('INSERT INTO direct_mail_recipients (id,customer_id,campaign_id,name,company,address_line1,address_line2,city,postcode,country,lead_id,status,provider_mailpiece_id,mailpiece_type,provider_status,created_at,updated_at) VALUES (?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?)').run(trackingId, customerId, campaign.id, rcpt.name || 'Lead', rcpt.company || '', rcpt.address_line1 || '', rcpt.address_line2 || '', rcpt.city || '', rcpt.postcode || '', rcpt.country || 'United Kingdom', rcpt.lead_id || '', 'pending', String(mid), pType, 'processing', new Date().toISOString(), new Date().toISOString());
            }
          } catch(rcptErr) { console.log('[DM-SEND] recipient update failed:', rcptErr.message); }
        });
      } else {
        failedIds.push(rcpt.lead_id);
        if (errors.length < 3) errors.push((pieceResult && pieceResult.error) || 'Send failed');
      }
    }
    var providerCampaignId = sentIds.length ? sentIds.join(',') : '';
    if (sentIds.length === 0) {
      db.prepare('UPDATE direct_mail_campaigns SET status = ?, updated_at = ? WHERE id = ? AND customer_id = ?').run('failed', new Date().toISOString(), campaign.id, customerId);
      db.prepare('INSERT INTO direct_mail_provider_logs (id,customer_id,campaign_id,provider,endpoint,request_body,response_body,status_code,success,error_message,created_at) VALUES (?,?,?,?,?,?,?,?,?,?,?)').run(uuidv4(), customerId, campaign.id, provider.name, 'sendMailpiece', JSON.stringify({ mailType: mailType, recipients: recipientCount }), JSON.stringify({ success: false, errors: errors }), 500, 0, errors.join(' | '), new Date().toISOString());
      return { success: false, error: errors.join(' | ') || 'Stannp send failed' };
    }
    db.prepare('UPDATE direct_mail_campaigns SET status = ?, provider = ?, provider_campaign_id = ?, provider_status = ?, sent_count = ?, updated_at = ? WHERE id = ? AND customer_id = ?').run('sent_to_provider', provider.name, providerCampaignId, 'processing', sentIds.length, new Date().toISOString(), campaign.id, customerId);
    db.prepare('INSERT INTO direct_mail_status_history (id,customer_id,campaign_id,from_status,to_status,changed_by,notes,created_at) VALUES (?,?,?,?,?,?,?,?)').run(uuidv4(), customerId, campaign.id, campaign.status, 'sent_to_provider', 'system', 'Sent to provider: ' + provider.name + ' (IDs: ' + providerCampaignId.substring(0, 60) + ') · Items: ' + sentIds.length, new Date().toISOString());
    db.prepare('INSERT INTO direct_mail_provider_logs (id,customer_id,campaign_id,provider,endpoint,request_body,response_body,status_code,success,error_message,created_at) VALUES (?,?,?,?,?,?,?,?,?,?,?)').run(uuidv4(), customerId, campaign.id, provider.name, 'sendMailpiece', JSON.stringify({ mailType: mailType, recipients: recipientCount, files: files.length }), JSON.stringify({ success: true, ids: sentIds, failures: failedIds.length }), 200, 1, failedIds.length ? (failedIds.length + ' recipients failed') : '', new Date().toISOString());
    // Capture the proof-of-posting PDF from Stannp for the customer's reassurance.
    // We DOWNLOAD the PDF content and store it locally so the proof never expires
    // (Stannp's proof URLs carry an expiry token) and is served from OUR dashboard.
    try {
      var firstId = String(providerCampaignId).split(',')[0];
      var proofRes = await provider.getProofOfPosting(firstId);
      if (proofRes && proofRes.proof_url) {
        var proofPdf = '';
        try {
          proofPdf = await downloadBinary(proofRes.proof_url);
        } catch(pdErr) { console.log('[DM-SEND] Proof PDF download failed:', pdErr.message); }
        db.prepare('UPDATE direct_mail_campaigns SET proof_url = ?, proof_pdf = ?, updated_at = ? WHERE id = ? AND customer_id = ?').run(proofRes.proof_url, proofPdf || '', new Date().toISOString(), campaign.id, customerId);
        saveDb();
        console.log('[DM-SEND] Proof of posting saved for campaign ' + campaign.id.substring(0, 8) + (proofPdf ? ' (PDF stored)' : ' (URL only)'));
      }
    } catch(proofErr) { console.log('[DM-SEND] Proof capture skipped:', proofErr.message); }
    return { success: true, provider: provider.name, provider_campaign_id: providerCampaignId, recipient_count: sentIds.length, message: 'Sent ' + sentIds.length + ' item(s) to our print partner for printing' };
  }

  // MOCK / legacy campaign path
  // 2. Create campaign with provider
  var campaignResult = await provider.createCampaign({ name: campaign.name, recipient_count: recipientCount, description: campaign.description });
  if (!campaignResult || !campaignResult.success) {
    return { success: false, error: (campaignResult && campaignResult.error) || 'Provider rejected campaign' };
  }
  var providerCampaignId = campaignResult.provider_campaign_id;

  // 3. Upload artwork (flyer front/back/letter) from template materials if any
  var artworkResult = await provider.uploadArtwork(providerCampaignId, files);

  // 4. Add recipients to provider campaign
  var addResult = await provider.addRecipients(providerCampaignId, validAddresses.map(function(d) { return d.original; }));

  // 5. Send campaign
  var sendResult = await provider.sendCampaign(providerCampaignId);

  // 6. Update DB
  var finalStatus = sendResult && sendResult.success ? 'sent_to_provider' : 'queued';
  db.prepare('UPDATE direct_mail_campaigns SET status = ?, provider = ?, provider_campaign_id = ?, provider_status = ?, sent_count = ?, updated_at = ? WHERE id = ? AND customer_id = ?').run(finalStatus, provider.name, providerCampaignId, sendResult && sendResult.success ? 'processing' : 'accepted', recipientCount, new Date().toISOString(), campaign.id, customerId);
  db.prepare('INSERT INTO direct_mail_status_history (id,customer_id,campaign_id,from_status,to_status,changed_by,notes,created_at) VALUES (?,?,?,?,?,?,?,?)').run(uuidv4(), customerId, campaign.id, campaign.status, finalStatus, 'system', 'Sent to provider: ' + provider.name + ' (ID: ' + providerCampaignId + ') · Artwork: ' + artworkResult.files + ' · Recipients: ' + (addResult.added || 0), new Date().toISOString());
  db.prepare('INSERT INTO direct_mail_provider_logs (id,customer_id,campaign_id,provider,endpoint,request_body,response_body,status_code,success,error_message,created_at) VALUES (?,?,?,?,?,?,?,?,?,?,?)').run(uuidv4(), customerId, campaign.id, provider.name, 'fullSend', JSON.stringify({ campaign: campaign.name, recipients: recipientCount, files: files.length }), JSON.stringify({ create: campaignResult, artwork: artworkResult, recipients: addResult, send: sendResult }), 200, sendResult && sendResult.success ? 1 : 0, sendResult && sendResult.success ? '' : 'Provider send failed', new Date().toISOString());

  if (!sendResult || !sendResult.success) {
    db.prepare('UPDATE direct_mail_campaigns SET status = ?, updated_at = ? WHERE id = ? AND customer_id = ?').run('failed', new Date().toISOString(), campaign.id, customerId);
    return { success: false, error: (sendResult && sendResult.error) || 'Campaign created but failed to send. Contact support.' };
  }
  return { success: true, provider: provider.name, provider_campaign_id: providerCampaignId, recipient_count: recipientCount, message: 'Campaign sent to ' + provider.name + ' for printing' };
}

// POST /api/direct-mail/campaigns/:id/send — Send campaign to provider (manual)
app.post('/api/direct-mail/campaigns/:id/send', authMiddleware, async (req, res) => {
  try {
    var result = await sendDmCampaign(req.params.id, req.user.id);
    if (!result.success) {
      db.prepare('UPDATE direct_mail_campaigns SET status = ?, updated_at = ? WHERE id = ? AND customer_id = ?').run('failed', new Date().toISOString(), req.params.id, req.user.id);
      return res.status(500).json({ success: false, error: result.error });
    }
    sendDMNotification(req.user.id, 'campaign_sent', '📬 Campaign Sent to Print', 'Your mailing is on its way to the printer',
      '<p>Your mailing "' + (result.campaign_name || '') + '" has been sent to our print partner and will be dispatched shortly.</p><p style="font-size:12px;color:#5a6280">Recipients: ' + result.recipient_count + '</p>',
      'Track Campaign', PUBLIC_URL + '/portal/dashboard.html?page=direct-mail');
    res.json({ success: true, provider: result.provider, provider_campaign_id: result.provider_campaign_id, recipient_count: result.recipient_count, invalid_addresses: 0, total_valid: result.recipient_count, message: result.message });
  } catch(e) { res.status(500).json({ error: e.message }); }
});

// POST /api/direct-mail/campaigns/:id/simulate-status — Simulate provider status update (for testing)
app.post('/api/direct-mail/campaigns/:id/simulate-status', authMiddleware, async (req, res) => {
  try {
    var campaign = db.prepare('SELECT * FROM direct_mail_campaigns WHERE id = ? AND customer_id = ?').get(req.params.id, req.user.id);
    if (!campaign) return res.status(404).json({ error: 'Campaign not found' });
    var provider = getDirectMailProvider();
    var statusResult = await provider.getCampaignStatus(campaign.provider_campaign_id);
    if (!statusResult.success) return res.status(500).json({ error: 'Failed to get status from provider' });
    var newStatus = statusResult.status === 'accepted' ? 'queued' : statusResult.status === 'printing' ? 'printing' : statusResult.status === 'dispatched' ? 'dispatched' : statusResult.status === 'completed' ? 'completed' : 'failed';
    var fromStatus = campaign.status;
    db.prepare('UPDATE direct_mail_campaigns SET status = ?, updated_at = ? WHERE id = ? AND customer_id = ?').run(newStatus, new Date().toISOString(), req.params.id, req.user.id);
    db.prepare('INSERT INTO direct_mail_status_history (id,customer_id,campaign_id,from_status,to_status,changed_by,notes,created_at) VALUES (?,?,?,?,?,?,?,?)').run(uuidv4(), req.user.id, req.params.id, fromStatus, newStatus, 'system', 'Provider status update: ' + (statusResult.message || newStatus), new Date().toISOString());
    res.json({ success: true, from_status: fromStatus, to_status: newStatus, provider_status: statusResult.status });
  } catch(e) { res.status(500).json({ error: e.message }); }
});

// GET /api/direct-mail/campaigns/:id/proof — Get proof of posting
app.get('/api/direct-mail/campaigns/:id/proof', authMiddleware, async (req, res) => {
  try {
    var campaign = db.prepare('SELECT * FROM direct_mail_campaigns WHERE id = ? AND customer_id = ?').get(req.params.id, req.user.id);
    if (!campaign) return res.status(404).json({ error: 'Campaign not found' });
    if (!campaign.provider_campaign_id) return res.status(400).json({ error: 'Campaign has not been sent to a provider yet' });
    // Serve the stored proof PDF directly if we have a local copy (never expires)
    if (campaign.proof_pdf) {
      res.setHeader('Content-Type', 'application/pdf');
      res.setHeader('Content-Disposition', 'inline; filename="proof-of-posting-' + campaign.provider_campaign_id + '.pdf"');
      res.setHeader('Cache-Control', 'private, max-age=3600');
      return res.send(Buffer.from(campaign.proof_pdf, 'base64'));
    }
    // Return the stored proof URL if we captured it at dispatch time
    if (campaign.proof_url) {
      return res.json({ success: true, proof: { success: true, provider_campaign_id: campaign.provider_campaign_id, proof_url: campaign.proof_url, generated_at: campaign.updated_at || new Date().toISOString(), recipient_count: campaign.sent_count || 1, postage_date: campaign.delivery_date || '', estimated_delivery: '' }, cached: true });
    }
    var provider = getDirectMailProvider();
    var proof = await provider.getProofOfPosting(campaign.provider_campaign_id);
    if (!proof.success) return res.status(500).json({ error: 'Failed to get proof of posting' });
    res.json({ success: true, proof: proof });
  } catch(e) { res.status(500).json({ error: e.message }); }
});

// GET /api/direct-mail/lead/:id/proof — Get proof of posting for a LEAD by looking
// up the campaign via the lead's stored post_order_id (Stannp order id).
app.get('/api/direct-mail/lead/:id/proof', authMiddleware, async (req, res) => {
  try {
    var lead = db.prepare('SELECT * FROM leads WHERE id = ? AND customer_id = ?').get(req.params.id, req.user.id);
    if (!lead) return res.status(404).json({ error: 'Lead not found' });
    var ld = {}; try { ld = JSON.parse(lead.data || '{}'); } catch(e) {}
    var orderId = ld.post_order_id || '';
    var campaign = null;
    if (orderId) campaign = db.prepare('SELECT * FROM direct_mail_campaigns WHERE customer_id = ? AND provider_campaign_id LIKE ? ORDER BY created_at DESC LIMIT 1').get(req.user.id, orderId + '%');
    if (!campaign) campaign = db.prepare('SELECT * FROM direct_mail_campaigns WHERE customer_id = ? ORDER BY created_at DESC LIMIT 1').get(req.user.id);
    if (!campaign) return res.status(404).json({ error: 'No campaign found for this lead' });
    if (campaign.proof_pdf) {
      res.setHeader('Content-Type', 'application/pdf');
      res.setHeader('Content-Disposition', 'inline; filename="proof-of-posting.pdf"');
      res.setHeader('Cache-Control', 'private, max-age=3600');
      return res.send(Buffer.from(campaign.proof_pdf, 'base64'));
    }
    if (campaign.proof_url) return res.json({ success: true, proof_url: campaign.proof_url });
    var provider = getDirectMailProvider();
    var proof = await provider.getProofOfPosting(campaign.provider_campaign_id);
    if (!proof.success) return res.status(500).json({ error: 'Proof not available yet' });
    res.json({ success: true, proof_url: proof.proof_url });
  } catch(e) { res.status(500).json({ error: e.message }); }
});

// Get provider campaign status
app.get('/api/direct-mail/campaigns/:id/provider-status', authMiddleware, async (req, res) => {
  try {
    var campaign = db.prepare('SELECT * FROM direct_mail_campaigns WHERE id = ? AND customer_id = ?').get(req.params.id, req.user.id);
    if (!campaign) return res.status(404).json({ error: 'Campaign not found' });
    if (!campaign.provider_campaign_id) return res.status(400).json({ error: 'Campaign has not been sent to a provider yet' });
    var provider = getDirectMailProvider();
    var status = await provider.getCampaignStatus(campaign.provider_campaign_id);
    res.json({ success: true, provider_status: status.status, provider_campaign_id: campaign.provider_campaign_id });
  } catch(e) { res.status(500).json({ error: e.message }); }
});

// POST /api/direct-mail/campaigns/:id/cancel-with-provider — Cancel with provider
app.post('/api/direct-mail/campaigns/:id/cancel-with-provider', authMiddleware, async (req, res) => {
  try {
    var campaign = db.prepare('SELECT * FROM direct_mail_campaigns WHERE id = ? AND customer_id = ?').get(req.params.id, req.user.id);
    if (!campaign) return res.status(404).json({ error: 'Campaign not found' });
    if (!campaign.provider_campaign_id) return res.status(400).json({ error: 'Campaign not sent to provider' });
    var provider = getDirectMailProvider();
    var result = await provider.cancelCampaign(campaign.provider_campaign_id);
    db.prepare('INSERT INTO direct_mail_provider_logs (id,customer_id,campaign_id,provider,endpoint,request_body,response_body,status_code,success,error_message,created_at) VALUES (?,?,?,?,?,?,?,?,?,?,?)').run(uuidv4(), req.user.id, req.params.id, provider.name, 'cancelCampaign', JSON.stringify({ provider_campaign_id: campaign.provider_campaign_id }), JSON.stringify(result), 200, result.success ? 1 : 0, result.error || '', new Date().toISOString());
    if (result.success) {
      db.prepare('UPDATE direct_mail_campaigns SET status = ?, updated_at = ? WHERE id = ? AND customer_id = ?').run('cancelled', new Date().toISOString(), req.params.id, req.user.id);
      db.prepare('INSERT INTO direct_mail_status_history (id,customer_id,campaign_id,from_status,to_status,changed_by,notes,created_at) VALUES (?,?,?,?,?,?,?,?)').run(uuidv4(), req.user.id, req.params.id, campaign.status, 'cancelled', 'customer', 'Cancelled via provider', new Date().toISOString());
    }
    res.json({ success: result.success, message: result.message || (result.success ? 'Cancelled' : 'Failed to cancel'), provider_result: result });
  } catch(e) { res.status(500).json({ error: e.message }); }
});

// POST /api/direct-mail/automation — Save automation settings
app.post('/api/direct-mail/automation', authMiddleware, (req, res) => {
  try {
    var enabled = req.body.enable_auto_send ? 1 : 0;
    if (enabled) {
      if (!req.body.default_template_id) return res.status(400).json({ error: 'Please select a saved template before enabling Print & Post.' });
      if (!req.body.max_daily_spend || parseInt(req.body.max_daily_spend) < 10) return res.status(400).json({ error: 'Please set a minimum daily spend of at least £10.' });
      if (req.body.consent_given !== true && req.body.consent_given !== 1) return res.status(400).json({ error: 'You must approve the consent to enable Print & Post.' });
    }
    var existing = db.prepare('SELECT * FROM direct_mail_automation_settings WHERE customer_id = ?').get(req.user.id);
    var settings = {
      id: existing ? existing.id : uuidv4(),
      customer_id: req.user.id,
      enable_auto_send: enabled,
      lead_types: req.body.lead_types || '',
      postcode_areas: req.body.postcode_areas || '',
      default_template_id: req.body.default_template_id || '',
      mail_type: req.body.mail_type || 'letter',
      max_daily_spend: parseInt(req.body.max_daily_spend) || 0,
      max_monthly_spend: parseInt(req.body.max_monthly_spend) || 0,
      max_letters_per_day: parseInt(req.body.max_letters_per_day) || 0,
      min_leads_before_send: parseInt(req.body.min_leads_before_send) || 1,
      send_timing: req.body.send_timing || 'after_9am',
      pause_on_payment_fail: req.body.pause_on_payment_fail ? 1 : 0,
      pause_on_provider_fail: req.body.pause_on_provider_fail ? 1 : 0,
      pause_on_spend_limit: req.body.pause_on_spend_limit ? 1 : 0,
      avoid_duplicate_mailing: req.body.avoid_duplicate_mailing !== false ? 1 : 0,
      repeat_mailing_days: parseInt(req.body.repeat_mailing_days) || 90,
      consent_given: 0,
      consent_date: '',
      consent_ip: '',
      created_at: existing ? existing.created_at : new Date().toISOString(),
      updated_at: new Date().toISOString()
    };
    if (enabled && req.body.consent_given) {
      settings.consent_given = 1;
      settings.consent_date = new Date().toISOString();
      settings.consent_ip = req.headers['x-forwarded-for'] || req.ip || '';
    }
    if (existing) {
      db.prepare('UPDATE direct_mail_automation_settings SET enable_auto_send=?,lead_types=?,postcode_areas=?,default_template_id=?,mail_type=?,max_daily_spend=?,max_monthly_spend=?,max_letters_per_day=?,min_leads_before_send=?,send_timing=?,pause_on_payment_fail=?,pause_on_provider_fail=?,pause_on_spend_limit=?,avoid_duplicate_mailing=?,repeat_mailing_days=?,consent_given=?,consent_date=?,consent_ip=?,updated_at=? WHERE customer_id=?').run(settings.enable_auto_send, settings.lead_types, settings.postcode_areas, settings.default_template_id, settings.mail_type, settings.max_daily_spend, settings.max_monthly_spend, settings.max_letters_per_day, settings.min_leads_before_send, settings.send_timing, settings.pause_on_payment_fail, settings.pause_on_provider_fail, settings.pause_on_spend_limit, settings.avoid_duplicate_mailing, settings.repeat_mailing_days, settings.consent_given, settings.consent_date, settings.consent_ip, settings.updated_at, req.user.id);
    } else {
      db.prepare('INSERT INTO direct_mail_automation_settings (id,customer_id,enable_auto_send,lead_types,postcode_areas,default_template_id,mail_type,max_daily_spend,max_monthly_spend,max_letters_per_day,min_leads_before_send,send_timing,pause_on_payment_fail,pause_on_provider_fail,pause_on_spend_limit,avoid_duplicate_mailing,repeat_mailing_days,consent_given,consent_date,consent_ip,created_at,updated_at) VALUES (?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?)').run(settings.id, settings.customer_id, settings.enable_auto_send, settings.lead_types, settings.postcode_areas, settings.default_template_id, settings.mail_type, settings.max_daily_spend, settings.max_monthly_spend, settings.max_letters_per_day, settings.min_leads_before_send, settings.send_timing, settings.pause_on_payment_fail, settings.pause_on_provider_fail, settings.pause_on_spend_limit, settings.avoid_duplicate_mailing, settings.repeat_mailing_days, settings.consent_given, settings.consent_date, settings.consent_ip, settings.created_at, settings.updated_at);
    }
    res.json({ success: true, settings: settings, message: enabled ? 'Print & Post enabled' : 'Print & Post disabled' });
  } catch(e) { res.status(500).json({ error: e.message }); }
});

