// ===== LIGHTWEIGHT CONVERSION ANALYTICS =====
// Self-hosted event log (no external platform, no PII). Used to understand the
// visitor → signup → trial → paid funnel. Logged events are capped + viewable
// via the admin analytics endpoint.
function trackAnalytics(event, props) {
  try {
    var db2 = getDb();
    if (!db2.analytics) db2.analytics = [];
    db2.analytics.push({ ts: new Date().toISOString(), event: String(event || '').substring(0, 60), props: props || {} });
    if (db2.analytics.length > 20000) db2.analytics = db2.analytics.slice(-20000);
    saveDb();
  } catch(e) {}
}
app.post('/api/analytics/event', async (req, res) => {
  try {
    var ev = String(req.body.event || '').substring(0, 60);
    var props = req.body.props || {};
    var uid = String(req.body.uid || '').substring(0, 80) || '';
    // Never accept PII; strip anything that looks like contact data.
    var clean = {};
    Object.keys(props).forEach(function(k) {
      var v = String(props[k] || '').substring(0, 80);
      if (!/email|name|phone|address|postcode/i.test(k)) clean[k] = v;
    });
    if (uid) clean._uid = uid;
    trackAnalytics(ev, clean);
    res.json({ ok: true });
  } catch(e) { res.json({ ok: true }); }
});
// GET /api/admin/analytics — conversion funnel dashboard (unique users + rates +
// trial/lead-type/plan performance + zero-lead trials). Supports ?days=1|7|30|0.
app.get('/api/admin/analytics', adminAuth, (req, res) => {
  try {
    var db2 = getDb();
    var allEvents = db2.analytics || [];
    var days = parseInt(req.query.days, 10);
    if (isNaN(days) || days < 0) days = 30;
    var cutoff = days > 0 ? Date.now() - days * 86400000 : 0;
    var events = allEvents.filter(function(e) { return !cutoff || new Date(e.ts || 0).getTime() >= cutoff; });

    var byEvent = {}, byDay = {}, rawCount = {};
    var uidFor = function(e) { return (e.props && (e.props._uid || e.props.uid)) || (e.props && e.props.customer_id) || ''; };
    var unique = {};
    events.forEach(function(e) {
      rawCount[e.event] = (rawCount[e.event] || 0) + 1;
      byEvent[e.event] = (byEvent[e.event] || 0) + 1;
      var d = (e.ts || '').substring(0, 10);
      byDay[d] = byDay[d] || {}; byDay[d][e.event] = (byDay[d][e.event] || 0) + 1;
      var k = uidFor(e); if (k) { if (!unique[e.event]) unique[e.event] = {}; unique[e.event][k] = true; }
    });
    var uniqueCount = function(ev) { return unique[ev] ? Object.keys(unique[ev]).length : 0; };

    var funnelOrder = ['homepage_viewed','trial_cta_clicked','signup_started','signup_completed','trial_activated','lead_viewed','lead_contacted','pricing_viewed','checkout_started','subscription_started'];
    var funnel = [];
    var prevCount = null;
    funnelOrder.forEach(function(ev) {
      var u = uniqueCount(ev);
      var pct = (prevCount !== null && prevCount > 0) ? Math.round((u / prevCount) * 1000) / 10 : null;
      funnel.push({ event: ev, unique: u, raw: rawCount[ev] || 0, fromPrevPct: pct });
      if (u > 0) prevCount = u;
    });
    var overallPct = null;
    var visitors = uniqueCount('homepage_viewed');
    var paid = uniqueCount('subscription_started');
    if (visitors > 0 && paid > 0) overallPct = Math.round((paid / visitors) * 1000) / 10;

    // Trial performance from the customers table
    var customers = [];
    try { customers = db.prepare('SELECT * FROM customers').all() || []; } catch(c2) { customers = []; }
    var now = Date.now();
    var prodNames = { moving: 'Moving', probate: 'Probate', newbusiness: 'New Business', planning: 'Planning', tenders: 'Tenders' };
    var paidPlans = ['starter', 'pro', 'enterprise'];
    var trialStats = { started: 0, active: 0, expired: 0, converted: 0, receivedTotal: 0, viewedTotal: 0, contactedTotal: 0, zeroLead: [] };
    var byProduct = {};
    var byPlan = { starter: { count: 0 }, pro: { count: 0 }, enterprise: { count: 0 } };
    var weeklyValue = { starter: 25, pro: 49, enterprise: 99 };

    customers.forEach(function(c) {
      var trialEnd = c.trial_ends ? new Date(c.trial_ends).getTime() : 0;
      var isTrial = c.plan === 'free_trial';
      var isPaid = paidPlans.indexOf(c.plan) !== -1;
      // Trials started: ever signed up in this window (created_at) — approximate via events.
      var inWindow = !cutoff || (c.created_at ? new Date(c.created_at).getTime() >= cutoff : true);
      var p = c.product || 'moving';
      if (!byProduct[p]) byProduct[p] = { trials: 0, converted: 0, receivedTotal: 0, viewedTotal: 0, contactedTotal: 0 };
      // Trials currently active / expired / converted
      if (isTrial) {
        if (trialEnd > now) trialStats.active++; else trialStats.expired++;
        trialStats.started++;
        if (inWindow) byProduct[p].trials++;
      }
      if (isPaid) {
        trialStats.converted++;
        if (byPlan[c.plan]) byPlan[c.plan].count++;
        if (inWindow) { byProduct[p].converted++; }
      }
      // Average leads delivered during trial (all leads for the account)
      var rec = 0, con = 0;
      try {
        var cs = countLeadStatuses(c.id);
        rec = cs.received; con = cs.engaged;
      } catch(le) {}
      if (isTrial || isPaid) { trialStats.receivedTotal += rec; trialStats.contactedTotal += con; }
      if (inWindow && isTrial) { byProduct[p].receivedTotal += rec; byProduct[p].contactedTotal += con; }
      // Zero-lead trials: trial accounts (active or expired recently) with no leads
      if (isTrial && rec === 0) {
        trialStats.zeroLead.push({
          id: c.id, email: c.email, product: prodNames[p] || p,
          areas: (function(){ try { var a = c.target_areas; if (Array.isArray(a)) return a.join(', '); if (typeof a === 'string') { var j = JSON.parse(a); return Array.isArray(j) ? j.join(', ') : a; } return a || ''; } catch(e) { return ''; } })(),
          trial_start: c.created_at || '', trial_end: c.trial_ends || '',
          days_remaining: trialEnd > now ? Math.ceil((trialEnd - now) / 86400000) : 0,
          allocation: c.leads_per_day || 0
        });
      }
    });

    var trialPct = trialStats.started > 0 ? Math.round((trialStats.converted / trialStats.started) * 1000) / 10 : null;
    // Lead-type breakdown (trials from signup_completed events, converted from subscription_started)
    Object.keys(byProduct).forEach(function(p) {
      var b = byProduct[p];
      b.conversion_pct = b.trials > 0 ? Math.round((b.converted / b.trials) * 1000) / 10 : null;
      b.avg_received = b.trials > 0 ? Math.round((b.receivedTotal / b.trials) * 10) / 10 : 0;
      b.avg_contacted = b.trials > 0 ? Math.round((b.contactedTotal / b.trials) * 10) / 10 : 0;
    });

    // Plan conversion + est weekly subscription value
    var paidTotal = trialStats.converted;
    var weeklyEst = 0;
    Object.keys(byPlan).forEach(function(p) { byPlan[p].pct = paidTotal > 0 ? Math.round((byPlan[p].count / paidTotal) * 1000) / 10 : null; weeklyEst += byPlan[p].count * weeklyValue[p]; });

    // Lightweight warnings (only actual percentages; no invented benchmarks)
    var warnings = [];
    if (trialStats.started >= 10) {
      var signupC = uniqueCount('signup_completed'), signupS = uniqueCount('signup_started');
      if (signupS > 0) {
        var sc = Math.round((signupC / signupS) * 1000) / 10;
        warnings.push({ level: sc < 60 ? 'red' : (sc < 80 ? 'amber' : 'green'), label: 'Signup Completion', pct: sc, note: 'unique users completing signup after starting' });
      }
      if (trialStats.started > 0) {
        var lv = uniqueCount('lead_viewed');
        var le = Math.round((lv / trialStats.started) * 1000) / 10;
        warnings.push({ level: le < 40 ? 'red' : (le < 65 ? 'amber' : 'green'), label: 'Lead Engagement', pct: le, note: 'unique users who viewed leads vs trials started' });
      }
      if (trialPct !== null) {
        warnings.push({ level: trialPct < 5 ? 'red' : (trialPct < 12 ? 'amber' : 'green'), label: 'Trial Conversion', pct: trialPct, note: 'paid / trials started' });
      }
    }

    res.json({
      success: true, total: events.length, days: days, by_event: byEvent, by_day: byDay,
      funnel: funnel, overall_pct: overallPct,
      trials: {
        started: trialStats.started, active: trialStats.active, expired: trialStats.expired,
        converted: trialStats.converted, conversion_pct: trialPct,
        avg_received: trialStats.started > 0 ? Math.round((trialStats.receivedTotal / trialStats.started) * 10) / 10 : 0,
        avg_contacted: trialStats.started > 0 ? Math.round((trialStats.contactedTotal / trialStats.started) * 10) / 10 : 0,
        zero_lead_count: trialStats.zeroLead.length, zero_lead: trialStats.zeroLead.slice(0, 100)
      },
      by_product: byProduct, by_plan: byPlan, weekly_value_est: weeklyEst,
      warnings: warnings, recent: events.slice(-50).reverse()
    });
  } catch(e) { res.status(500).json({ error: e.message }); }
});

// POST /api/admin/delete-customer — remove a customer by email for fresh signup
app.post('/api/admin/delete-customer', adminAuth, (req, res) => {
  try {
    const email = req.body.email;
    if (!email) return res.status(400).json({ error: 'email required' });
    var jsonDb = getDb();
    var cust = (jsonDb.customers || []).filter(function(c) { return c.email === email; })[0];
    if (cust) {
      jsonDb.customers = (jsonDb.customers || []).filter(function(c) { return c.email !== email; });
      jsonDb.leads = (jsonDb.leads || []).filter(function(l) { return cust.id && l.customer_id !== cust.id; });
    }
    saveDb();
    // Delete from SQLite-shim via db.prepare
    var existing = db.prepare('SELECT id FROM customers WHERE email = ?').get(email);
    if (existing) {
      db.prepare('DELETE FROM leads WHERE customer_id = ?').run(existing.id);
      db.prepare('DELETE FROM customers WHERE id = ?').run(existing.id);
    }
    console.log('[ADMIN] Deleted customer ' + email + (existing ? ' (found)' : ' (not in SQLite)') + (cust ? ' (JSON)' : ''));
    res.json({ success: true, message: 'Customer deleted: ' + email });
  } catch(e) { res.status(500).json({ error: e.message }); }
});

// GET /api/admin/backups — list local database backups (hourly snapshots) so a
// mistakenly deleted customer can be recovered from a pre-deletion backup.
app.get('/api/admin/backups', adminAuth, (req, res) => {
  try {
    var files = [];
    try { files = fs.readdirSync(BACKUP_DIR).filter(function(f) { return f.startsWith('database-') && f.endsWith('.json'); }).sort(); } catch(e) {}
    res.json({ success: true, dir: BACKUP_DIR, backups: files.map(function(f) {
      var p = path.join(BACKUP_DIR, f);
      var st = 0; try { st = fs.statSync(p).size; } catch(e) {}
      var ct = 0; try { var raw = JSON.parse(fs.readFileSync(p, 'utf-8')); ct = (raw.customers || []).length; } catch(e) {}
      return { file: f, size: st, customers: ct };
    }) });
  } catch(e) { res.status(500).json({ error: e.message }); }
});

// POST /api/admin/restore-customers — restore specific customers + their leads from a
// backup file into the live DB (merge, keeps current customers). Body:
// { backup_file: 'database-....json', emails: ['a@b.com', ...] }
app.post('/api/admin/restore-customers', adminAuth, (req, res) => {
  try {
    var file = String((req.body && req.body.backup_file) || '').replace(/[^\w\-.]/g, '');
    var emails = (req.body && Array.isArray(req.body.emails)) ? req.body.emails.map(function(e){ return String(e).toLowerCase(); }) : [];
    if (!file || !emails.length) return res.status(400).json({ error: 'backup_file and emails required' });
    var p = path.join(BACKUP_DIR, file);
    if (!fs.existsSync(p)) return res.status(404).json({ error: 'Backup file not found: ' + file });
    var bk = JSON.parse(fs.readFileSync(p, 'utf-8'));
    var db = getDb();
    var restored = 0, skipped = 0;
    (bk.customers || []).forEach(function(c) {
      if (emails.indexOf(String(c.email || '').toLowerCase()) === -1) return;
      var existing = (db.customers || []).find(function(x) { return x.id === c.id || String(x.email || '').toLowerCase() === String(c.email || '').toLowerCase(); });
      if (existing) { skipped++; return; }
      db.customers.push(c); restored++;
    });
    var ids = (bk.customers || []).filter(function(c) { return emails.indexOf(String(c.email || '').toLowerCase()) !== -1; }).map(function(c) { return c.id; });
    // MERGE BACKUP LEADS for existing customers: historical leads that the live DB
    // no longer has (e.g. deleted by a destructive admin cleanup / force-replace
    // reset) are re-added so every customer keeps their full lead history since
    // signup. The customer's CURRENT batch (delivered today) is preserved — a lead
    // already present (same id) is never duplicated, and backup leads marked
    // 'removed' are restored as their ORIGINAL delivered state so they re-appear.
    var leadAdded = 0;
    var todayStr = new Date().toISOString().split('T')[0];
    (bk.leads || []).forEach(function(l) {
      if (ids.indexOf(l.customer_id) === -1) return;
      if ((db.leads || []).some(function(x) { return x.id === l.id; })) return;
      // Restore HISTORICAL leads only (delivered before today). Today's batch is
      // handled separately and must stay at the exact promised count — the backup's
      // today-leads may reflect an over-delivered/duplicate state, so never merge
      // them back in (it would re-inflate "leads today").
      if (l.delivered && l.delivered_at && l.delivered_at.indexOf(todayStr) === 0) return;
      var nl = Object.assign({}, l);
      if (nl.status === 'removed' && nl.delivered) nl.status = 'delivered';
      if (!nl.delivered && nl.delivered_at) { nl.delivered = 1; if (!nl.status) nl.status = 'delivered'; }
      db.leads.push(nl); leadAdded++;
    });
    saveDb();
    res.json({ success: true, restored_customers: restored, skipped: skipped, restored_leads: leadAdded });
  } catch(e) { res.status(500).json({ error: e.message }); }
});

// POST /api/admin/restore-full-db — restore the ENTIRE database from a backup file
// (customers + leads + everything). For disaster recovery when database.json gets
// corrupted/truncated (e.g. a failed write shrank it to a few KB). Body:
// { backup_file: 'database-....json' }
app.post('/api/admin/restore-full-db', adminAuth, (req, res) => {
  try {
    var file = String((req.body && req.body.backup_file) || '').replace(/[^\w\-.]/g, '');
    if (!file) return res.status(400).json({ error: 'backup_file required' });
    var p = path.join(BACKUP_DIR, file);
    if (!fs.existsSync(p)) return res.status(404).json({ error: 'Backup file not found: ' + file });
    var bk = JSON.parse(fs.readFileSync(p, 'utf-8'));
    if (!bk || typeof bk !== 'object') return res.status(500).json({ error: 'Backup is not a valid DB object' });
    var beforeCust = (getDb().customers || []).length;
    var beforeLeads = (getDb().leads || []).length;
    // Also back up the current (corrupt) state first so we never lose the last state.
    try {
      var stamp = new Date().toISOString().replace(/[:T]/g, '-').substring(0, 19);
      var corruptFile = path.join(BACKUP_DIR, 'database-CORRUPT-BEFORE-RESTORE-' + stamp + '.json');
      fs.writeFileSync(corruptFile, JSON.stringify(getDb(), null, 2));
      console.log('[RESTORE] Saved pre-restore (possibly corrupt) state to ' + corruptFile);
    } catch(be) { console.log('[RESTORE] pre-restore backup error:', be.message); }
    // Replace the whole DB with the backup content. Set _dbData directly so getDb()
    // returns the restored data (getDb only reads DB_FILE when _dbData is null).
    _dbData = bk;
    saveDb();
    var afterCust = (getDb().customers || []).length;
    var afterLeads = (getDb().leads || []).length;
    res.json({ success: true, file: file, customers_before: beforeCust, customers_after: afterCust, leads_before: beforeLeads, leads_after: afterLeads });
  } catch(e) { res.status(500).json({ error: e.message }); }
});

// POST /api/admin/purge-demo — remove demo migration accounts only (keeps real signups)
app.post('/api/admin/purge-demo', adminAuth, (req, res) => {
  try {
    const db = getDb();
    const demoIds = (db.customers || []).filter(c => c.source === 'demo-migration').map(c => c.id);
    const beforeCust = db.customers.length;
    const beforeLeads = db.leads.length;
    db.customers = (db.customers || []).filter(c => c.source !== 'demo-migration');
    db.leads = (db.leads || []).filter(l => !demoIds.includes(l.customer_id));
    saveDb();
    res.json({ success: true, removed_customers: beforeCust - db.customers.length, removed_leads: beforeLeads - db.leads.length });
  } catch (e) {
    res.status(500).json({ error: e.message });
  }
});

// GET /api/admin/export — export customers for marketing
app.get('/api/admin/export', adminAuth, (req, res) => {
  const customers = db.prepare(`
    SELECT email, company, contact_name, phone, product, lead_type, business_type, 
           source, plan, marketing_consent, bounced, created_at, last_login
    FROM customers ORDER BY created_at DESC
  `).all();

  // CSV format
  const headers = 'Email,Company,Contact Name,Phone,Product,Lead Type,Business Type,Source,Plan,Marketing Consent,Bounced,Created At,Last Login\n';
  const rows = customers.map(c =>
    [c.email, c.company, c.contact_name, c.phone, c.product, c.lead_type, c.business_type,
     c.source, c.plan, c.marketing_consent, c.bounced, c.created_at, c.last_login].map(v => '"' + (v || '') + '"').join(',')
  ).join('\n');

  res.setHeader('Content-Type', 'text/csv');
  res.setHeader('Content-Disposition', 'attachment; filename=9amleads-customers.csv');
  res.send(headers + rows);
});

// ===== WEBSITE ANALYTICS =====
const analytics = { visits: [], pages: {} };

app.get('/api/track', (req, res) => { try { var dbG = getDb(); if (!dbG.pageviews) dbG.pageviews = []; var when = new Date().toISOString(); dbG.pageviews.push({ id: uuidv4(), visitor: String(req.query.v || req.query.p || '').substring(0,64), path: String(req.query.p || req.path || '/').substring(0,300), referrer: String(req.headers.referer || req.headers.referrer || '').substring(0,300), ua: String(req.headers['user-agent'] || '').substring(0,300), created_at: when }); if (dbG.pageviews.length > 200000) dbG.pageviews.splice(0, dbG.pageviews.length - 200000); saveDb(); } catch(e) {} res.set('Content-Type','image/gif'); res.send(Buffer.from('R0lGODlhAQABAIAAAAAAAP///yH5BAEAAAAALAAAAAABAAEAAAIBRAA7','base64')); });

app.post('/api/track', (req, res) => {
  const { page, referrer } = req.body;
  const ip = req.ip || req.headers['x-forwarded-for'] || 'unknown';
  const visit = { page: page || '/', referrer: referrer || '', ip, time: Date.now(), ua: req.headers['user-agent'] || '' };
  analytics.visits.push(visit);
  if (analytics.visits.length > 10000) analytics.visits.splice(0, 5000);
  if (!analytics.pages[visit.page]) analytics.pages[visit.page] = 0;
  analytics.pages[visit.page]++;
  res.json({ ok: true });
});

app.get('/api/analytics/live', (req, res) => {
  const cutoff = Date.now() - 5 * 60 * 1000;
  const live = analytics.visits.filter(v => v.time > cutoff);
  const uniqueIps = new Set(live.map(v => v.ip));
  res.json({ live: uniqueIps.size, visits5min: live.length, total: analytics.visits.length });
});

app.get('/api/analytics/pages', (req, res) => {
  const sorted = Object.entries(analytics.pages).sort((a, b) => b[1] - a[1]).slice(0, 20);
  res.json(sorted.map(([page, count]) => ({ page, count })));
});

