// POST /api/admin/update-areas - update customer target areas to postcode codes
app.post('/api/admin/update-areas', adminAuth, (req, res) => {
  try {
    var { email, areas, coverage } = req.body;
    if (!email || !areas) return res.status(400).json({ error: 'Email and areas required' });
    var customer = db.prepare('SELECT * FROM customers WHERE email = ?').get(email);
    if (!customer) return res.status(404).json({ error: 'Customer not found' });
    if (coverage) {
      db.prepare('UPDATE customers SET target_areas = ?, coverage = ? WHERE email = ?').run(JSON.stringify(areas), coverage, email);
    } else {
      db.prepare('UPDATE customers SET target_areas = ? WHERE email = ?').run(JSON.stringify(areas), email);
    }
    // SYNC the nested product_config areas so the distributor (which may read the
    // config) never sees stale areas. Update every product's target_areas.
    try {
      var pc = JSON.parse(customer.product_config || '{}');
      Object.keys(pc).forEach(function(p) {
        if (pc[p] && typeof pc[p] === 'object') {
          pc[p].target_areas = JSON.stringify(areas);
          if (coverage) pc[p].coverage = coverage;
        }
      });
      db.prepare('UPDATE customers SET product_config = ? WHERE email = ?').run(JSON.stringify(pc), email);
    } catch(pcErr) { console.log('[update-areas] product_config sync skipped:', pcErr.message); }
    saveDb();
    res.json({ success: true, areas: areas, coverage: coverage || customer.coverage });
  } catch(e) { res.status(500).json({ error: e.message }); }
});

// POST /api/admin/load-test-customers - bulk-create test customers (bypasses the
// signup IP limit and dedup). Body: { customers: [{ product, plan, coverage,
// areas, name, email }] } or { product, plan, coverage, areas, count }.
app.post('/api/admin/load-test-customers', adminAuth, (req, res) => {
  try {
    var list = req.body.customers || [];
    var product = req.body.product, plan = req.body.plan || 'free_trial', coverage = req.body.coverage || 'postcode';
    var areas = req.body.areas || [], count = parseInt(req.body.count) || 1;
    var created = 0;
    if (!list.length && product) {
      for (var i = 0; i < count; i++) {
        var email = 'loadtest.' + product + '.' + Date.now() + '.' + i + '@gmail.com';
        var cid = uuidv4();
        var cfg = {}; cfg[product] = { target_areas: JSON.stringify(areas), coverage: coverage };
        if (product === 'moving') cfg[product].moving_type = 'both';
        db.prepare('INSERT INTO customers (id, email, company, name, plan, product, coverage, target_areas, product_config, password_hash, created_at, signup_ip) VALUES (?,?,?,?,?,?,?,?,?,?,?,?)')
          .run(cid, email, 'LoadTest ' + product + ' ' + i, 'LoadTester', plan, product, coverage, JSON.stringify(areas), JSON.stringify(cfg), 'testhash', new Date().toISOString(), 'loadtest');
        created++;
      }
    } else if (list.length) {
      list.forEach(function(c) {
        var cid = uuidv4();
        var cfg = {}; cfg[c.product] = { target_areas: JSON.stringify(c.areas || []), coverage: c.coverage || 'postcode' };
        if (c.product === 'moving') cfg[c.product].moving_type = 'both';
        db.prepare('INSERT INTO customers (id, email, company, name, plan, product, coverage, target_areas, product_config, password_hash, created_at, signup_ip) VALUES (?,?,?,?,?,?,?,?,?,?,?,?)')
          .run(cid, c.email, c.name || ('LoadTest ' + c.product), 'LoadTester', c.plan || 'free_trial', c.product, c.coverage || 'postcode', JSON.stringify(c.areas || []), JSON.stringify(cfg), 'testhash', new Date().toISOString(), 'loadtest');
        created++;
      });
    }
    saveDb();
    res.json({ success: true, created: created });
  } catch(e) { res.status(500).json({ error: e.message }); }
});

// Global error handler. Persists the last N unhandled errors (with stack) so the
// real cause can be read from /api/health (public) instead of guessing.
global.__lastErrors = global.__lastErrors || [];
// Crash diagnostics: capture uncaught exceptions / rejections and track memory so
// an OOM/SIGABRT crash can be diagnosed from /api/health (Render API has no logs).
global.__memHistory = global.__memHistory || [];
try {
  process.on('uncaughtException', function(err) {
    var msg = String((err && (err.message || err)) || 'uncaughtException');
    global.__lastErrors.push({ at: new Date().toISOString(), url: 'PROCESS:uncaughtException', message: msg, stack: String((err && err.stack) || msg).substring(0, 1200) });
    if (global.__lastErrors.length > 20) global.__lastErrors.shift();
    console.error('[FATAL-EXCEPTION]', msg, (err && err.stack ? '\n' + err.stack.substring(0, 800) : ''));
  });
  process.on('unhandledRejection', function(reason) {
    var msg = String((reason && (reason.message || reason)) || 'unhandledRejection');
    global.__lastErrors.push({ at: new Date().toISOString(), url: 'PROCESS:unhandledRejection', message: msg, stack: String((reason && reason.stack) || msg).substring(0, 1200) });
    if (global.__lastErrors.length > 20) global.__lastErrors.shift();
    console.error('[UNHANDLED-REJECTION]', msg);
  });
  setInterval(function() {
    try {
      var m = process.memoryUsage();
      global.__memHistory.push({ t: new Date().toISOString(), rssMB: Math.round(m.rss / 1048576), heapMB: Math.round(m.heapUsed / 1048576), extMB: Math.round(m.external / 1048576) });
      if (global.__memHistory.length > 120) global.__memHistory.shift();
    } catch(e) {}
  }, 30000);
} catch(e) { console.log('[CRASH-DIAG] monitor init error:', e.message); }
app.use(function(err, req, res, next) {
  var msg = String((err && (err.message || err)) || 'unknown error');
  var stack = String((err && err.stack) || msg);
  global.__lastErrors.push({ at: new Date().toISOString(), url: (req && req.method + ' ' + (req.originalUrl || req.url || '')) || '', message: msg, stack: stack.substring(0, 1200) });
  if (global.__lastErrors.length > 20) global.__lastErrors.shift();
  console.error('[ERROR] Unhandled error:', msg, (err && err.stack ? '\n' + err.stack.substring(0, 800) : ''));
  res.status(500).json({ error: 'Internal server error' });
});

